pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += 15.0 * tightness;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins below mean residual (fill the emptier bins first keeps spread low)?
    // Instead: prefer bins with residual close to item (already captured); add mild
    // penalty for deviating from mean residual to consolidate.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave another tiny dead gap, penalize slightly.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 10.0;
    }

    // New-bin candidate handling: neutral baseline, slightly above good fits
    // but below bins that would create dead space.
    if bin_residual == bin_capacity {
        score = 12.0 + 0.6 * open_bins_count as f64;
        // If the only alternative creates a tiny dead gap, opening a new bin is fine.
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ni = next_item_size as f64;
    let it = item_size as f64;
    let is_new = bin_residual == bin_capacity;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Lookahead: keep room for the next item, stronger early in the stream.
    if next_item_size > 0 && post_residual > 0 {
        if pr >= ni {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            // near-exact chain: residual barely above next item
            if pr - ni < 0.03 * cap {
                score -= 1.5;
            }
            // concavity: prefer residuals that are neither too tight nor too loose
            score -= 0.6 * (pr / cap) * (1.0 - pr / cap);
        } else {
            // dead space: too small for the next item
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            // penalize dead space more when few bins can fit this item
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
            // dead space hurts more early when there's still time to regret it
            score += 0.8 * (ni - pr) / cap * (1.0 - progress);
        }
    }
    // tiny unusable sliver
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits more strongly when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 2.0 * (it / cap);
    } else if !is_new {
        score -= 60.0; // last-chance bin: avoid opening a new bin
    }

    // Balance: penalize deviation from mean residual, softened late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (0.25 - 0.1 * progress) * dev;

    // New-bin candidate: only attractive when no open bin has usable space
    // for this item, or when a fresh bin can host this item AND the next.
    if is_new {
        let usable = mean_residual.max(0.0);
        if open_bins_count > 0 && usable >= it {
            score += 8.0 + 6.0 * (usable / cap);
        } else {
            score += 2.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
