            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
            score += 0.8 * (ni - pr) / cap * (1.0 - progress);
            if fitting_bins_count <= 1 && !is_new {
                score += 1.2;
            }
            if (ni - pr) > 0.5 * mean_residual && !is_new {
                score += 0.7 * (1.0 - progress);
            }
            // nearly-full bin even after failed chain: still worth using
            if pr < 0.05 * cap && !is_new {
                score += 1.4;
            }
            // tight-fit bonus when item nearly fills residual
            if (br - it) / cap < 0.02 {
                score -= 1.0;
            }
            if br / cap < 0.10 && !is_new {
                score -= 0.6;
            }
            // prefer conserving near-empty bins when many are open
            if is_new && open_bins_count > 4 && (ni - pr) / cap < 0.05 {
                score += 0.6;
            }
        }
    }
    // tiny unusable sliver
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits more strongly when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 2.0 * (it / cap);
    } else if !is_new {
        score -= 60.0; // last-chance bin: avoid opening a new bin
    }

    // Balance: penalize deviation from mean residual, softened late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (0.25 - 0.1 * progress) * dev;

    if is_new {
        let usable = mean_residual.max(0.0);
        if open_bins_count > 0 && usable >= it {
            score += 8.0 + 6.0 * (usable / cap);
        } else {
            score += 2.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        score -= (it / cap) * 150.0;
        // fresh bins less attractive for small items when open bins exist
        let fill = it / cap;
        if fill < 0.5 && open_bins_count > 0 {
            score += 3.0 * (0.5 - fill);
        }
        // extra caution against new bins late in the stream
        score += 0.5 * (1.0 - progress) + 1.5 * progress * (open_bins_count as f64).min(10.0) / 10.0;
    }

    // Late in the stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    // Graded tightness bonus — reward placements whose leftover is a
    // small fraction of capacity, scaled by how many alternatives exist.
    if post_residual > 0 {
        let tight = 1.0 - pr / cap;
        score -= 3.0 * tight * tight * (fitting_bins_count as f64).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < 20 && post_residual >= 10 {
        score += 15.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward fitting next item exactly into the gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score += 10.0;
    }

    // Open-bin pressure: prefer fewer open bins when spread is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.25 * progress);

    // Penalize bins deviating from mean residual (keep packing balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are poor.
    if bin_residual == bin_capacity {
        let bad_open = if mean_residual < 25.0 { 1.0 } else { 0.0 };
        score = 60.0 - 45.0 * bad_open + 0.1 * open_bins_count as f64;
    }

    score
}

