    if fitting_bins_count > 3 { score -= 5.0 ; }
    // new-bin candidate: open only under fragmentation pressure
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64 ;
        if frag > 0.35 { score += 40.0 ; } else { score += 5.0 ; }
    }
    // mild tie-break toward fewer open bins
    score += (open_bins_count as f64) * 0.01 ;
    score
}

