        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
        // fallback base penalty for new bin
        score += 30.0 + mean_residual * 0.15;
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-aware tightness: single fitting bin, consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A gap is "dead" if it is too small for even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fill is highly desirable
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity
    score += 25.0 * (post_residual as f64 / bin_capacity as f64);

    // Dead-space penalty scales with how much of the bin is wasted
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 35.0 * (0.1 - waste_ratio) / 0.1;
    }

    // Open-bin pressure: discourage spreading across many bins when few needed
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.8 * bin_pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward if next item fills post_residual nearly exactly
        let next_gap = post_residual - next_item_size;
        if next_gap < 10 {
            score -= 12.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual unusable for the known next item: penalize
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean — placing into a below-mean-residual bin keeps large
    // residuals available for larger future items.
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 6.0 * dev;
    }

    // New-bin candidate: neutral-ish baseline so it's chosen only when
    // open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * open_bins_count as f64 - 10.0 * progress;
        // Allow new bin if no open bin gives a good fit
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

