    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: prefer it only late or when existing bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        score = 55.0
            - progress * 20.0
            - fragmentation * 15.0
            - (open_bins_count as f64) * 0.3;
        if next_item_size > 0 && next_item_size <= pr {
            score -= 10.0;
        }
    }

    // Mild preference for tight fills among open bins.
    score += (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward tight fits, decay bonus for loose fits
            score -= 50.0 - slack.min(60.0) * 0.85;
        } else {
            let waste = (next_item_size - post_residual) as f64;
            // penalize unusable gap more when item nearly fits
            score += if waste <= 10.0 { 40.0 + waste * 1.2 } else { 30.0 + waste * 0.8 };
