    }

    // lookahead: small leftovers are likely dead space; scale penalty by mean residual
    if post_residual > 0 && (post_residual as f64) < mean_residual.max(20.0) * 0.5 {
        score += 10.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // prefer tightest bin when many candidates exist
    if fitting_bins_count > 3 {
        score -= 5.0;
    } else if fitting_bins_count > 1 {
        score -= 2.0;
    }

    // discourage opening a new bin when a decent fit exists,
    // but allow it when all fits are poor (post_residual would be tiny)
    if bin_residual == bin_capacity && post_residual == bin_capacity {
        let poor_fit = post_residual < item_size.saturating_mul(2).max(20) && next_item_size > post_residual;
        if poor_fit {
            score += 10.0 + open_bins_count as f64;
        } else {
            score += 60.0 + open_bins_count as f64 * 2.0;
        }
    }

    // mild preference to keep bins balanced late in the stream
    if step_index * 2 > total_items {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small for the smallest plausible item (<= ~10 units,
    // or <= next_item_size) is "dead" — punish it quadratically.
    let dead_threshold: u32 = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < dead_threshold.min(15) {
        let gap = (dead_threshold.min(15) - post_residual) as f64;
        score += 40.0 + 4.0 * gap * gap;
    }

    // Perfect fit: post_residual == 0 is ideal, strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual sizes that can still accommodate the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.2 * post_residual as f64;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a
    // new bin — reward heavily (unless residual would become pure dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < dead_threshold.min(15) && post_residual > 0 {
            score += 10.0; // still dead space, don't force it
        } else {
            score -= 45.0;
        }
    }

    // New-bin candidate: opening a bin is expensive; penalize it so we only
    // open when existing placements are genuinely bad (large dead-space risk
    // or wasteful residual relative to the item).
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * item_size as f64;
        // Opening a new bin is more attractive early in the stream and when
        // many bins are already open (fragmentation pressure).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        score -= 0.3 * open_bins_count as f64;
        // If the item is huge, keeping it isolated in a fresh bin is fine.
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Open-bins pressure: prefer placements that reduce fragmentation across
    // many open bins; tilt score by mean residual context.
    score += 0.15 * open_bins_count as f64;
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

