}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
        score -= 3.0 * (next_item_size as f64 / cap);
    }

    // Dead space handling.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 120.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Next-item-aware shaping.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            if pr == ni {
                score -= 3.0 * (ni / cap);
            }
            if pr - ni > 0.35 * cap && fitting_bins_count >= 4 {
                score += 0.9;
            }
            if pr - ni < 0.03 * cap {
                score -= 1.5;
            }
            if pr - ni < 0.08 * cap {
                score -= 0.8 * (1.0 - progress);
            }
            if pr - ni < 0.12 * cap && fitting_bins_count >= 3 {
                score -= 0.6;
            }
            if pr - ni > 0.20 * cap && pr - ni < 0.30 * cap && ni < 0.25 * cap {
                score += 0.5 * (1.0 - progress);
            }
            if pr - ni > 0.10 * cap && pr - ni < 0.18 * cap {
                score -= 0.4 * (pr - ni) / cap;
            }
            score -= 0.6 * (pr / cap) * (1.0 - pr / cap);
        } else {
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
            score += 0.8 * (ni - pr) / cap * (1.0 - progress);
            if fitting_bins_count <= 1 && bin_residual < bin_capacity {
                score += 1.2;
            }
            if (ni - pr) as f64 > 0.5 * mean_residual && bin_residual < bin_capacity {
                score += 0.7 * (1.0 - progress);
            }
            if pr < 0.05 * cap && bin_residual < bin_capacity {
                score += 1.4;
            }
            if (br - item_size as f64) / cap < 0.02 {
                score -= 1.0;
            }
            if br / cap < 0.10 && bin_residual < bin_capacity {
                score -= 0.6;
            }
        }
    }

    // Balance around mean residual, softened late in stream.
    let dev = (br - mean_residual).abs();
    score += 0.25 * dev * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate logic: only open when item is large or pair fits.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
        score += 200.0 - big_item_bonus;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        score += 2.5 * (1.0 - progress);
        if item_size as f64 > 0.5 * cap {
            score -= 1.0;
        }
        // Prefer fresh bin when no open bin leaves room for the next item.
        if next_item_size > 0 && fitting_bins_count > 1 && (bin_capacity as u32).saturating_sub(item_size) < next_item_size {
            score += 0.8;
        }
    }

    // Late in stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual below the minimum item size (1) is impossible, but small residuals (< ~30)
    // are unlikely to be filled later, so punish them super-linearly.
    let dead_zone: f64 = 30.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 0.15;
    }

    // Reward tight fits: small post_residual relative to bin capacity gets a bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the next item can exactly fill the post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If the next item fits in the post_residual, mild bonus (keeps chain packing alive).
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If next item cannot fit in the residual, penalize slightly (dead space likely).
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // Open bins pressure: with many open bins, prefer reusing existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual != bin_capacity {
        // Existing bin: subtract pressure so it beats the new-bin candidate.
        score -= pressure * 2.0;
    } else {
        // New-bin candidate: add pressure so it loses when open bins are viable.
        score += pressure * 2.0;
        // Also penalize new bins when mean residual across open bins is large
        // (existing bins have plenty of room).
        score += mean_residual * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids wasting the remaining space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight preference for fuller bins among open bins (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t2 = t * t;

    // Non-linear coupling: post_residual penalized more as stream progresses
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let progress_weight = 1.0 + 2.0 * t2 + t * t2;
    score += progress_weight * pr_norm * pr_norm * cap;

    // Reward tight fits (small post_residual) with smooth exponential-like polynomial
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize if next item cannot fit in post_residual (smooth quadratic)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            let gap = (ns - pr) / cap;
            score += 15.0 * gap * gap * cap;
        } else {
            let slack = (pr - ns) / cap;
            score -= 3.0 * slack * (1.0 - slack);
        }
    }

    // Last-chance bin bonus: only fitting bin, smooth in open_bins_count
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score -= 12.0 * scarcity;
    }

    // New-bin candidate: penalize mildly, more so early in the stream
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - t2);
    }

    // Mean residual divergence: prefer bins close to mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.5 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well does the leftover space
    // align with the small-item granularity? Residuals that are multiples
    // of small denominations are reusable; odd remainders are dead space.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -8.0 // perfect fit, reward strongly
    } else if pr % 10 == 0 {
        -2.0
    } else if pr % 5 == 0 {
        -1.0
    } else if pr < 10 {
        4.0 // tiny unusable sliver
    } else {
        0.5
    };
    score += class;

    // Integer-division threshold: residuals in [10, 20] can host the
    // smallest guaranteed item class; residuals below 10 are nearly dead.
    if pr >= 10 && pr < 20 {
        score -= 1.5;
    } else if pr < 10 {
        score += 3.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // chainability reward, stronger when the chain is tight
            let tightness = (pr - next_item_size) as f64;
            score -= 2.0 - tightness * 0.02;
        } else {
            // next item won't chain here; penalize proportionally to waste
            score += 1.0 + (next_item_size as f64) * 0.01;
        }
        // harmonic class match between next item and residual
        if next_item_size % 10 == 0 && pr % 10 == 0 && pr >= next_item_size {
            score -= 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Prefer it only when existing bins would leave bad classes.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many bins are open
        // and stream is early (future items can fill fresh bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 6.0 - 2.0 * progress;
        score = open_cost + (bin_capacity - item_size) as f64 * 0.05;
        // if existing bins are few, opening is more expensive
        if open_bins_count <= 2 {
            score += 2.0;
        }
        // if next item is large and current item is small, fresh bin keeps
        // big-item bins intact
        if next_item_size > 50 && item_size <= 30 {
            score -= 2.0;
        }
    }

    // Mild normalization: prefer filling bins closer to mean residual usage
    score += (bin_residual as f64 - mean_residual) * 0.02;

    score
}

