        score += 200.0 - big_item_bonus;
        // If the next item also fits nicely in a fresh bin, opening is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
    }

    // Late in the stream: prefer closing bins tightly (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect packing (small dead space).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Reward tight relative fit: item filling a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize creating small, hard-to-use residuals (dead space bands).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // the item would leave a large residual in every fitting bin, or when
    // open bins are already fragmented (high mean residual).
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 18.0;
        // If open bins are fragmented, a fresh bin is more acceptable.
        score -= 0.15 * mean_residual;
        // Early in the stream, fresh bins are cheaper; later, consolidate.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 22.0 * t;
        // If item is large relative to capacity, fresh bin keeps flexibility.
        score -= 0.1 * item_size as f64;
    }

    // Lookahead coupling: if the next item fits exactly into this bin's
    // post-residual, strongly favor this bin (paired packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 14.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here anyway; slight penalty for wasting
            // a residual that could have held it.
            if next_item_size <= bin_residual {
                score += 3.0;
            }
        }
    }

    // Fewer open bins relative to stream length: encourage consolidation.
    let openness = open_bins_count as f64 / (mean_residual / 10.0 + 1.0);
    score += 0.05 * openness;

    // Mild preference for bins whose residual is close to the mean
    // (keeps the bin pool balanced and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: post-residual quality weighted by stream progress
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 8.0 + cube * 12.0) * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * 20.0 * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual
    score += (pr - mean_residual).abs() * 0.15;

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: favor residual that can still host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5);
        } else {
            score += 5.0 * (1.0 - ni / cap);
        }
    }

    // Mild penalty for proliferation of open bins early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual gap: dead space is worse in some classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Classify post_residual by capacity fraction (eighths): gaps in the lowest
    // eighth are nearly unusable dead space; gaps near half are highly usable.
    let frac = pr / cap; // 0..1
    let eighth = (post_residual * 8) / bin_capacity; // integer division class 0..7
    let class_penalty: f64 = match eighth {
        0 => 40.0,                    // tiny gap: dead space
        1 => 18.0,
        2 => 6.0,
        3 => -6.0,                    // ~3/8..1/2: sweet spot
        4 => -10.0,                   // exactly half-like: very reusable
        5 => -4.0,
        6 => 4.0,
        _ => 12.0,                    // nearly full bin: fine, but less flexible
    };
    score += class_penalty;

    // Exact modulo harmony: post_residual divisible by common item sizes (2,4,5,10)
    // makes the gap more likely to be filled exactly later.
    let harmony_bonus: f64 = {
        let p = post_residual;
        let mut h = 0.0;
        if p > 0 {
            if p % 10 == 0 { h -= 8.0; }
            else if p % 5 == 0 { h -= 4.0; }
            else if p % 2 == 0 { h -= 2.0; }
            if p % 20 == 0 { h -= 4.0; }
            if p % 25 == 0 { h -= 3.0; }
        }
        h
    };
    score += harmony_bonus;

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item exactly matches post_residual, strongly prefer.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by how snugly
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this gap: penalize large wasted gaps
            score += 8.0 * (1.0 - (next_item_size as f64 - pr).min(cap) / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= bin_capacity / 4 {
            score -= 25.0; // acceptable squeeze, avoid new bin
        } else {
            score += 10.0; // poor fit, let a fresh bin compete
        }
    }

    // New-bin candidate: brand-new empty bin gets a baseline score of capacity.
    // Encourage using open bins for small items, but a fresh bin is good when
    // the item is large relative to residual or many bins are already open.
    if bin_residual == bin_capacity {
        // baseline: opening a new bin costs ~capacity of potential
        score = cap * 0.85;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // late in the stream, prefer consolidating into open bins
        score += 15.0 * (1.0 - progress);
        // large items start fresh bins happily
        score -= 0.35 * item_size as f64;
        // if open bins are already crowded on average, new bin is fine
        if mean_residual < 25.0 {
            score -= 12.0;
        }
    }

    // Mild preference to keep mean residual balanced: avoid extreme outliers.
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev;

    // Tie-breaker: slight preference for bins with larger residual overall
    // (best-fit already encoded via post_residual; add tiny diversity nudge).
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (best-fit flavor).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize wasting a large residual on a small item when gap is huge.
    let waste_ratio = (post_residual as f64) / (bin_capacity as f64);
    score += 20.0 * waste_ratio * waste_ratio;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 80.0;
        } else if slack < 10 {
            score -= 20.0;
        }
    }
    // If next item would NOT fit in post_residual, this residual is dead for lookahead.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0;
    }

    // Open-bin pressure: discourage opening new bins when many already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good alternative exists.
        score += 25.0 + 30.0 * (open_bins_count as f64 / 20.0).min(1.0);
        if fitting_bins_count > 0 {
            score += 40.0; // strongly prefer existing bins when any fit
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size && fitting_bins_count == 0 {
            score -= 15.0; // fresh bin still useful for lookahead pairing
        }
    } else {
        // Reusing bins is favored; pressure grows with open bins and stream progress.
        score -= 5.0 + 10.0 * ((open_bins_count as f64) / 50.0).min(1.0) + 5.0 * progress;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild alignment with mean residual: prefer bins whose residual tracks the mean
    // (keeps bin pool homogeneous, easier to pack later).
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover exactly fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        if post_residual == next_item_size {
            // Perfect 2-chain: residual consumed by next item.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: gentle reward scaled by slack.
            score -= 20.0 * (1.0 - (post - nxt) / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space,
            // worse when the miss is small (wasted near-fit).
            let miss = nxt - post;
            score += 15.0 * (1.0 - miss / 100.0);
        }

        // Compare post_residual against mean residual: avoid creating outliers.
        score += 0.3 * (post - mean_residual).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Never prefer opening a new bin when a decent fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin attractive only if no open bin leaves a tight leftover.
        score += 10.0;
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            // Pairing potential in a fresh bin.
            score -= 5.0;
        }
    }

    // Late in the stream, prefer tightening residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward near-perfect fits: post residual close to 0 is great.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space, exponentially worse for tiny slivers that nothing fits.
        let dead = post / cap;
        if post_residual < 10 {
            score += 30.0 * (1.0 - dead);
        }
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // good chaining, but prefer tighter chaining
            score -= 15.0 * (nxt / post.max(1.0));
        } else {
            // next item won't fit here; penalize more when the gap left is small
            score += 8.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it mediocre.
    if bin_residual == bin_capacity {
        // Opening new bins early is wasteful; scale with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap * (1.05 - 0.15 * progress);
        // If no open bin can fit the item, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        return score;
    }

    // Prefer bins with below-average residual (tighter bins) for tight packing.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference to fill bins when many bins are open (consolidation).
    score -= 0.05 * open_bins_count as f64 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: post_residual weighted by progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * cap;
    score += 0.8 * coupling;

    // Penalize dead space more as stream progresses (quadratic in progress)
    score += 40.0 * progress * progress * norm_pr;

    // Reward tight fits (low post_residual) with smooth exponential term
    score -= 15.0 * (-(pr / 20.0)).exp();

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: penalize if next item cannot fit in post_residual
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 10.0 + 0.5 * (next_item_size as f64 - pr);
    } else if next_item_size > 0 {
        score -= 5.0;
    }

    // New bin candidate: prefer it only when residuals across open bins are large
    if bin_residual == bin_capacity {
        let spread = (mean_residual - pr).abs();
        score -= 8.0 * (1.0 - progress) - 0.1 * spread;
        score += 5.0 * progress * progress;
    }

    // Mild penalty for too many open bins relative to progress
    score += (open_bins_count as f64).sqrt() * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class post_residual into residue classes modulo small harmonics of capacity.
    // Perfect closures (post_residual == 0) are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: nearly always take it
        return score;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 are
    // more likely to be exactly filled by future items (sizes 1..100 often
    // cluster on multiples of 10 in many streams).
    let mod10 = post_residual % 10;
    score += mod10 as f64 * 1.5; // non-multiple-of-10 dead space is stickier

    // Modulo-5 secondary harmonic: half-decade residuals are semi-usable.
    let mod5 = post_residual % 5;
    score += mod5 as f64 * 0.8;

    // Integer-division thresholds: classify post_residual into usable bands.
    // A residual that can still hold a "typical" mid-size item (>= 20) is
    // valuable; tiny residuals (< 10) are near-dead space.
    if post_residual < 10 {
        score += 25.0; // dead space penalty
    } else if post_residual < 20 {
        score += 8.0;
    } else {
        // residual in [20, 100): usable band, mild reward scaled by size class
        let band = post_residual / 20; // 1..=5 harmonic bands
        score -= band as f64 * 2.0; // larger usable residual slightly favored
    }

    // --- Lookahead coupling: can next_item_size land exactly in this residual? ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // guaranteed future perfect closure
        } else if next_item_size <= post_residual {
            // next item fits here: reward, stronger when the leftover after
            // that second placement is again a multiple of 10 (harmonic chain)
            let two_step = post_residual - next_item_size;
            score -= 15.0;
            if two_step % 10 == 0 && two_step > 0 {
                score -= 10.0;
            }
            if two_step == 0 {
                score -= 40.0;
            }
        } else {
            // next item cannot use this bin's residual: mild penalty scaled
            // by how far off it is, quantized by integer division
            let gap_bands = (next_item_size - post_residual) / 10;
            score += gap_bands as f64 * 3.0;
        }
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; opening a new bin is costly.
        // Reward strongly, but not enough to override a truly terrible fit
        // (dead space < 10 with no lookahead closure).
        let closure = next_item_size > 0 && next_item_size == post_residual;
        if post_residual >= 10 || closure {
            score -= 60.0;
        } else {
            score -= 20.0;
        }
    }

    // --- New-bin candidate handling ---
    // The empty-bin call arrives with bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: moderate, so we only open when
        // existing fits are bad (high residual waste or dead-space classes).
        let mut new_bin_score = 30.0 + 0.25 * (post_residual as f64);
        // If current item is large, filling a fresh bin is efficient.
        if item_size >= 50 {
            new_bin_score -= 10.0;
        }
        // Late in the stream, prefer closing out open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 20.0;
        // If many bins are open and mean residual is high, discourage new bins.
        new_bin_score += (open_bins_count as f64).ln().max(0.0) * 4.0
            + (mean_residual / cap).max(0.0) * 15.0;
        return new_bin_score;
    }

    // --- Mean-residual alignment: prefer bins whose residual is close to the mean
    // (keeps the bin pool homogeneous and predictable for future items). ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // --- Progress-based tightening: as the stream advances, waste matters more ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item (<= ~5)
    // are nearly worthless; amplify their penalty.
    if post_residual <= 5 {
        score += 60.0;
    } else if post_residual < 10 {
        score += 25.0;
    }

    // Dead space relative to the lookahead item: a gap that cannot host the next item
    // is likely to become permanent waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize less).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already small (bins nearly full are fine; many half-empty bins are bad).
    if open_bins_count > 2 {
        score += 0.8 * (open_bins_count as f64 - 2.0);
    }

    // Penalize a brand-new empty bin unless the item is large enough that
    // keeping it whole is worthwhile (large items pair well with a fresh bin).
    if bin_residual == bin_capacity {
        let large_item = item_size >= 60;
        let poor_fit_elsewhere = fitting_bins_count <= 1 && post_residual > 40;
        if large_item || poor_fit_elsewhere {
            score -= 10.0;
        } else {
            score += 45.0;
        }
    }

    // Mild stream-progression coupling: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        score -= 150.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect 2-step chain: post_residual == next_item_size
        if post_residual as u32 == next_item_size {
            score -= 200.0;
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 30.0 * (1.0 - post_residual as f64 / next);
        }
    }

    // Penalize large leftover relative to mean residual (fragmentation)
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer denser bins early; open new bins sparingly as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless post_residual is very clean
        score += 40.0 - 30.0 * progress;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 60.0;
        }
    } else {
        // Reward filling already-open bins more when many bins are open
        score -= 2.0 * open_bins_count.min(20) as f64 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste (dead space relative to capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_ratio * waste_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidates, mild penalty to discriminate between them.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward space.
            score += 4.0 * (1.0 - (bin_residual - next_item_size.min(bin_residual)) as f64 / bin_capacity as f64);
        }
    }

    // Global state: if many open bins with high mean residual, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
        score -= 6.0 * (mean_residual / bin_capacity as f64);
    }

    // Early in stream: be more willing to open new bins (explore); later: consolidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when a fitting bin exists.
        let new_bin_penalty = 20.0 + 30.0 * progress + (item_size as f64 / bin_capacity as f64) * 10.0;
        score += new_bin_penalty;
        if fitting_bins_count == 1 && post_residual >= 0 {
            score += 15.0; // don't open new bin when exactly one open bin fits
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size && post_residual >= next_item_size {
            score -= 25.0; // new bin can host both items
        }
    }

    // Slight preference for bins with lower residual (denser bins first) when ties.
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual (tight packing)
    let mut score = post;

    // Non-linear tightness reward: quadratic coupling of fill fraction with stream progress
    let tightness = (1.0 - fit_ratio).powi(2);
    score -= (1.0 - tightness) * (cap * 0.5) * (0.5 + progress);

    // Smooth penalty for large dead space, amplified late in the stream
    let waste = post / cap;
    score += waste * waste * cap * (0.3 + 0.7 * progress);

    // Next-item compatibility: reward residuals that can host the lookahead item
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 3.0 + 5.0 * (next_item_size as f64 / cap) * (1.0 - progress);
        } else {
            // Dead space that cannot host the next item is penalized smoothly
            let gap = (next_item_size as f64 - post) / cap;
            score += gap * gap * 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.6;
    }

    // New-bin candidate: make it unattractive unless current bin would be nearly empty waste
    if bin_residual == bin_capacity {
        // Opening a new bin is fine only if no open bin fits well
        let crowd = open_bins_count as f64;
        score = cap * (0.9 - 0.15 * (1.0 - progress)) + crowd * 2.0;
        if fitting_bins_count == 0 {
            score -= cap; // forced open
        }
    }

    // Mild preference to spread load when many bins are open with high mean residual
    score -= mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual in [0,10) is "dead space"
    let class: u32 = post_residual / 10;
    match class {
        0 => score -= 12.0,                       // near-perfect fit, strongly reward
        1 => score -= 4.0,                        // small but usable
        2 => score += 1.0,
        3 => score += 2.5,
        4 => score += 4.0,
        5 => score += 5.0,                        // half-empty bin: mediocre
        6 => score += 6.0,
        7 => score += 7.5,
        8 => score += 9.0,
        _ => {}                                   // 90..100 residual (new bin) unchanged
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 10.0 - gap;                  // chain fit: excellent
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize proportionally to wasted potential
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Prefer bins tighter than average (best-fit flavor)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.15;

    // Early stream: be a bit more willing to open bins (spread items)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus mild progress adjustment
        score = cap_f * 0.98 - progress * 5.0;
        if fitting_bins_count == 1 { score += 15.0; }   // never open when it's the only fit
        if next_item_size > 0 && next_item_size <= post_residual { score -= 4.0; }
    } else if progress < 0.2 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10] are nearly unusable
    // for future items (min item size 1, but small gaps fragment capacity).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // worst at post_residual == 1
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 45.0;
    } else {
        // Usable residual: mild reward proportional to how "round" the gap is.
        let gap = post_residual as f64;
        score -= (gap / 20.0).min(8.0);
    }

    // Tight-fit bonus: reward filling most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 25.0 * (fill_ratio - 0.7) / 0.3;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size <= 5 {
            score -= 30.0;
        } else {
            score -= 8.0;
        }
    }
    // Penalize leaving a gap that the next item just barely misses.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit
    // is mediocre; mild linear + quadratic coupling.
    let pressure = (open_bins_count as f64) * 0.6
        + ((open_bins_count as f64).powi(2)) * 0.05;
    score += pressure * (1.0 - fill_ratio);

    // New-bin candidate handling: an empty bin has large post_residual, so it
    // naturally loses to decent fits; add a bias so it only wins when the
    // best available fit would create severe dead space.
    if bin_residual == bin_capacity {
        score += 35.0 + (mean_residual / 10.0).min(10.0);
    }

    // Late-stream consolidation: as the stream progresses, favor closing out
    // existing bins rather than fragmenting.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact match with the next item's size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();

        if post_residual == next_item_size {
            // Perfect pairing: this bin's leftover exactly fits the next item.
            score -= 60.0 + 0.5 * nr;
        } else if post_residual >= next_item_size {
            // Next item still fits here; reward closeness of the match.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            // Bonus if the pair consumes the bin entirely next step.
            if post_residual - next_item_size <= 5 {
                score -= 20.0;
            }
        } else {
            // Dead space: next item cannot use the leftover.
            // Penalize proportionally to how much of the residual is stranded,
            // but less if the item would barely not fit (near-miss).
            let waste = pr / nr;
            score += 25.0 * waste.min(2.0);
        }
    }

    // Penalize very small unusable leftovers (dead space) regardless.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-unattractive so we prefer
    // existing bins unless the fit is poor; attractive only for large items
    // that would leave a clean, large residual elsewhere.
    if bin_residual == bin_capacity {
        // Fresh bin: score ~ its future residual, dampened.
        score = post_residual as f64 * 0.9 + 5.0;
        // Early in the stream, opening bins is cheap; later, discourage spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild coupling with mean residual: prefer bins tighter than average.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of residual consumed by this placement (0..1).
    let fill = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits: subtract proportional to how well the item fills the bin.
    score -= 25.0 * fill * fill;

    // Penalize small dead space left behind that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver -> wasted capacity, but bin is closed anyway
    }
    // Reward closing a bin exactly (perfect fit).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; if post residual is small this is fine (bin closed),
            // if large it becomes a stranded gap.
            let waste_frac = post_residual as f64 / bin_capacity as f64;
            if next_item_size > post_residual && post_residual > 0 {
                score += 12.0 * waste_frac;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current item
    // is large relative to capacity (poor candidate for squeezing into open bins) and the
    // stream still has a long way to go (future items can fill the fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        let horizon = 1.0 - progress;
        // Base penalty so a new bin is only chosen when open bins look bad.
        score += 15.0;
        // Large items early in the stream justify a fresh bin.
        score -= 20.0 * big_item * horizon;
        // If open bins are already quite full on average, a new bin is reasonable.
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score -= 10.0 * mean_fill;
        // If this item cannot leave a useful gap for the next item anywhere, new bin ok.
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0;
        }
    } else {
        // For existing bins, mild penalty if bin is far below mean residual (fragmenting
        // a mostly-empty bin while fuller bins exist is wasteful).
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score += 3.0 * (diff / bin_capacity as f64);
        }
    }

    // Slight preference for using bins that are already heavily committed (consolidation).
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * used;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 + progress * 2.0) - norm_pr * progress;

    let mut score = pr + 40.0 * poly;

    // Penalize tiny post-residuals more strongly later in the stream (dead space).
    let tiny = ((10.0 - norm_pr) / 10.0).max(0.0);
    score += 25.0 * tiny * tiny * (0.5 + progress);

    // Reward tight fits.
    score -= 8.0 * (item_size as f64 / cap) * (1.0 + progress);

    // Last-chance bonus when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).sqrt() * 0.5;

    // Pull toward mean residual to keep bins balanced.
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction band does it land in?
    // Residuals in (0, 10] are nearly dead space -> heavy penalty.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space banding via integer division thresholds (harmonic classes of capacity/8)
    let class = post_residual / (bin_capacity / 8); // 0..8 harmonic class
    score += match class {
        0 => 60.0,                 // post_residual < 12.5 : near-perfect fill, but tiny residue risk
        1 => -8.0,                 // 12.5..25 : good slot for small items
        2 => -15.0,                // 25..37.5 : sweet spot
        3 => -10.0,                // 37.5..50
        4 => 0.0,                  // ~half full
        5 => 6.0,
        6 => 12.0,
        _ => 20.0,                 // mostly empty bin being used -> wasteful
    };

    // Exact modulo harmony: post_residual divisible by common item granularities
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0; // residue aligns with 10-grid, likely reusable
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Odd, non-harmonic residues are harder to fill later
    if post_residual % 2 == 1 && post_residual < 30 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit the post residue harmonically?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or with harmonic residue
            let nxt = next_item_size as f64;
            if (post_residual as u32) % next_item_size == 0 {
                score -= 25.0; // perfect chaining: bin consumed in whole classes
            } else {
                score -= 10.0 * (nxt / cap); // fits, mild reward scaled by size
            }
        } else {
            // next item won't fit here; penalize small residues more (dead space)
            if post_residual < next_item_size / 2 {
                score += 15.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin offers
    // a genuinely harmonic fit.
    if bin_residual == bin_capacity {
        // neutral base for new bin, minus pressure as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
    }

    // Slight global pressure: with many open bins, prefer compacting into existing ones
    score += 0.3 * open_bins_count as f64;

    // Prefer bins whose residual is already below the mean (tighter bins first)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: post-residual quality weighted by stream progress
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 8.0 + cube * 12.0) * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * 20.0 * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual
    score += (pr - mean_residual).abs() * 0.15;

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: favor residual that can still host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni as f64 {
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5);
            // Extra reward when residual is snugly sized for the next item
            if pr - ni as f64 <= 10.0 {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            score += 5.0 * (1.0 - ni / cap);
        }
    }

    // Mild penalty for proliferation of open bins early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // New-bin gating: a fresh empty bin is only attractive when the item
    // is large relative to capacity or open bins are mostly full.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        let crowding = open_bins_count as f64 / (1.0 + progress * 10.0);
        // Penalize new bins when many open bins exist, less so for big items
        score += 4.0 + 18.0 * (1.0 - fill_ratio) + crowding * 0.8;
        // Late in the stream, opening bins is riskier (fewer chances to fill)
        score += progress * 6.0;
    }

    // Discourage leaving residuals that are too small to host typical items
    if pr > 0.0 && pr < mean_residual * 0.35 {
        score += 3.0 * (1.0 - pr / (mean_residual * 0.35 + 1e-9));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = pr as f64;

    // Non-linear polynomial coupling: post-residual quality weighted by stream progress
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 8.0 + cube * 12.0) * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * 20.0 * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual
    score += (pr - mean_residual).abs() * 0.15;

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: favor residual that can still host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as u32 >= next_item_size {
            // Stronger reward when residual leaves a *comfortable* margin for the next item
            let slack = (pr - next_item_size as f64) / cap;
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5);
            score -= slack * 6.0 * (1.0 - progress);
        } else {
            score += 5.0 * (1.0 - ni / cap);
        }
    }

    // New-bin decision: only open a fresh bin when the item is large relative to
    // capacity or the stream is early and open bins are getting fragmented.
    if is_new_bin {
        let item_frac = item_size as f64 / cap;
        // Penalize new bins normally; discount the penalty for large items or
        // when few fitting bins exist (avoids forcing bad fits).
        let mut new_bin_penalty = 12.0;
        if item_frac > 0.6 {
            new_bin_penalty -= 6.0 * (item_frac - 0.6) / 0.4;
        }
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 8.0;
        }
        if progress < 0.5 {
            new_bin_penalty -= 3.0 * (1.0 - 2.0 * progress);
        }
        // Extra pressure against bin proliferation once many bins are open
        new_bin_penalty += (open_bins_count as f64).sqrt() * 1.2;
        score += new_bin_penalty.max(0.0);
    }

    // Mild penalty for proliferation of open bins early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
