    // Non-linear polynomial coupling: post-residual quality weighted by stream progress
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += (quad * 8.0 + cube * 12.0) * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * 20.0 * (0.3 + 0.7 * progress);

    // Penalize dead space deviating from mean residual
    score += (pr - mean_residual).abs() * 0.15;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
