                score -= 30.0;
            }
        } else {
            score += 5.0 * (1.0 - ni / cap);
        }
    }

    // Mild penalty for proliferation of open bins early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 30.0 * progress + (item_size as f64 / cap) * 10.0;
        score += new_bin_penalty;
        // Don't open a new bin when exactly one open bin fits
        if fitting_bins_count == 1 {
            score += 15.0;
