        // Reward opening a new bin that can host both this and the next item
        if next_item_size > 0 && next_item_size >= cap - item_size as f64 && pr >= next_item_size as f64 {
            score -= 25.0;
        }
    }

    // Slight preference for denser bins on ties
    score += 0.05 * (bin_residual as f64 / cap);

    score
}

