    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain match with next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item,
    // scaled by how "valuable" the next item is and by progress.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 12.0 * (ni / cap) * (1.0 - progress * 0.5);
        } else if post_residual > 0 {
            score += 6.0 * (1.0 - ni / cap);
        }
    }

    // Dead space: unusable slivers are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 120.0;
    }

    // Keep residual spread balanced; penalize hoarding bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: strongly favor the only fitting existing bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer existing bins; relax only for large items
    // or when a fresh bin would pair item + next item exactly.
