    let waste_ratio = pr / cap;
    score += 12.0 * waste_ratio * waste_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits in post_residual, reward (scaled by fit tightness).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            let fit_tightness = ni / pr;
            score -= 10.0 * fit_tightness * (1.0 - progress * 0.5);
            if next_item_size == post_residual {
                score -= 20.0; // exact chain fit
            }
        } else {
            // Next item won't fit here; penalize leaving awkward space.
            score += 5.0 * (1.0 - ni / cap);
        }
    }

    // Global state: prefer consolidation when many open bins with high mean residual.
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
        score -= 6.0 * (mean_residual / cap);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 30.0 * progress + (item_size as f64 / cap) * 10.0;
        score += new_bin_penalty;
        if fitting_bins_count == 1 {
            score += 15.0; // don't open new bin when exactly one open bin fits
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size && post_residual >= next_item_size {
            score -= 25.0; // new bin can host both items
        }
        // Only open a fresh bin if the best open-bin fit would be very wasteful.
        if waste_ratio > 0.5 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Slight preference for denser bins on ties.
    score += 0.05 * (bin_residual as f64 / cap);

