    // Scarcity pressure: when few bins can fit the item, favor reusing existing bins
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64) ;
        if bin_residual != bin_capacity {
            score -= 3.0 * scarcity ;
        } else {
            // New-bin candidate: penalize opening a bin unless item is large
            let large = item_size as f64 / cap ;
            score += 6.0 * (1.0 - large) + 2.0 * scarcity ;
        }
    }

    // Avoid leaving many bins with small dead space
    if bin_residual != bin_capacity && pr > 0.0 {
        let waste_ratio = pr / cap ;
        if waste_ratio < 0.1 {
            score -= 2.0 ; // nearly-perfect fill is valuable
        } else if waste_ratio > 0.6 {
            score += 1.5 * waste_ratio ; // discourage leaving large dead space
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
