    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            // deeper lookahead reward when the leftover fits next item snugly
            let snug = 1.0 - ((pr - ni) / cap) ;
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5) * (0.5 + 0.5 * snug) ;
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
        }
    }
    // penalize bins that are nearly full but leave awkward slivers (< next item)
    if post_residual > 0 && next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 2.0 * (1.0 - post_residual as f64 / cap) ;
    }
    // prefer opening a new bin early when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = if open_bins_count > 0 { mean_residual / cap } else { 0.0 } ;
        score -= 3.0 * frag * (1.0 - progress) ;
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
