    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 8.0 * scarcity * (1.0 - pr / cap);

    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as u32 >= next_item_size {
            // Lookahead bonus, slightly stronger early, damped late.
            score -= (10.0 + 4.0 * scarcity) * (ni / cap) * (1.0 - progress * 0.5);
        } else {
            score += 5.0 * (1.0 - ni / cap);
        }
    }

    // Mild penalty for leaving large dead space mid-stream.
    if pr > 0.5 * cap && progress > 0.1 {
        score += 2.0 * (pr / cap - 0.5);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
