    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let res = bin_residual as f64 ;
    let it = item_size as f64 ;
    let mut score = pr ;

    // Reward tight fits: penalize wasted dead space relative to capacity
    let fill_ratio = it / cap ;
    score += 8.0 * fill_ratio * (1.0 - pr / cap) ;

    // Lookahead on next item
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            // next item still fits: reward, stronger early when future matters
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5) ;
            // extra reward for leaving just enough room (snug chain)
            if (pr - ni) as u32 <= item_size / 4 + 2 {
                score -= 3.0 * (1.0 - progress) ;
            }
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
        }
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    // or few bins fit this item (poor fits elsewhere)
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0) ;
        let crowd = open_bins_count as f64 / (1.0 + progress * 20.0) ;
        score = pr - 6.0 * scarcity * (0.5 + progress)
              - 2.0 * (mean_residual / cap).min(1.0) * crowd ;
    }

    // Mild pressure to prefer bins with small residuals overall
    score += 0.05 * (res / cap) * (1.0 - progress) ;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let it = item_size as f64 ;
    let pr = post_residual as f64 ;
    let res = bin_residual as f64 ;
    // base: prefer minimal post residual, with mild fragmentation penalty
    let mut score = pr ;
    // penalize leaving awkward dead space: residual that no typical item can use
    let frag = (pr / cap) * (1.0 - pr / cap) ; // peaks at half-full residual
    score += 6.0 * frag * (1.0 - progress * 0.6) ;
    // lookahead on next item
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            // next item fits: reward, stronger early when slack matters more
            let tight = 1.0 - (pr - ni) / cap ; // reward tight follow-up fit
            score -= (10.0 + 6.0 * tight) * (ni / cap) * (1.0 - progress * 0.5) ;
        } else {
            // next item won't fit here: penalize bins that strand capacity
            score += 5.0 * (1.0 - ni / cap) + 3.0 * (pr / cap) ;
        }
    }
    // scarcity coupling: when few bins can fit this item, prioritize tight fits harder
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64) ;
        score -= scarcity * (res - it) * 0.15 ;
    }
    // prefer bins whose residual is near the stream mean (predictable reuse)
    score += 0.05 * ((pr - mean_residual) / cap).abs() * cap * 0.01 ;
    // new-bin candidate: make empty bins moderately attractive only late in stream
    // or when item is large relative to capacity (avoid premature bin explosion)
    if bin_residual == bin_capacity {
        let large = it / cap ;
        let pressure = open_bins_count as f64 / (1.0 + progress * 10.0) ;
        score += 2.0 + 8.0 * (1.0 - large) - progress * 3.0 - pressure * 0.05 ;
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
