    let it = item_size as f64 ;
    let pr = post_residual as f64 ;
    let res = bin_residual as f64 ;
    // base: minimal post residual dominates
    let mut score = pr ;
    // fragmentation penalty: dead space that sits at awkward mid-range values,
    // stronger early in the stream when consolidation still pays off
    let frag = (pr / cap) * (1.0 - pr / cap) ;
    score += 8.0 * frag * (1.0 - progress * 0.7) ;
    // lookahead on next item, amplified: reward tight follow-up fits,
    // penalize bins that strand capacity the next item could have used
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            let tight = 1.0 - (pr - ni) / cap ;
            score -= (12.0 + 8.0 * tight) * (ni / cap) * (1.0 - progress * 0.4) ;
        } else {
            // next item won't fit: penalize proportional to stranded capacity
            score += 6.0 * (1.0 - ni / cap) + 4.0 * (pr / cap) * (1.0 - progress * 0.5) ;
        }
    }
    // scarcity coupling: when few bins can host this item, reward slack reuse harder
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64) ;
        score -= scarcity * (res - it) * 0.25 ;
    }
    // mild pull toward stream-mean residual for predictable reuse
    score += 0.03 * ((pr - mean_residual) / cap).abs() * cap * 0.01 ;
    // new-bin candidate: keep empty bins unattractive unless item is large or
    // open bins are badly fragmented (mean residual low relative to capacity)
    if bin_residual == bin_capacity {
        let large = it / cap ;
        let pressure = open_bins_count as f64 / (1.0 + progress * 12.0) ;
        score += 3.0 + 10.0 * (1.0 - large) - progress * 4.0 - pressure * 0.08 ;
        // extra deterrent when the current item would leave a clean small residual
        if pr > 0.0 && pr / cap < 0.35 {
            score += 2.0 * (1.0 - pr / cap) ;
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let it = item_size as f64 ;
    let pr = post_residual as f64 ;
    let res = bin_residual as f64 ;
    // base: minimal post residual
    let mut score = pr ;
    // fragmentation penalty: dead space that is awkward (near half capacity)
    let frag = (pr / cap) * (1.0 - pr / cap) ;
    score += 7.0 * frag * (1.0 - progress * 0.7) ;
    // lookahead: reward exact/tight follow-up fits, penalize stranding
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            let slack = (pr - ni) / cap ;
            // combined fine-grained fit: reward tight follow-up, scaled by item size
            score -= (10.0 + 8.0 * (1.0 - slack)) * (ni / cap) * (1.0 - progress * 0.5) ;
            // extra reward if next item exactly fills the bin (perfect compaction)
            if pr as u32 == next_item_size {
                score -= 4.0 * (1.0 - progress) ;
            }
        } else {
            // next item won't fit here: penalize bins whose leftover is unusable
            let waste = if pr < ni { 1.0 } else { 0.0 } ;
            score += 5.0 * (1.0 - ni / cap) + 3.0 * (pr / cap) + 2.0 * waste * (1.0 - progress) ;
        }
    }
    // scarcity: when few bins fit, push hardest toward tightest fit
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64) ;
        score -= scarcity * (res - it) * 0.2 ;
    }
    // mean-residual alignment: mild preference for predictable reuse
    score += 0.05 * ((pr - mean_residual) / cap).abs() * cap * 0.01 ;
    // new-bin candidate: attractive only when item is large, open bins are scarce,
    // or stream is late; otherwise discourage explosion
    if bin_residual == bin_capacity {
        let large = it / cap ;
        let pressure = open_bins_count as f64 / (1.0 + progress * 10.0) ;
        // if next item is also large, opening fresh space is more valuable
        let ni_large = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 } ;
        score += 2.0 + 9.0 * (1.0 - large)
                 - progress * 3.5
                 - pressure * 0.06
                 - 2.0 * ni_large * (1.0 - progress) ;
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;

    // reward tight fits more strongly when few alternatives exist
    if fitting_bins_count > 1 {
        score -= 2.0 * (item_size as f64 / cap) ;
    } else {
        score += 1.5 * (item_size as f64 / cap) ;
    }

    // lookahead: keep room for the next item, stronger early in the stream
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr >= ni as f64 {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap) ;
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
        }
    }

    // discourage opening new bins while usable space remains in the system
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let usable = mean_residual.max(0.0) ;
        if usable >= item_size as f64 {
            score += 8.0 + 6.0 * (usable / cap) ;
        } else {
            score += 2.0 ;
        }
    }

    // mild penalty for leaving large awkward residuals (dead space)
    if pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 0.02 * pr ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Lookahead: if the next item fits in the leftover space, reward
    // proportionally to how much of the residual it uses (tight chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let ni = next_item_size as f64;
        score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: leftover too small for the next item.
        let ni = next_item_size as f64;
        score += 5.0 * (1.0 - ni / cap);
    }

    // Tiny unusable slivers (items are >= 1, but typical items are larger).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild balance term: penalize deviation from mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: base penalty keeps existing bins preferred;
    // relax it when the item is large or pairs well with the next item.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
        score += 200.0 - big_item_bonus;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        // Late in the stream, avoid proliferating open bins.
        score += progress * 40.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
