    if pr == 0.0 {
        score -= 12.0 ;
    } else if pr <= 5.0 {
        score -= 6.0 ;
    }

    // reward tight fits more strongly when few alternatives exist
    if fitting_bins_count > 1 {
        score -= 2.0 * (item / cap) ;
    } else {
