    }

    // lookahead: keep room for the next item, stronger early in the stream
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr >= ni {
            // reward residual that exactly matches next item even more
            let gap = pr - ni ;
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap) ;
            if gap <= 3.0 {
                score -= 3.0 ;
            }
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
        }
    }

    // discourage opening new bins while usable space remains in the system
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let usable = mean_residual.max(0.0) ;
        if usable >= item {
            score += 8.0 + 6.0 * (usable / cap) ;
        } else {
            score += 2.0 ;
        }
        // extra penalty when the next item could use leftover space elsewhere
        if next_item_size > 0 && (usable - item) >= next_item_size as f64 {
