pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Perfect fit: strong reward (bin closed exactly).
    if post_residual == 0 {
        score -= 300.0;
    }

    // Lookahead: reward residuals that still fit the next item well,
    // weighted by how "tight" the fit is and by stream progress.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5);
        } else {
            score += 5.0 * (1.0 - ni / cap);
        }
        // Exact chain match: post residual equals next item => perfect reuse.
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }

    // Dead-space penalty: gap too small for anything useful (min item = 1),
    // but especially too small for the next item.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Mild balance pressure: avoid hoarding space in one bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it expensive by default; relax only when
    // the item is very large or pairs with the next item in a fresh bin.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64 / cap) * 120.0;
        score += 150.0 - big_item;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Late-stream: prefer tight closures / fewer open bins.
    score += progress * 8.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
