    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr >= ni {
            // prefer residuals that also fit the next item, weighted by slack quality
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap) ;
        } else {
            // penalize residuals too small for the next item, more when next item is large
            score += 5.0 * (1.0 - ni / cap) + 0.03 * (ni - pr) ;
        }
    }

    // discourage opening new bins while usable space remains in the system
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let usable = mean_residual.max(0.0) ;
        if usable >= isz {
