    // dead-space penalty: awkward residuals that waste capacity
    if pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 0.02 * pr ;
    }

    // mild preference for bins whose residual stays close to a useful multiple of mean item size
    if fitting_bins_count > 2 {
        score += 0.5 ;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
