    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            // lookahead reward scaled by how many alternatives exist
            let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0) ;
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5) * (1.0 + scarcity) ;
        } else {
            // dead space relative to next item: penalize proportionally
            let gap = (next_item_size - pr as u32) as f64 ;
            score += 5.0 * (1.0 - ni / cap) + 0.05 * gap * (1.0 - progress) ;
        }
