    // mild pressure toward consolidating into few bins
    score += 0.02 * (pr / cap) * (mean_residual / cap).max(0.0) ;

    // new-bin candidate: make empty bins unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { (item_size as f64 / cap).max(0.1) } ;
        score += 15.0 * desperation + 0.5 * (open_bins_count as f64).ln().max(0.0) ;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
