    }

    // discourage opening new bins when reasonable open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 3.0 + 4.0 * progress;
    }

    // mild penalty for residual far from mean (fragmentation avoidance)
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
