pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;

    // Dead-space penalty: residual that is too small to be useful is waste.
    let dead = if pr > 0.0 && pr < 8.0 { (8.0 - pr) * 2.5 } else { 0.0 } ;
    score += dead ;

    // Lookahead: reward bins whose remainder fits the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            // Tighter coupling: bonus scaled by how snugly next item fits.
            let snug = 1.0 - (pr - ni) / cap ;
            score -= 12.0 * (ni / cap) * snug * (1.0 - progress * 0.4) ;
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
        }
    }

    // Prefer concentrated bins when many alternatives exist (avoid fragmenting).
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 0.4 * (bin_residual as f64 / cap) ;
    }

    // Mild penalty for opening a new bin early when open bins still fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + 4.0 * (1.0 - progress) ;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let res = bin_residual as f64 ;
    let it = item_size as f64 ;
    let mut score = pr ;
    // penalize dead space: waste created by this placement
    let waste = res - it ;
    score += 0.35 * (waste / cap) * (1.0 + progress) ;
    // reward tight fits strongly
    if waste as u32 <= 2 { score -= 3.0 ; }
    else if waste as u32 <= 8 { score -= 1.0 ; }
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            // lookahead bonus scaled by slack quality and fitting scarcity
            let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0) ;
            score -= (10.0 + 8.0 * scarcity) * (ni / cap) * (1.0 - progress * 0.5) ;
            // extra reward if post residual leaves a compact usable state
            if pr <= cap * 0.5 { score -= 1.5 * (pr / cap) ; }
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
        }
    }
    // mild pressure against proliferating bins late in stream
    score += 0.02 * open_bins_count as f64 * (pr / cap) ;
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;

    // reward tight fits, stronger when alternatives exist
    if fitting_bins_count > 1 {
        score -= 2.5 * (item_size as f64 / cap) ;
    } else {
        score += 1.0 * (item_size as f64 / cap) ;
    }

    // lookahead: prefer bins that can still hold the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr >= ni {
            score -= (10.0 + 5.0 * (1.0 - progress)) * (ni / cap) ;
        } else {
            // penalize dead space that the next item cannot use,
            // scaled by how much of the residual is wasted
            score += 4.0 * (1.0 - ni / cap) + 0.05 * (pr / cap) * (ni - pr) ;
        }
    }

    // discourage opening new bins while usable space remains in the system
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let usable = mean_residual.max(0.0) ;
        if usable >= item_size as f64 {
            score += 10.0 + 6.0 * (usable / cap) ;
        } else {
            score += 2.0 ;
        }
    }

    // mild penalty for leaving residuals smaller than the next item (fragmentation)
    if pr > 0.0 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 0.03 * pr ;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let used = (bin_capacity - bin_residual) as f64 ;
    let mut score = pr ;

    // reward bins that stay tight: prefer low post residual, weighted by how full the bin already is
    score -= 0.35 * (used / cap) * (cap - pr) * 0.01 ;

    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            // lookahead bonus scaled by how snugly the next item fits the leftover
            let snug = 1.0 - (pr - ni) / cap ;
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5) * (0.5 + snug) ;
        } else {
            // dead space penalty grows late in the stream when leftover can't host next item
            score += 5.0 * (1.0 - ni / cap) + 2.0 * progress * (pr / cap) ;
        }
    }

    // discourage opening a new bin unless almost nothing fits well anywhere
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)) ;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be useful
    // are heavily penalized. Anything below the minimum item size (1..100 stream,
    // but conservatively < 20) is "dead space".
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a bin should only win if the current bin would
    // leave a bad gap. Penalize the fresh bin mildly, more so as many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If lookahead item would fit nicely in the fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Open-bins pressure: discourage scattering across many open bins when the
    // placement is mediocre (post_residual large relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * open_bins_count as f64 * 1.5;

    // Mean-residual coupling: if this bin's post-residual is far below the mean
    // residual, it's consolidating space well.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a gap the next item can't use.
        score += (post_residual as f64) * 0.3;
    }

    // Stream progression: late in the stream, be extra greedy about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= tightness * progress * 10.0;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward bins whose post-fit residual is a "perfect" leftover for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            // Exact fit for next item is golden; scale lookahead by progress
            let exact = if post_residual == next_item_size { 15.0 } else { 0.0 };
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5) + exact;
        } else {
            score += 5.0 * (1.0 - ni / cap);
        }
    }

    // Penalize dead space: residual too small to matter relative to mean residual
    let res = bin_residual as f64;
    if res < mean_residual * 0.5 && bin_residual != bin_capacity {
        score += 3.0 * (1.0 - res / cap);
    }

    // Scarcity: if few bins can fit this item, grab them tightly
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Discourage opening a new bin unless the item is large or stream is late
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score += 8.0 * (1.0 - frac) * (1.0 - progress * 0.7);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item nearly fills the residual.
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= 2.5 * tightness * tightness;

    // 2-step lookahead: strongly reward if the NEXT item fits in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits: reward proportionally to how well it fills post space
            let next_tight = (next_item_size as f64) / (post_residual as f64);
            score -= 3.0 * next_tight;
        } else {
            // next item won't fit: penalize dead space that becomes unusable
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent alternatives exist,
    // unless this item fits very poorly everywhere (handled by tightness above).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_pressure = (item_size as f64) / mean_residual.max(1.0);
        // new bin baseline: slightly above a moderately good fit
        score += 35.0 - 10.0 * progress - 5.0 * avg_pressure;
        // if no open bin can fit at all, opening is inevitable: make it cheap
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (smaller residual than average = bin is more filled).
    if bin_residual != bin_capacity {
        score += 0.3 * ((bin_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
