    let tightness = it / (bin_residual as f64).max (1.0) ;
    score -= 4.0 * tightness * (1.0 + (fitting_bins_count as f64).recip ()) ;
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if post_residual >= next_item_size {
