        } else {
            score += 5.0 * (1.0 - ni / cap) ;
            // penalize dead space that cannot host the next item, scaled by waste ratio
            let dead = pr - (pr % ni) ;
            score += 2.0 * (dead / cap) ;
        }
    }
    // mild bonus for near-full bins late in the stream
    if progress > 0.6 && pr <= cap * 0.05 {
        score -= 1.5 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Strongly reward exact / near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space: residuals too small for any item (min size 1..10 range).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead: if next item can fit into the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Bonus if post residual exactly leaves room for next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins already fit.
        score += 15.0 + 8.0 * (fitting_bins_count as f64);
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many open bins with slack, discourage new bin.
        score += 0.3 * open_bins_count as f64;
    }

    // Global residual pressure: if mean residual is low, conserve space (tight fits matter more).
    let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
    score += 5.0 * mean_tight * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many bins late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with the next item => chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            // Reward leaving just enough room for the next item, scaled by
            // how tight the leftover-for-next fit is and by stream progress.
            let tightness = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 12.0 * (ni / cap) * tightness * (1.0 - progress * 0.4);
        } else {
            // Dead space: residual too small for the next item.
            score += 8.0 * (1.0 - ni / cap) + 60.0;
        }
    }
    if post_residual > 0 && post_residual < 10 {
        score += 80.0; // tiny unusable sliver
    }

    // Mild deviation penalty to keep residual spread balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: keep existing bins preferred, but relax for large
    // items that fit poorly everywhere, or when a fresh bin can chain the
    // next item.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
        score += 200.0 - big_item_bonus;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        // Late in the stream, opening a tight new bin is cheaper than
        // scattering space across many open bins.
        score -= progress * 30.0 * (open_bins_count as f64).sqrt() * 0.05;
    }

    // Late in the stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
