    let mut score = pr ;
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr as u32 >= next_item_size {
            // reward tight future fit; stronger when few alternatives remain
            let tight = 1.0 - ((pr - ni) / cap) ;
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5) * (0.5 + 0.5 * tight) ;
            if fitting_bins_count <= 2 { score -= 4.0 * (ni / cap) ; }
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
        }
    }
    // penalize leaving fragmented residuals (small, unusable gaps)
    if pr > 0.0 && pr < cap * 0.08 { score += 3.0 * (1.0 - pr / (cap * 0.08)) ; }
    // mild preference for keeping some large-residual bins available
    if bin_residual >= 40 { score -= 0.5 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear amplification
    let mut score = post + 18.0 * norm_post * norm_post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; later, tight packing is crucial
    let coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 22.0 * coupling * (1.0 - norm_post) * (1.0 - norm_post);

    // Penalize residuals that can't fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 10.0 * (1.0 - post / nxt) * (1.0 + coupling);
        } else {
            score -= 4.0 * coupling * (nxt / cap);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + coupling);
    }

    // Mild penalty proportional to bin scarcity, encouraging reuse of crowded pools
    score += (open_bins_count as f64) * 0.15;

    // New-bin candidate: penalize slightly so it's chosen only when open bins are bad,
    // with a smooth relaxation late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 + 14.0 * (1.0 - coupling) - 6.0 * norm_post;
    }

    // Small attraction toward bins with residual near the mean (balanced packing)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
