    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: how "usable" is the leftover space?
    // Class residuals into quarters of capacity (harmonic fractions).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let r = post_residual;

    // Perfect fit: heavily reward.
    if r == 0 {
        score -= 1000.0;
    } else if r <= quarter / 2 {
        // Small dead space (<12.5% capacity): good tight fit.
        score -= 40.0;
    } else if r <= quarter {
        score -= 20.0;
    } else if r == half {
        // Half-residual is a harmonic sweet spot: future medium items fit.
        score -= 35.0;
    } else if r >= 3 * quarter {
        // Very large residual: bin still roomy, mild reward for consolidation.
        score -= 10.0;
    }

    // Modulo arithmetic on residual: residuals divisible by common item-size
    // classes (multiples of 5, 10) are more likely to be exactly filled later.
    if r % 10 == 0 {
        score -= 15.0;
    } else if r % 5 == 0 {
        score -= 7.0;
    }

    // Integer-division threshold coupling with the lookahead item.
    if next_item_size > 0 {
        if r >= next_item_size {
            // Next item still fits here: strong bonus (chain two placements).
            score -= 25.0;
            // Exact chain: post_residual equals next item size class.
            if r - next_item_size <= 5 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit in this bin afterwards: penalize slightly,
            // unless this bin is a last-chance bin (fitting_bins_count == 1).
            if fitting_bins_count > 1 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // reward strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: opening a fresh bin should only win when the item
    // fits poorly everywhere else. Base penalty keeps it behind good fits.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Late in the stream, slightly discourage proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // But if mean residual of open bins is very low (all nearly full),
        // a new bin is natural: reduce the penalty.
        if mean_residual < 10.0 {
            score -= 60.0;
        }
    }

    // Mild preference to fill bins with below-average residual (balance avoidance):
    // tighter bins first keeps many mid-size residuals open.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Tiny penalty for creating awkward residuals in the "gap" harmonic zone
    // (just above quarter, e.g. 26..40), where few item sizes 10..80 fit well.
    if r > quarter && r < half - 5 {
        score += 6.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let res = bin_residual as f64 ;
    let mut score = pr ;
    // penalize dead space: residual that stays after placement
    let dead_ratio = (res - item_size as f64) / cap ;
    score += 3.0 * dead_ratio * dead_ratio * cap / 100.0 ;
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr >= ni as f64 {
            // lookahead bonus scaled by how snugly the next item fits
            let snug = 1.0 - (pr - ni) / cap ;
            score -= 10.0 * (ni / cap) * (1.0 - progress * 0.5) * (0.5 + snug) ;
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
        }
    }
    // prefer bins with fewer competing candidates when fit is loose
    if fitting_bins_count > 1 && (bin_residual - item_size) > bin_capacity / 4 {
        score += 1.5 * (fitting_bins_count as f64).ln() ;
    }
    // new-bin candidate: keep it unattractive unless item is large and no snug open bin exists
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (item_size as f64 / cap) * (1.0 - progress) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        // Small gaps (10..20) are only usable by tiny items; heavy penalty.
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 150.0;
    } else {
        // Usable residual: mild reward proportional to how large it stays.
        score -= 10.0;
    }

    // Tight-fit reward: the smaller the item relative to the gap, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement (enables a perfect closure next step).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // This placement strands the next item elsewhere; mild penalty.
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // as open_bins_count grows, penalize placements that leave large gaps.
    let pressure = open_bins_count as f64 / 10.0;
    score += pressure * post_residual as f64 * 0.5;

    // New-bin candidate calibration: an empty bin has residual == capacity,
    // i.e. post_residual == 100 - item_size, a large gap. Only allow opening
    // a new bin when no open bin offers a decent fit (mean residual small)
    // or the current item would create dead space everywhere.
    if bin_residual == bin_capacity {
        let waste_here = post_residual as f64;
        // Penalize new bins when existing bins already have slack.
        score += 120.0 + 0.8 * mean_residual;
        // But if the item is large relative to typical residual, opening
        // a fresh bin can be right: reduce the penalty.
        if item_size as f64 > mean_residual {
            score -= 90.0;
        }
        // Late in the stream, avoid opening bins that strand big gaps.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * waste_here;
    }

    score
}

