pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain match with next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward
    // proportionally to its size (bigger chain fill = better).
    if next_item_size > 0 && post_residual >= next_item_size {
        let ni = next_item_size as f64;
        score -= 12.0 * (ni / cap) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap unusable for next item: penalize more for large wasted gaps.
        let ni = next_item_size as f64;
        score += 8.0 + 60.0 * (1.0 - ni / cap);
    }

    // Tiny unusable sliver (min item size 1..=100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild balance term only early on; drop it late to allow tight closing.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev * (1.0 - progress);

    // Last-chance bin: strongly favor the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate logic: open a fresh bin only when the item is large
    // relative to capacity AND no open bin wastes little space, or when the
    // fresh bin can chain the next item.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
        score += 200.0 - big_item_bonus;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        // Late stream with many open bins: discourage opening yet another bin.
        if progress > 0.7 && open_bins_count > 3 {
            score += 40.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Late stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

