    // penalize brand-new empty bins so we only open when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress) ;
        if fitting_bins_count <= 1 { score -= 9.0 ; }
    }
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr >= ni {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap) ;
            if pr == ni { score -= 3.0 * (ni / cap) ; }
            if pr - ni < 0.03 * cap { score -= 1.5 ; }
            if pr - ni < 0.06 * cap { score -= 0.7 ; }
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
            score += 0.02 * pr ;
            if (ni - pr) / cap > 0.15 { score += 1.0 ; }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64) . min (3.0) ;
            // lookahead: prefer bins whose leftover stays far above next_item
            if pr - ni >= ni as f64 * 1.2 { score -= 0.8 ; }
        }
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
