            // extra penalty when the leftover cannot even fit a small item
            if pr < 5.0 { score += 1.2 ; }
        }
    }
    // discourage opening a new bin unless open bins are genuinely poor fits
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 2.0 + 3.0 * (1.0 - progress) ;
