}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let mut score = pr ;
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr >= ni {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap) ;
            if pr == ni { score -= 3.0 * (ni / cap) ; }
            let gap = pr - ni ;
            if gap < 0.03 * cap { score -= 1.5 ; }
            // penalize leaving a large awkward remainder that few items can use
            if gap > 0.25 * cap { score += 0.6 * (gap / cap - 0.25) ; }
            // reward bins whose remainder stays usable for the mean-size item
            if gap >= mean_residual * 0.5 && gap > 0.0 { score -= 0.4 ; }
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
            score += 0.02 * pr ;
            if (ni - pr) / cap > 0.15 { score += 1.0 ; }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64) . min (3.0) ;
            // extra penalty when this bin would strand most of its space
            if pr / cap < 0.1 { score += 1.2 ; }
        }
    }
    // discourage opening a new bin early when open bins can still fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 2.0 + 3.0 * (1.0 - progress) ;
        if fitting_bins_count > 1 { score += 1.0 ; }
    } else if bin_residual == bin_capacity {
        score -= 0.5 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: how well does the next item fit into the post-residual?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // Next item fits: reward tight chaining.
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            if pr == ni {
                score -= 500.0; // exact chain match
            }
            if pr - ni < 0.03 * cap {
                score -= 1.5; // nearly-perfect chain
            }
        } else {
            // Next item won't fit here: penalize leaving a dead gap.
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            // More fitting alternatives => less need to keep this bin tidy.
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
        }
    }

    // Tiny unusable sliver penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild balance term (weaker than parent to favor tight fits).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Last-chance bin: only fitting bin => strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: keep existing bins preferred, but relax when the
    // item is large or when a fresh bin could chain with the next item.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
        score += 200.0 - big_item_bonus;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        // Late in the stream, opening a fresh bin for a big item is fine.
        if progress > 0.7 && item_size as f64 > 0.5 * cap {
            score -= 40.0;
        }
    }

    // Late-stream pressure to close bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match with the next item => chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // Reward leaving a gap that fits the next item, scaled by its size
            // and stronger early in the stream (more future to exploit).
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            // Reward a snug-but-not-exact fit for the next item.
            if pr - ni < 0.03 * cap {
                score -= 1.5;
            }
        } else {
            // Post-residual unusable for next item: penalize proportionally
            // to how badly it misses, more when few alternatives exist.
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
        }
    }

    // Dead space: tiny slivers are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward bins whose residual is close to mean (keep spread balanced),
    // penalize bins that deviate strongly upward (hoarding space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre reason.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when item is large relative to
    // typical residuals (i.e., poor fit everywhere). Base penalty keeps
    // existing bins preferred; relax it for big items.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
        score += 200.0 - big_item_bonus;
        // If the next item also fits nicely in a fresh bin, opening is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        // Late in the stream, opening new bins is more costly: fewer open
        // bins and tighter packing matter more.
        score += progress * 40.0;
    }

    // Late in the stream: prefer closing bins tightly (fewer open bins).
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
