            if pr == ni { score -= 3.0 * (ni / cap) ; }
            if pr - ni < 0.03 * cap { score -= 1.5 ; }
            // reward bins whose leftover after this item is small relative to mean residual
            if pr < mean_residual + 0.05 * cap { score -= 0.4 * (1.0 - progress) ; }
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
            score += 0.02 * pr ;
            if (ni - pr) / cap > 0.15 { score += 1.0 ; }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min (3.0) ;
            // penalize wasting a nearly-full bin on an item that leaves a big hole
            if res / cap > 0.75 && (ni - pr) / cap > 0.25 { score += 1.2 ; }
        }
    }
    // new-bin candidate: discourage unless few fitting bins or residual would be badly fragmented
    if bin_residual == bin_capacity {
        let ni = next_item_size as f64 ;
        let tight = fitting_bins_count as f64 ;
        let mut penalty = 2.0 ;
        if tight <= 1.0 { penalty -= 1.5 ; }
        if ni > 0.0 && (ni / cap) > 0.6 { penalty -= 0.8 ; }
        if progress > 0.5 { penalty -= 0.3 ; }
        score += penalty ;
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let progress = step_index as f64 / total_items as f64 ;
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let res = bin_residual as f64 ;
    let mut score = pr ;
    // penalize dead space: if post_residual is small but nonzero, it's wasted
    if pr > 0.0 && pr < 0.02 * cap {
        score += 2.0 * (1.0 - pr / (0.02 * cap)) ;
    }
    if next_item_size > 0 {
        let ni = next_item_size as f64 ;
        if pr >= ni {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap) ;
            if pr == ni {
                score -= 3.0 * (ni / cap) ;
            }
            if pr - ni < 0.03 * cap {
                score -= 1.5 ;
            }
            // reward leaving room for the item after next when slack allows
            if pr - ni > 0.25 * cap {
                score -= 0.8 * (pr - ni) / cap ;
            }
        } else {
            score += 5.0 * (1.0 - ni / cap) ;
            score += 0.02 * pr ;
            if (ni - pr) / cap > 0.15 {
                score += 1.0 ;
            }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min (3.0) ;
            // extra penalty when many bins fit: prefer spreading to keep slack balanced
            if fitting_bins_count > 2 && res > 0.5 * cap {
                score += 0.6 ;
            }
        }
    }
    // new-bin candidate: discourage opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && (next_item_size as f64) > 0.9 * cap
            || fitting_bins_count == 0 ;
        score += if poor_fit { -1.0 } else { 3.0 + 2.0 * (1.0 - progress) } ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ni = next_item_size as f64;
    let it = item_size as f64;
    let is_new = bin_residual == bin_capacity;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Lookahead: keep room for the next item, stronger early in the stream.
    if next_item_size > 0 && post_residual > 0 {
        if pr >= ni {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            // near-exact chain: residual barely above next item
            if pr - ni < 0.03 * cap {
                score -= 1.5;
            }
        } else {
            // dead space: too small for the next item
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            // penalize dead space more when few bins can fit this item
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
        }
    }
    // tiny unusable sliver
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits more strongly when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 2.0 * (it / cap);
    } else if !is_new {
        score -= 60.0; // last-chance bin: avoid opening a new bin
    }

    // Balance: penalize deviation from mean residual, softened late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (0.25 - 0.1 * progress) * dev;

    // New-bin candidate: only attractive when no open bin has usable space
    // for this item, or when a fresh bin can host this item AND the next.
    if is_new {
        let usable = mean_residual.max(0.0);
        if open_bins_count > 0 && usable >= it {
            score += 8.0 + 6.0 * (usable / cap);
        } else {
            score += 2.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        // big items pack better into fresh bins
        score -= (it / cap) * 150.0;
    }

    // Late in the stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    // NEW: graded tightness bonus — reward placements whose leftover is a
    // small fraction of capacity, scaled by how many alternatives exist.
    if post_residual > 0 {
        let tight = 1.0 - pr / cap;
        score -= 3.0 * tight * tight * (fitting_bins_count as f64).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in small
    // "dead-zone" classes (residual < smallest item) are effectively closed.
    if post_residual < 10 {
        score -= 60.0; // perfect closure, near-zero waste
    } else {
        // classify residual by integer division into harmonic slots of 10
        let slot = post_residual / 10;
        // reward residuals that are multiples of 10 (clean slots, likely reusable)
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        // deeper slots (smaller residual) are better
        score -= (10 - slot.min(10)) as f64 * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: penalize leaving large unusable residue
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fit is terrible and many bins are open with little room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = mean_residual / cap;
        score = cap * 0.9 + open_bins_count as f64 * 0.5 + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing fits anywhere: new bin is necessary
        }
        if tightness < 0.15 {
            score += 25.0; // open bins nearly full, discourage new bin slightly less
        }
    }

    // Mild penalty for bins far below mean residual (fragmentation risk)
    if (post_residual as f64 - mean_residual).abs() > cap * 0.5 {
        score += 5.0;
    }

    // Slight preference for fuller bins overall
    score -= (1.0 - post_residual as f64 / cap) * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // A gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps that only fit tiny items are semi-dead.
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement creates a perfect chain -> strong reward.
    if next_item_size > 0 {
