pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // Chain placement: leave room for the next item.
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            if pr == ni {
                score -= 500.0; // exact 2-step chain
            }
            if pr - ni < 0.03 * cap {
                score -= 1.5; // tight follow-up fit
            }
            // Concavity bonus: prefer filling bins to mid-range residuals.
            score -= 0.6 * (pr / cap) * (1.0 - pr / cap);
            if pr - ni < 0.08 * cap {
                score -= 0.8 * (1.0 - progress);
            }
            if pr - ni < 0.12 * cap && fitting_bins_count >= 3 {
                score -= 0.6;
            }
        } else {
            // Dead space for the next item.
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
            score += 0.8 * (ni - pr) / cap * (1.0 - progress);
            if fitting_bins_count <= 1 && bin_residual < bin_capacity {
                score += 1.2;
            }
            if (ni - pr) as f64 > 0.5 * mean_residual && bin_residual < bin_capacity {
                score += 0.7 * (1.0 - progress);
            }
        }
    }

    // Tiny unusable sliver penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild balance pressure toward mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: keep expensive unless item is large or pairs with next item.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
        score += 200.0 - big_item_bonus;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        // Late in stream with many bins open, a fresh bin is less harmful.
        score -= progress * (open_bins_count as f64).sqrt() * 0.5;
    }

    // Late-stream closure pressure.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

