    }
    // tiny unusable sliver
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits more strongly when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 2.0 * (it / cap);
    } else if !is_new {
