            if br / cap < 0.10 && !is_new {
                score -= 0.6;
            }
            if is_new && open_bins_count > 4 && (ni - pr) / cap < 0.05 {
                score += 0.6;
            }
            // penalize leaving this bin nearly unusable for the next item
            let dead = (ni - pr) / cap;
            if dead < 0.05 && dead > 0.0 && !is_new {
                score += 0.9 * (1.0 - progress);
            }
        }
    }
    // tiny unusable sliver
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits more strongly when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 2.0 * (it / cap);
    } else if !is_new {
        score -= 60.0; // last-chance bin: avoid opening a new bin
