    // small fraction of capacity, scaled by how many alternatives exist.
    if post_residual > 0 {
        let tight = 1.0 - pr / cap;
        score -= 3.0 * tight * tight * (fitting_bins_count as f64).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let is_new = bin_residual == bin_capacity;
