    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
        score -= 3.0 * (next_item_size as f64 / cap);
    }

    // Dead space handling.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 120.0;
    }
    if post_residual > 0 && post_residual < 10 && !is_new {
        score += 80.0;
    }

    // Next-item-aware shaping.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            if pr == ni {
                score -= 3.5 * (ni / cap);
                if progress > 0.5 {
                    score -= 0.5;
                }
            }
            if pr - ni > 0.35 * cap && fitting_bins_count >= 4 {
                score += 0.9;
            }
            if pr - ni < 0.03 * cap {
                score -= 1.7;
            }
            if pr - ni < 0.08 * cap {
                score -= 0.9 * (1.0 - progress);
            }
            if pr - ni < 0.12 * cap && fitting_bins_count >= 3 {
                score -= 0.6;
            }
            if pr - ni > 0.20 * cap && pr - ni < 0.30 * cap && ni < 0.25 * cap {
                score += 0.5 * (1.0 - progress);
            }
            if pr - ni > 0.10 * cap && pr - ni < 0.18 * cap {
                score -= 0.45 * (pr - ni) / cap;
            }
            score -= 0.6 * (pr / cap) * (1.0 - pr / cap);
            // snug residual lookahead: reward bins whose slack stays tight
            let slack = pr - ni;
            if slack > 0.0 {
                let snug = 1.0 - (slack / cap).min(1.0);
                score -= 0.35 * snug * (1.0 - progress);
            }
            if br / cap < 0.06 && !is_new {
                score -= 0.8;
            }
            if pr / cap < 0.05 && !is_new {
                score -= 0.5 * (1.0 - progress);
            }
        } else {
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
            score += 0.8 * (ni - pr) / cap * (1.0 - progress);
            if fitting_bins_count <= 1 && !is_new {
                score += 1.2;
            }
            if (ni - pr) as f64 > 0.5 * mean_residual && !is_new {
                score += 0.7 * (1.0 - progress);
            }
            if pr < 0.05 * cap && !is_new {
                score += 1.4;
            }
            if (br - item_size as f64) / cap < 0.02 {
                score -= 1.0;
            }
            if br / cap < 0.10 && !is_new {
                score -= 0.6;
            }
            if is_new && open_bins_count > 4 && (ni - pr) / cap < 0.05 {
                score += 0.6;
            }
            // penalize leaving this bin unusable for the next item when residual is tiny
            let dead = (ni - pr) / cap;
            if dead < 0.05 && dead > 0.0 && !is_new {
                score += 0.9 * (1.0 - progress);
            }
        }
    }

    // Balance around mean residual, softened late in stream.
    let dev = (br - mean_residual).abs();
    score += 0.25 * dev * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && !is_new {
        score -= 60.0;
    }

    // New-bin candidate logic: only open when item is large or pair fits.
    if is_new {
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
