                score -= 1.0;
            }
            if br / cap < 0.10 && !is_new {
                score -= 0.6;
            }
            if is_new && open_bins_count > 4 && (ni - pr) / cap < 0.05 {
                score += 0.6;
            }
            // penalize leaving this bin unusable for the next item when its residual is tiny
            let dead = (ni - pr) / cap;
            if dead > 0.0 && dead < 0.05 && !is_new {
                score += 0.9 * (1.0 - progress);
            }
        }
    }
    // tiny unusable sliver
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits more strongly when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 2.0 * (it / cap);
    } else if !is_new {
        score -= 60.0; // last-chance bin: avoid opening a new bin
    }

    // Balance: penalize deviation from mean residual, softened late.
    let dev = (br - mean_residual).abs();
    score += (0.25 - 0.1 * progress) * dev;

    if is_new {
        let usable = mean_residual.max(0.0);
        if open_bins_count > 0 && usable >= it {
            score += 8.0 + 6.0 * (usable / cap);
        } else {
            score += 2.5 * (1.0 - progress);
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        score -= (it / cap) * 150.0;
        if it > 0.5 * cap {
            score -= 1.0;
        }
    }

    // Late in the stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    // Graded tightness bonus — reward placements whose leftover is a
    // small fraction of capacity, scaled by how many alternatives exist.
    if post_residual > 0 {
        let tight = 1.0 - pr / cap;
        score -= 3.0 * tight * tight * (fitting_bins_count as f64).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let fit_norm = item_size as f64 / cap;

    // Base: post residual, mildly damped
    let mut score = post * (1.0 - 0.25 * norm_post);

    // Smooth polynomial coupling: small post-residuals get progressively penalized
    // as the stream progresses (dead space matters more later).
    let dead_penalty = norm_post * norm_post * (0.5 + 2.0 * progress);
    score += dead_penalty * cap;

    // Reward tight fits (small post residual) more strongly early on
    let tight_reward = (1.0 - norm_post).powi(3) * (1.0 - progress) * 8.0;
    score -= tight_reward;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * (1.0 - progress);
    }

    // If next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 6.0 * (1.0 - gap).powi(2);
        } else {
            // penalize post residuals that waste most space relative to next item
            score += 3.0 * (1.0 - (nxt / cap)).max(0.0);
        }
    }

    // Deviation from mean residual: prefer bins whose leftover is typical (smooth quadratic)
    score += 0.15 * (post - mean_residual) * (post - mean_residual) / cap;

    // Slight preference for consolidating into fewer bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post) * 0.5;

    // New-bin candidate bias: make empty bin moderately attractive only for large items
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * fit_norm * (1.0 - fit_norm) * 4.0;
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which capacity-fraction band does post_residual fall in?
    let q = post_residual as f64 / cap;
    // Dead-space bands: leftover in (0, 10) is nearly useless; (10, 20) only fits tiny items.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 }
               else if post_residual < 20 { 0.6 }
               else if post_residual < 30 { 0.25 }
               else { 0.0 };
    score += dead * 25.0;

    // Modulo-arithmetic harmony: leftover that is a multiple of common item sizes (10,20,25,50)
    // is "clean" and reusable. Reward exact divisibility.
    let pr = post_residual as u32;
    let harmony = if pr == 0 { 3.0 }
        else if pr % 50 == 0 { 2.0 }
        else if pr % 25 == 0 { 1.5 }
        else if pr % 20 == 0 || pr % 10 == 0 { 1.0 }
        else { 0.0 };
    score -= harmony * 4.0;

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + 0.5 * (next_item_size as f64);
        } else {
            // next item won't fit here; leftover becomes dead weight relative to next item
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Perfect fit reward: item exactly fills bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: item fills bin to a harmonic fraction (>= 80% full).
    let fill = item_size as f64 / cap;
    if fill >= 0.8 { score -= 6.0; }
    else if fill < 0.3 { score += 4.0; } // dumping a tiny item into a big residual is wasteful

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fit win by default.
        score += 15.0;
        // But if all fitting bins would leave bad dead space, allow the new bin.
        if fitting_bins_count == 0 { score -= 100.0; }
        // Late in stream, prefer closing out open bins rather than spawning.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // Many open bins with slack: reuse them instead.
        if open_bins_count > 4 && mean_residual > item_size as f64 {
            score += 8.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (minimize wasted gap).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let ni = next_item_size as f64;
    let it = item_size as f64;
    let is_new = bin_residual == bin_capacity;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    if next_item_size > 0 && post_residual > 0 {
        if pr >= ni {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            if pr - ni < 0.03 * cap {
                score -= 1.7;
            }
            if pr == ni {
                score -= 3.5 * (ni / cap);
            }
            score -= 0.6 * (pr / cap) * (1.0 - pr / cap);
            if pr - ni < 0.08 * cap {
                score -= 0.9 * (1.0 - progress);
            }
            if pr - ni < 0.12 * cap && fitting_bins_count >= 3 {
                score -= 0.6;
            }
            if pr - ni > 0.35 * cap && fitting_bins_count >= 4 {
                score += 1.0;
            }
            if pr - ni > 0.10 * cap && pr - ni < 0.18 * cap {
                score -= 0.45 * (pr - ni) / cap;
            }
            if br / cap < 0.06 && !is_new {
                score -= 0.8;
            }
            // dead-space penalty: residual too small for typical future items
            if pr / cap < 0.05 && !is_new {
                score -= 0.5 * (1.0 - progress);
            }
            if pr == ni && progress > 0.5 {
                score -= 0.5;
            }
            // snug lookahead: reward bins whose post-residual still fits the next item tightly
            let slack = pr - ni;
            let snug = 1.0 - (slack / cap).min(1.0);
            score -= 0.35 * snug * (1.0 - progress);
            // also check two-step chain: next item then a near-exact fit again
            if slack > 0.0 && slack >= ni && (slack - ni) < 0.05 * cap {
                score -= 1.2 * (1.0 - progress);
            }
        } else {
            // dead space: too small for the next item
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
            score += 0.8 * (ni - pr) / cap * (1.0 - progress);
            if fitting_bins_count <= 1 && !is_new {
                score += 1.2;
            }
            if (ni - pr) > 0.5 * mean_residual && !is_new {
                score += 0.7 * (1.0 - progress);
            }
            if pr < 0.05 * cap && !is_new {
                score += 1.4;
            }
            if (br - it) / cap < 0.02 {
                score -= 1.0;
            }
            if br / cap < 0.10 && !is_new {
                score -= 0.6;
            }
            if is_new && open_bins_count > 4 && (ni - pr) / cap < 0.05 {
                score += 0.6;
            }
            // penalize leaving this bin unusable for the next item when its residual is tiny
            let dead = (ni - pr) / cap;
            if dead < 0.05 && dead > 0.0 && !is_new {
                score += 0.9 * (1.0 - progress);
            }
        }
    }
    // tiny unusable sliver
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits more strongly when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 2.0 * (it / cap);
    } else if !is_new {
        score -= 60.0; // last-chance bin: avoid opening a new bin
    }

    // Balance: penalize deviation from mean residual, softened late.
    let dev = (br - mean_residual).abs();
    score += (0.25 - 0.1 * progress) * dev;

    if is_new {
        let usable = mean_residual.max(0.0);
        if open_bins_count > 0 && usable >= it {
            score += 8.0 + 6.0 * (usable / cap);
        } else {
            score += 2.5 * (1.0 - progress);
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        score -= (it / cap) * 150.0;
        if it > 0.5 * cap {
            score -= 1.0;
        }
    }

    // Late in the stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    // Graded tightness bonus — reward placements whose leftover is a
    // small fraction of capacity, scaled by how many alternatives exist.
    if post_residual > 0 {
        let tight = 1.0 - pr / cap;
        score -= 3.0 * tight * tight * (fitting_bins_count as f64).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are nearly useless — penalize small gaps hard, scaled by how "dead" they are.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        let deadness = (dead_threshold - post_residual as f64) / dead_threshold; // 0..1
        score += 60.0 * deadness + 25.0;
    }

    // Smooth penalty for small-to-mid residuals that are hard to fill later,
    // peaking around residual ~ 30 (too small for large items, too big to waste).
    let pr = post_residual as f64;
    let mid_gap = (pr - 30.0) * (pr - 30.0) / 400.0;
    score += 8.0 * (1.0 - (-mid_gap).exp());

    // Lookahead: reward if the next item fits exactly / well into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // guaranteed future perfect fit
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / 100.0); // good chaining bonus
        } else {
            score += 10.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless it creates dead space, handled above).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, consolidate rather than fragment.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Prefer bins whose residual is already below average (they are "tight"
    // and close to closing); penalize very loose bins.
    if (bin_residual as f64) > mean_residual {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate (empty bin): make it attractive only when this bin
    // would otherwise create dead space or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin has full flexibility, residual = 100.
        score -= 5.0;
        if post_residual < 10 {
            score += 200.0; // never open a new bin for a perfect fit elsewhere
        }
        if fitting_bins_count > 1 && open_bins_count > 0 {
            score += 20.0 + 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight relative to capacity.
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Strong 2-step lookahead: exact match of next item into post_residual is ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain closure
        } else if next_item_size <= post_residual {
            // next fits: residual waste after next placement
            let two_step_waste = post_residual - next_item_size;
            score -= 25.0 - 0.4 * two_step_waste as f64;
        } else {
            // next item cannot use this residual: residual becomes dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare residual against mean residual across open bins:
    // placing into a below-mean-residual bin evens out the load.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, slightly prefer opening fresh bins (cheap now, flexible later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        // penalize leaving very small unusable slivers
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
        // reward large residual bins being consumed when many bins are open
        if open_bins_count > 6 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let is_new = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prn = pr / cap;

    // Base: wasted space, damped late in the stream
    let mut score = pr * (1.0 - 0.35 * progress * progress);

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (prn * prn - prn) * (0.5 + progress);
    score += 12.0 * coupling;

    // Reward tight fits more strongly as progress advances
    score -= (1.0 - prn).powi(3) * (4.0 + 10.0 * progress);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward bins whose post-residual accommodates the next item snugly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let slack = pr - ni;
        if slack >= 0.0 {
            // exact fit bonus
            if slack == 0.0 {
                score -= 6.0 + 3.0 * (1.0 - progress);
            }
            // snug gaussian-like reward
            let diff = slack;
            score -= 20.0 * (-diff * diff / 50.0);
            if slack < 0.03 * cap {
                score -= 1.7;
            }
            if slack < 0.08 * cap {
                score -= 0.9 * (1.0 - progress);
            }
            if slack < 0.12 * cap && fitting_bins_count >= 3 {
                score -= 0.6;
            }
            if slack > 0.35 * cap && fitting_bins_count >= 4 {
                score += 1.0;
            }
            if slack > 0.10 * cap && slack < 0.18 * cap {
                score -= 0.45 * slack / cap;
            }
            // dead-space lookahead
            let snug = 1.0 - (slack / cap).min(1.0);
            score -= 0.35 * snug * (1.0 - progress);
        } else {
            let dead = -slack / cap;
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if dead > 0.15 {
                score += 1.0;
            }
            score += 0.5 * dead * (fitting_bins_count as f64).min(3.0);
            score += 0.8 * dead * (1.0 - progress);
            if dead < 0.05 && !is_new {
                score += 0.9 * (1.0 - progress);
            }
            if -slack as f64 > 0.5 * mean_residual && !is_new {
                score += 0.7 * (1.0 - progress);
            }
        }
    }

    // Penalize opening a new bin when plenty of bins already fit the item
    if is_new {
        let pressure = fitting_bins_count as f64;
        score += 15.0 + 8.0 * (pressure.max(1.0).ln()) - 10.0 * progress;
        if open_bins_count > 4 && next_item_size > 0 && ((next_item_size as f64 - pr) / cap).abs() < 0.05 {
            score += 0.6;
        }
        if item_size as f64 > 0.5 * cap {
            score -= 1.0;
        }
    } else {
        // Mild preference for bins below mean residual (use up sparse space first)
        score += 0.15 * (mean_residual - br);
        if br / cap < 0.06 {
            score -= 0.8;
        }
        if prn < 0.05 {
            score -= 0.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early (few open bins) or when
        // the item is large (would leave an awkward fit elsewhere).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = 1.0 / (open_bins_count as f64 + 1.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        let base = post_residual as f64
            - 12.0 * openness
            - 10.0 * large_item * (1.0 - progress);
        // If many bins fit the item, opening a new one is wasteful.
        let crowd = (fitting_bins_count as f64).min(6.0) * 3.0;
        return base + crowd;
    }

    // ---- Best-fit core: small post_residual wins ----
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // ---- Lookahead (k=2): reward bins whose leftover can host the next item ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly-ish into this bin's leftover: chain bonus.
            let tight = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.05 * tight;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin but not after placing current item:
            // mild penalty, since we may want the current item elsewhere.
            score += 6.0;
        } else {
            // Next item won't fit this bin either way: slight bonus for
            // keeping this bin for the current item.
            score -= 3.0;
        }
    }

    // ---- Last-chance bin: if this is the only fitting bin, strongly prefer it ----
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // ---- Global residual coupling: prefer bins below mean residual
    //      (concentrate waste in few bins, keep others flexible). ----
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // ---- Time horizon: as the stream progresses, tighten placements ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    // ---- Fragmentation penalty: leftover that is small-but-not-zero is dead space ----
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

