        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (1.0 - pr / cap) * nxt * (0.5 + 0.5 * progress);
        } else {
            score += (nxt - pr) * (0.3 + 0.4 * progress);
        }
    }

    // Mean-residual coupling: prefer bins deviating from mean residual (diversity of gaps).
    let dev = (pr - mean_residual).abs();
    score += dev * 0.15 * (1.0 - progress);

    // New-bin candidate: smooth sigmoid-like penalty depending on how well open bins exist.
