        let openness = 1.0 / (1.0 + (fitting_bins_count as f64) * (1.0 + progress));
        score += cap * (0.6 + 0.4 * openness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let ni = next_item_size as f64;
    let it = item_size as f64;
    let is_new = bin_residual == bin_capacity;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    if next_item_size > 0 && post_residual > 0 {
        if pr >= ni {
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            if pr - ni < 0.03 * cap {
                score -= 1.7;
            }
            if pr == ni {
                score -= 3.5 * (ni / cap);
            }
            score -= 0.6 * (pr / cap) * (1.0 - pr / cap);
            if pr - ni < 0.08 * cap {
                score -= 0.9 * (1.0 - progress);
            }
            if pr - ni < 0.12 * cap && fitting_bins_count >= 3 {
                score -= 0.6;
            }
            if pr - ni > 0.35 * cap && fitting_bins_count >= 4 {
                score += 1.0;
            }
            if pr - ni > 0.10 * cap && pr - ni < 0.18 * cap {
                score -= 0.45 * (pr - ni) / cap;
            }
            if br / cap < 0.06 && !is_new {
                score -= 0.8;
            }
            // dead-space penalty: residual too small for typical future items
            if pr / cap < 0.05 && !is_new {
                score -= 0.5 * (1.0 - progress);
            }
            if pr == ni && progress > 0.5 {
                score -= 0.5;
            }
            // snug lookahead: reward bins whose post-residual still accommodates
            // the next item tightly, stronger early in the stream.
            let slack = pr - ni;
            if slack > 0.0 {
                let snug = 1.0 - (slack / cap).min(1.0);
                score -= 0.45 * snug * (1.0 - progress);
                // two-step chain: post-residual must also fit item after next
                // approximated via mean residual as a proxy for the following item
                if slack >= mean_residual && slack - mean_residual < 0.04 * cap {
                    score -= 0.8 * (1.0 - progress);
                }
            }
        } else {
            // dead space: too small for the next item
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            if (ni - pr) / cap > 0.15 {
                score += 1.0;
            }
            score += 0.5 * (ni - pr) / cap * (fitting_bins_count as f64).min(3.0);
            score += 0.8 * (ni - pr) / cap * (1.0 - progress);
            if fitting_bins_count <= 1 && !is_new {
                score += 1.2;
            }
            if (ni - pr) > 0.5 * mean_residual && !is_new {
                score += 0.7 * (1.0 - progress);
            }
            if pr < 0.05 * cap && !is_new {
                score += 1.4;
            }
            if (br - it) / cap < 0.02 {
                score -= 1.0;
            }
            if br / cap < 0.10 && !is_new {
                score -= 0.6;
            }
            if is_new && open_bins_count > 4 && (ni - pr) / cap < 0.05 {
                score += 0.6;
            }
            // penalize leaving this bin unusable for the next item when its residual is tiny
            let dead = (ni - pr) / cap;
            if dead < 0.05 && dead > 0.0 && !is_new {
                score += 0.9 * (1.0 - progress);
            }
        }
    }
    // tiny unusable sliver
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Reward tight fits more strongly when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 2.0 * (it / cap);
    } else if !is_new {
        score -= 60.0; // last-chance bin: avoid opening a new bin
    }

    // Balance: penalize deviation from mean residual, softened late.
    let dev = (br - mean_residual).abs();
    score += (0.25 - 0.1 * progress) * dev;

    if is_new {
        let usable = mean_residual.max(0.0);
        if open_bins_count > 0 && usable >= it {
            score += 8.0 + 6.0 * (usable / cap);
        } else {
            score += 2.5 * (1.0 - progress);
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        score -= (it / cap) * 150.0;
        if it > 0.5 * cap {
            score -= 1.0;
        }
    }

    // Late in the stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    // Graded tightness bonus — reward placements whose leftover is a
    // small fraction of capacity, scaled by how many alternatives exist.
    if post_residual > 0 {
        let tight = 1.0 - pr / cap;
        score -= 3.0 * tight * tight * (fitting_bins_count as f64).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post-residual (tight fit), scaled non-linearly.
    let mut score = post * post / cap; // quadratic waste penalty

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    // Residuals <= 10 are "perfect" (nearly sealed); 11..=25 mildly bad; large residuals bad.
    let class = post_residual / 10; // integer division class 0..=10
    score -= match class {
        0 => 30.0,               // near-perfect seal
        1 => 12.0,               // small pocket
        2 => 3.0,                // moderate pocket
        3 => -2.0,               // 30-39: can host small items later
        4 => 0.0,
        5 => 2.0,
        6 => 4.0,
        7 => 6.0,
        _ => 8.0,                // large dead space
    };

    // Modulo coupling: residuals that are multiples of common small sizes are reusable.
    let reusable = (post_residual % 10 == 0 && post_residual > 0)
        || (post_residual % 20 == 0 && post_residual > 0)
        || (post_residual % 25 == 0 && post_residual > 0);
    if reusable {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            // next item won't fit here: penalize leaving a residual just below next size (dead space trap)
            if post_residual >= next_item_size - 5 && post < next_item_size as f64 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // (avoids opening a new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate detection: bin_residual == bin_capacity (empty bin).
    if bin_residual == bin_capacity {
        // Opening a new bin should only win when no open bin fits well.
        if fitting_bins_count > 0 {
            // penalize new bin; strength grows with how many bins fit and how tight they'd be
            score += 35.0 + 5.0 * (fitting_bins_count as f64);
        } else {
            score -= 5.0; // forced: no open bin fits
        }
        // Late in the stream, opening fresh bins is slightly cheaper (less future risk)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.02 * (open_bins_count as f64);

    // Prefer bins whose residual is close to the mean (balance), slight effect.
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0; // unusable sliver
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid pushing us to open a new bin anyway.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * 0.5 + progress * 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: heavily penalized unless existing fits are bad.
        score += 400.0 + pressure;
        // If mean residual is small (open bins are nearly full), new bin is fine.
        if mean_residual < 15.0 {
            score -= 350.0;
        }
    } else {
        // Slight preference for fuller bins (smaller residual before placement).
        score += (bin_capacity - bin_residual) as f64 * -0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
