    // Progression: later in the stream, tighten up (prefer tight fits more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.3 * progress;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual < next_item_size;
        if bad_fit && fitting_bins_count <= 2 {
            score -= 60.0; // opening fresh bin is reasonable
        } else {
            score += 200.0; // prefer existing bins otherwise
        }
    }

    score
}

