    // Last-chance bin: favor using it, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity.max(1) as f64);
        score -= 120.0 + 60.0 * tightness;
    }

    // Mean-residual consolidation with adaptive gain: earlier in the stream,
    // be gentler; later, enforce consolidation more strongly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = post_residual as f64 - mean_residual;
    score += (0.10 + 0.20 * progress) * dev;

    // Rare large items: prefer keeping big residual bins available for them.
    let big_next = next_item_size > bin_capacity / 2;
    if big_next {
        // Reward leaving a large residual intact for the big next item.
        score += 0.3 * ((post_residual as f64) - (next_item_size as f64)).abs();
    }

    // Tighten overall scores late in the stream.
    score *= 1.0 - 0.3 * progress;

    // New-bin candidate logic: open fresh only when the fit landscape is bad.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual < next_item_size;
        if bad_fit && fitting_bins_count <= 2 {
            score -= 60.0;
        } else if big_next && post_residual < next_item_size {
            // Reserve capacity for the upcoming large item.
            score -= 90.0;
        } else {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = it / cap;                       // how big the item is
    let post_frac = pr / cap;                      // residual after placement

    // Base: reward small post-residual with a non-linear (quadratic) penalty on waste.
    let mut score = pr as f64 * (1.0 + 1.8 * post_frac * post_frac);

    // Tightness reward: strongly favor near-exact fits (smooth coupling of item & residual).
    let tightness = 1.0 - ((br - it) / cap).powi(2);
    score -= 14.0 * tightness * (0.5 + fit_frac);

    // Stream progress coupling: later in the stream, prefer compacting existing bins more.
    let p2 = progress * progress;
    score += pr * (2.5 * p2 - 0.6 * progress);

    // Mean-residual context: if this bin is below average residual, it's a good compactor.
    let dev = (mean_residual - br) / cap;
    score -= 3.0 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // New-bin candidate (empty bin): penalize mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        let spread = (mean_residual / cap).powi(3);
        score += 10.0 + 20.0 * (1.0 - spread) + 6.0 * (1.0 - progress);
    }

    // Lookahead: penalize leaving a residual that poorly matches the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = ((pr - nx) / cap).abs();
        score += 5.0 * gap * gap;
        // Reward residuals that exactly accommodate the next item.
        score -= 6.0 * (1.0 - ((pr - nx).abs() as f64 / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Ideal chained placement: next item exactly fills the remainder.
            score -= 900.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward tightness of the follow-up fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0) * 0.8;
        } else {
            // Dead space relative to next item: penalize proportionally,
            // but cap the penalty so large next items don't dominate.
            let waste = (next_item_size - post_residual) as f64;
            score += 25.0 + waste.min(60.0) * 0.7;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 140.0;
    } else if fitting_bins_count == 2 && bin_residual < bin_capacity {
        // Mild nudge toward one of the few viable bins to avoid fragmentation.
        score -= 30.0;
    }

    // Consolidation: reward bins with residuals below the mean (they are
    // closer to closure), penalize above-mean residuals mildly.
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Tight-fit bonus: reward placements that nearly close the bin.
    if post_residual > 0 && post_residual <= 10 {
        score -= 40.0;
    }

    // Progression: tighten preference for compact fits later in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.35 * progress;

    // New-bin candidate logic:
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual < next_item_size;
        if bad_fit && fitting_bins_count == 0 {
            // Nothing anywhere can take the next item after this placement;
            // a fresh bin is the only forward path.
            score -= 80.0;
        } else if bad_fit && fitting_bins_count <= 1 && post_residual < next_item_size / 2 {
            // Existing bin would waste more than half of next item's space.
            score -= 40.0;
        } else {
            // Prefer existing bins otherwise; scale penalty with how many
            // alternatives exist.
            score += 200.0 + 15.0 * fitting_bins_count as f64;
        }
    }

    score
}

