        } else {
            let waste = (next_item_size - post_residual) as f64 ;
            score += 30.0 + waste * 0.8 ;
        }
    }
    // new-bin candidate: discourage opening a bin unless it enables a perfect future fit
    if bin_residual == bin_capacity {
        let perfect_next = next_item_size > 0 && next_item_size == item_size ;
        let tight_now = item_size as f64 >= bin_capacity as f64 * 0.9 ;
