pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to ever be
    // useful (below the smallest plausible item, or below the lookahead item)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver -> dead space
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0; // gap unusable by the next arriving item
    }

    // Reward near-perfect fits (tight packing) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (penalize the new-bin candidate) and encourage consolidating into
    // existing ones, especially those with small residuals.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the current mean (they are the
    // "fuller" bins; filling them first keeps many large gaps open).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins
    // (keeps future flexibility); later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead matching ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if next_item_size <= bin_residual && post_residual >= next_item_size {
            // Next item still fits after this placement; reward tight leftover.
            score -= 0.35 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space: leftover too small for the lookahead item.
            // Penalize proportionally to how wasted the space is.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 25.0 + 40.0 * waste;
        }
        // Bonus if the item after next could chain into the residual too.
        if post_residual >= next_item_size && (post_residual - next_item_size) as f64 >= mean_residual * 0.5 {
            score -= 8.0;
        }
    } else {
        // Last item of stream: only absolute tightness matters.
        score -= 10.0;
    }

    // ---- Last-chance bonus: if this is the only bin that fits, strongly prefer it ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // ---- Relative-to-mean residual shaping ----
    // Prefer bins whose post residual is close to the mean residual (balanced packing),
    // but prefer bins already tighter than mean (consolidation).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.15 * (mean_residual - pr);
    } else {
        score += 0.10 * (pr - mean_residual);
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin offers a good fit.
        // Base cost of opening a bin; make it cheaper late in the stream when
        // open bins are fragmented (high mean residual relative to capacity).
        let fragmentation = mean_residual / bin_capacity as f64;
        let open_cost = 55.0 - 25.0 * fragmentation.min(1.0) - 10.0 * progress;
        // If the new bin would be a perfect 2-chain start, discount it.
        let chain_discount = if next_item_size > 0 && post_residual == next_item_size { 35.0 } else { 0.0 };
        score = open_cost + pr * 0.2 - chain_discount;
    }

    // Small nudge toward tight absolute fits regardless of other terms.
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
