        let lock = (next_item_size - post_residual) as f64 / bin_capacity as f64 ;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64) ;
        score += 10.0 + lock * 45.0 * scarcity ;
    }
    // small unusable residual penalty: residual too small to matter for next item
    let min_useful = if next_item_size > 0 { next_item_size } else { 1 } ;
    if post_residual > 0 && post_residual < min_useful.min(30) {
