        let w = ((progress - 0.75) / 0.25).min(1.0) ;
        score += post_residual as f64 * 0.06 * w ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness).powi(3) * 40.0;

    // Penalize dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless fits are bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64;
        score += 30.0 + pressure * 2.0;
        // If current bin would leave a good residual, discourage new bin more
        if post_residual as f64 <= mean_residual {
            score += 20.0;
        }
    } else {
        // Reward using existing bins, more when many bins are open
        score -= (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= chain_fit * 20.0; // better chain utilization
        } else {
            // next item won't fit here; penalize leaving residual close to but below next item
            let gap = (next_item_size as f64 - post_residual as f64).abs();
            if gap < 10.0 {
                score += 10.0;
            }
        }
    }

    // Time horizon: early in stream, be more conservative (prefer new bins for large items);
    // late in stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0;

    // Prefer bins whose residual deviates from mean residual in a useful way:
    // bins with residual close to item_size are near-perfect fits
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score -= (-(residual_gap / bin_capacity as f64)).exp() * 10.0;

    // Global state coupling: high mean residual means lots of slack exists; be pickier
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Small item into large residual: mild penalty to preserve big residual for big items
    if (item_size as f64) < 0.4 * bin_capacity as f64 && post_residual as f64 > 0.5 * bin_capacity as f64 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
