    // Smooth interaction: post_residual weighted by stream progress — later in the stream,
    // waste matters more, so tighten packing.
    score += post * (0.3 * progress * progress);

    // Lookahead coupling: reward bins whose post_residual still fits the next item smoothly
    if next > 0.0 && post >= next {
        let slack = (post - next) / cap;
        score -= 4.0 * (1.0 - slack).exp() * (1.0 - slack);
    } else if next > 0.0 {
        // Penalize bins that leave a gap just below the next item's size
        let gap = (next - post) / cap;
        score += 3.0 * (-gap * 10.0).exp();
