    score += 0.05 * (residual - mean_residual).abs();

    // New-bin candidate shaping: empty bin gets a moderate score unless open bins are few
    if bin_residual == bin_capacity {
        score = cap + 5.0 * (1.0 - progress) - 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    score
}

