    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward tight fits, decay bonus for loose fits
            score -= 55.0 - (slack * 0.5).min(55.0);
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            // exact double fit: gap holds the next item twice
            if slack == next_item_size as f64 {
                score -= 14.0;
            }
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            // penalize unusable gap more when item nearly fits
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
        }
    }

    // lookahead: small leftovers are likely dead space; scale penalty by mean residual
    if post_residual > 0 && (post_residual as f64) < mean_residual.max(20.0) * 0.5 {
        score += 10.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }

    // tightness ratio bonus when competing bins exist
    if fitting_bins_count > 1 && post_residual > 0 {
        let tightness = post_residual as f64 / bin_capacity as f64;
        if tightness < 0.08 {
            score -= 22.0;
        } else if tightness < 0.2 {
            score -= 8.0;
        }
    }

    // prefer tightest bin when many candidates exist
    if fitting_bins_count > 3 {
        score -= 5.0;
    } else if fitting_bins_count > 1 {
        score -= 2.0;
    }
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    // discourage opening a new bin when a decent fit exists,
    // but allow it when all fits are poor (post_residual would be tiny)
    if bin_residual == bin_capacity && post_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        let poor_fit = post_residual < item_size.saturating_mul(2).max(20) && next_item_size > post_residual;
        if poor_fit {
            score += 10.0 + open_bins_count as f64;
        } else {
            score += 60.0 + open_bins_count as f64 * 2.0;
        }
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        // when fragmentation is high and next item exceeds mean residual, opening a
        // fresh bin is often better than squeezing into a near-full one
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual.max(1) as f64;
