            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        let dead = post_residual as f64 / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        let rem_frac = (remaining / (total_items.max(1) as f64)).min(1.0);
        if dead > 0.0 && dead < 0.05 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if dead > 0.0 && dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead >= 0.12 && dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        // two-step lookahead: gap exactly fits next item twice
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual > next_item_size && (post_residual as f64) < next_item_size as f64 * 1.5 {
            score -= 6.0 * rem_frac;
        }
    }

    // mild preference to keep bins balanced late in the stream
    if step_index * 2 > total_items {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.9 && post_residual > 0 {
        score += post_residual as f64 * post_residual as f64 * 0.004;
    }

    score
}

