}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better, but dead space
    // below the smallest possible item is pure waste.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score -= 400.0; // near-perfect, unusable sliver
    }

    // Harmonic class logic: classify post_residual by capacity fraction.
    // Residuals in [0,25) are "dead" zones, [25,50) moderate, [50,75) good, [75,100] excellent.
    let class = post_residual / 25;
    score -= match class {
        0 => 50.0,
        1 => 20.0,
        2 => 0.0,
        _ => -30.0,
    } as f64;

    // Modulo coupling: residual divisible into chunks matching next item
    // alignment is valuable. If next_item_size > 0 and post_residual can
    // exactly hold it, big reward (chaining fits).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual % next_item_size == 0 {
                score -= 120.0;
            } else {
                score -= 40.0;
            }
            // lookahead fit tightness: residual after hypothetical next placement
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 150.0;
            }
        } else {
            // next item cannot fit here; residual must be wasted unless
            // it is tiny. Penalize mid-range waste.
            if post_residual >= 10 {
                score += (post_residual as f64) * 0.5;
            }
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    // or stream is early. An empty bin has full residual; score it so that
    // it loses to good fits but wins over poor ones.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 300.0;
        // early in stream, opening bins is cheaper (more future items to fill)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 150.0;
        // if many open bins and item is small, opening new bin is wasteful
        if item_size <= 30 {
            score += 100.0;
        }
        // if next item is large, a fresh bin is valuable for it
        if next_item_size >= 60 {
            score -= 180.0;
        }
    }

    // Spread-awareness: prefer bins with residual below the mean (consolidate)
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Prefer using fewer, fuller bins when many bins are open
    if open_bins_count > 5 {
        score += (open_bins_count as f64 - 5.0) * 2.0;
    }

    // Integer division threshold: exact half-fill bins are flexible
    if post_residual == bin_capacity / 2 {
        score -= 60.0;
    }

    score
}

