        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        // NEW: perfect-chain reward — post_residual is exactly reusable by next item
        // and the bin was already tight (fill ratio high)
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: minimize post_residual quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio * bin_capacity as f64;

    // Aggressive 2-step lookahead: exact match of next item into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_waste = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - lookahead_waste / bin_capacity as f64);
        // Perfect chain: item + next item exactly fills the bin.
        if lookahead_waste == 0.0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, worse when small.
        score += 0.35 * post_residual as f64;
    }

    // Penalize creating tiny unusable residuals (below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Context: relative to mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins as stream progresses if a decent fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let fit_quality = fit_ratio; // how well the item fills the fresh bin
        score += 45.0 + 30.0 * progress - 20.0 * fit_quality;
        // New bin justified only if this bin is a bad fit for current item.
        if fit_ratio > 0.6 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate across many open bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

