}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: squash post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score -= 40.0 * tightness;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * chain_fit;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the lookahead item.
        score += 8.0 + 0.15 * post_residual as f64;
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize proportionally to how many bins could fit,
    // and to how much mean residual is being wasted elsewhere.
    if is_new_bin {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 30.0 / fit_pressure + 0.2 * mean_residual;
        // Early in the stream, opening bins is cheap (future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    } else {
        // Favor using bins whose residual deviates above the mean (consolidate waste).
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
    }

