                let guess2 = (next_item_size as f64 * 0.75).round() as u32;
                if guess2 >= 1 && post_residual >= next_item_size + guess2 {
                    let extra = post_residual - next_item_size - guess2;
                    if extra == 0 {
                        score -= 16.0;
                    } else if (extra as f64) < 0.04 * bin_capacity as f64 {
                        score -= 8.0;
                    }
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            // shortfall small and several bins fit — recoverable, soften penalty
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
