        }
        // perfect-chain reward — post_residual exactly reusable by next item
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        // NEW: reward leaving a residual that is a clean fraction of capacity,
        // since such residuals compose well with typical item distributions
        if post_residual > 0 && bin_capacity % post_residual == 0 && post_residual <= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

