        if next_item_size as f64 <= item_size as f64 {
            score += 8.0; // don't open a bin the lookahead could reuse anyway
        }
    }

    // Mild preference for consolidating into bins with low mean residual.
    score += 2.0 * (mean_norm - norm_pr).abs();

    score
}

