pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "reusable"
    // residue classes (multiples of 10, or large enough for small items) are good.
    let pr = post_residual;
    let class = pr / 10; // integer division harmonic class
    if pr == 0 {
        score -= 40.0; // perfect fill is ideal
    } else if pr % 10 == 0 {
        score -= 8.0; // aligned residual: reusable by typical item sizes
    } else {
        score += (10 - (pr % 10)) as f64 * 0.5; // misalignment penalty
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0 + (next_item_size as f64 / cap) * 10.0;
        } else {
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bonus: sole fitting bin avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: prefer it only late or when existing bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        score = 55.0
            - progress * 20.0
            - fragmentation * 15.0
            - (open_bins_count as f64) * 0.3;
        if next_item_size > 0 && next_item_size <= pr {
            score -= 10.0;
        }
    }

    // Mild preference for tight fills among open bins.
    score += (item_size as f64 / cap) * 2.0;

    score
}

