                score += 1.0;
            }
            score += 0.5 * (ni2 - pr) / cap * (fitting_bins_count as f64).min(3.0);
            score += 0.8 * (ni2 - pr) / cap * (1.0 - progress);
            if fitting_bins_count <= 1 && bin_residual < bin_capacity {
                score += 1.2;
            }
            if pr < 0.05 * cap && bin_residual < bin_capacity {
                score += 1.4;
            }
            if (br - item_size as f64) / cap < 0.02 {
                score -= 1.0;
            }
            if br / cap < 0.10 && bin_residual < bin_capacity {
                score -= 0.6;
            }
        }
    }

    // Awkward gap just above next item when fill is low (dead space risk).
    if fill < 0.5 && next_item_size > 0 && pr > next_item_size as f64 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 4.0 {
            score += gap * 1.0;
        }
    }

    // Balance around mean residual, softened late in stream.
    let dev = (br - mean_residual).abs();
    score += 0.25 * dev * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Multiple fitting bins with reusable residual: reward.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        let remaining = (total_items - step_index).max(1) as f64;
        let big_item_bonus = (item_size as f64 / cap) * 150.0;
        score += 200.0 - big_item_bonus;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        score += 2.5 * (1.0 - progress);
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= 0.5 * cap && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / cap > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.7 && frag < 0.35 {
            score -= 18.0;
        }
        if next_item_size > 0 && fitting_bins_count > 1 && (bin_capacity as u32).saturating_sub(item_size) < next_item_size {
            score += 0.8;
        }
    } else {
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        }
        if pr > 0.0 && pr < 0.05 * cap && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && pr >= next_item_size as f64 && pr <= next_item_size as f64 * 2.0 {
            score -= 8.0;
        }
        if fill > 0.6 && next_item_size > 0 && pr >= next_item_size as f64 {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
    }

    // Late in stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item also fits here after placing current item: strong lookahead reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Bonus if the chain can continue (post_residual - next_item_size still useful).
        let chained = post_residual - next_item_size;
        if chained >= 10 {
            score -= 10.0;
        }
    }
    // Next item will NOT fit here: penalize proportional to wasted potential,
    // but only if other bins could have taken this item.
    else if next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Penalize creating tiny unusable dead space (below minimum item size ~1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    // over opening a new one, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Reward bins tighter than the mean residual (good consolidation).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-ish but slightly penalized so we only
    // open new bins when existing fits are genuinely bad (large residuals).
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is more attractive when few bins fit the item.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Early in stream, allow more bin opening.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Mild penalty for hoarding many open bins with big residuals.
    if open_bins_count > 4 && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - (slack * 0.5).min(55.0);
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            if slack == next_item_size as f64 {
                score -= 14.0;
            }
            // pair lookahead: residual reusable by next two items
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation: residual divisible by next item size
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
        }
    }

    // dead-space penalty: small leftovers unlikely to be reused
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    // residual exactly reusable-sized band
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if progress > 0.25 && progress < 0.85 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 6.0 {
                score += gap * 0.8;
            }
        }
        if dead > 0.0 && dead < 0.10 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 9.0 * rem_frac;
        }
        if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) < item_size {
            score += 4.0 * rem_frac;
        }
        // stranded capacity: unusable by next item and below half mean residual
        if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as f64) < mean_residual * 0.5 {
            score += 5.0 * rem_frac;
        }
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        // fresh bin for near-full items late in stream keeps old residuals as flexible pool
        if fitting_bins_count > 0 && progress > 0.5 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.55 && mean_residual >= item_size as f64 {
                score -= 7.0;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // strong preference for near-exact fits when few bins can host the next item
        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // penalize awkward gap just above next item when fill is low (dead space risk)
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        // reward near-perfect fill leaving residual matching mean residual band (reusable pool)
        if fill > 0.7 && post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 4.0 {
            score -= 4.0;
        }
    }

    score
}

