pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score quadratically as post_residual shrinks.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space that is too small for typical future items
    // (residual in (0, 10) is unusable; also small residual vs next item).
    if post_residual > 0 {
        let dead = 10u32.saturating_sub(post_residual) as f64;
        score += dead * 2.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward
    // this placement (chain packing); otherwise penalize proportionally.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.6;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost that
    // shrinks as the stream progresses (fewer chances to amortize a new bin)
    // and when many bins are already open (consolidate instead of expand).
    if bin_residual == bin_capacity {
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 30.0 * t + (open_bins_count as f64) * 1.5;
        // Opening a new bin is attractive when the current fit is very loose
        // (large item in a fresh bin leaves useful residual vs mean residual).
        if (post_residual as f64) >= mean_residual {
            score -= 12.0;
        }
    }

    // Mild preference for filling bins below mean residual (balance load).
    score += ((post_residual as f64) - mean_residual) * 0.08;

    // Slight early-stream conservatism: keep residual space flexible early,
    // pack greedily later.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
