    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, small residuals are fine; late, waste is penalized super-linearly.
    let poly = norm_pr * norm_pr * (0.5 + 2.5 * progress) + norm_pr * (0.5 * (1.0 - progress));
    score += poly * cap * 0.1;

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins.
    let fit_term = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 12.0 * fit_term * (1.0 + progress);

    // Tight fit reward: quadratic in (residual - item) proximity to zero.
    let tight = 1.0 - (pr / (bin_residual.max(1) as f64));
    score -= 6.0 * tight * tight;

    // Penalize if post_residual is small but next item likely can't use it.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        let unusable = if next_item_size as u32 > post_residual { gap } else { 0.0 };
        score += 0.15 * unusable * (0.5 + progress);
        // Reward leaving space exactly matching the next item.
        let match_term = 1.0 - (gap / cap).clamp(0.0, 1.0);
        score -= 3.0 * match_term * match_term;
