    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate handling: discourage opening new bins unless residual waste is small.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * norm_pr * (0.5 + progress);
    }

    score
}

