        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > next_item_size {
            let stranded = post_residual - next_item_size;
            if (stranded as f64) > 0.25 * bin_capacity as f64 {
                score -= 16.0;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // penalize awkward gap just above next item when fill is low (dead space risk)
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        // reward near-perfect fills more aggressively (fill > 0.92)
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps of 1..=10 are considered dead space (min item size ~10 in classic case,
    // but sizes go down to 1, so scale penalty by gap size).
    if post_residual > 0 {
        if post_residual <= 10 {
            // tiny gap: nearly total waste
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual <= 25 {
            // small gap: likely unusable unless tiny items come
            score += 25.0;
        } else if post_residual <= 50 {
            // moderate gap: mild penalty
            score += 8.0;
        }
    }

    // Reward exact fits / near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage scattering across many bins when few needed,
    // but encourage using existing bins over opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it less attractive unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // next item can't use the gap: dead space likely
            score += 6.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    // to keep large gaps available for large future items.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Stream progression: early on, be more willing to open bins (build diversity);
    // later, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - (slack * 0.5).min(55.0);
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            if slack == next_item_size as f64 {
                score -= 14.0;
            }
            // pair lookahead: residual reusable by next two items
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation: residual divisible by next item size
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
            }
            // triple lookahead for tight residual chains
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            // mild relief when residual is near-half of next item (mergeable later)
            if waste > 6.0 && (post_residual as f64) > next_item_size as f64 * 0.45 {
                score -= 4.0;
            }
        }
    }

    // dead-space penalty: small leftovers unlikely to be reused
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    // residual exactly reusable-sized band
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if progress > 0.25 && progress < 0.85 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 6.0 {
                score += gap * 0.8;
            }
        }
        if dead > 0.0 && dead < 0.10 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 9.0 * rem_frac;
        }
        if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) < item_size {
            score += 4.0 * rem_frac;
        }
        // anti-dead-space: residuals no plausible future item (<= 100) can fully use
        if progress > 0.15 && post_residual > 100 {
            let unusable = post_residual - 100;
            score += unusable as f64 * 0.35 * rem_frac;
        }
        // stranded capacity: unusable by next item and below half mean residual
        if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as f64) < mean_residual * 0.5 {
            score += 5.0 * rem_frac;
        }
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        // prefer fresh bin when existing fits are all poor (post_residual would be tiny)
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score -= 10.0;
        }
        // fresh bin for near-full items late in stream keeps old residuals flexible
        if fitting_bins_count > 0 && progress > 0.5 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.55 && mean_residual >= item_size as f64 {
                score -= 7.0;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.92 {
            score -= 22.0 * (fill - 0.92) / 0.08;
        } else if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // strong preference for near-exact fits when few bins can host the next item
        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // penalize awkward gap just above next item when fill is low (dead space risk)
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        // reward near-perfect fill leaving residual matching mean residual band
        if fill > 0.7 && post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 4.0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64; // 1.0 = perfect fill
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 120.0; // perfect chain: next item exactly fills this bin
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin; penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // last item: just minimize dead space
        score -= 50.0 * fit_ratio;
    }

    // Relative to mean residual: bins below-mean residual are precious; placing here
    // is efficient. Bins above mean have room elsewhere, less urgency.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.4 * (mean_residual - res);
    } else {
        score += 0.25 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: make it attractive only when current bin would
    // leave large unusable dead space relative to what a fresh bin offers.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        // Fresh bin: good if item is large (efficient packing of big items early)
        // and existing bins would leave a hole the next item can't use.
        let size_frac = item_size as f64 / bin_capacity as f64;
        let dead_here = post_residual as f64;
        let hole_useless = next_item_size > 0 && next_item_size as u32 > post_residual;
        let mut new_bin_score = 55.0 * size_frac;
        if hole_useless {
            new_bin_score -= 45.0;
        }
        // Discourage new bins when many bins are open with low fill (fragmentation).
        new_bin_score += 2.0 * open_bins_count as f64;
        // As stream progresses, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 30.0 * progress;
        // Compare against dead space we'd leave in an existing bin.
        new_bin_score += 0.5 * dead_here;
        return new_bin_score;
    }

    // Penalize leaving tiny unusable slivers (< 10, min item size) in existing bins.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

