        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
    score += pressure * 0.4;

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it, less so early in the stream.
        score += 6.0 + progress * 30.0;
        // If next item is large, a fresh bin is more attractive.
        score -= next_item_size as f64 * 0.08;
    } else {
        score -= progress * 4.0;
    }

    // Prefer bins whose residual is close to mean residual (balanced packing).
    score -= 1.0 / (1.0 + ((bin_residual as f64 - mean_residual).abs()));

    // Small bonus for filling bins past half capacity.
    if post_residual < bin_capacity / 2 {
        score -= 3.0;
    }

    score
}

