    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    let mut score = pr;

    // smooth polynomial coupling: prefer tight fits more strongly as stream progresses
    let tight = (fill * fill) * (1.0 + 3.0 * progress);
    score -= 12.0 * tight;

    // penalize residual that is non-linearly "dead" (too small for typical future items)
    let dead = ((pr / cap) - 0.2).powi(2);
    score += 20.0 * dead * (0.5 + progress);

    // lookahead: reward bins that also fit the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let chain = (next_item_size as f64 / cap).powi(2);
        score -= 8.0 * chain * (1.0 - progress);
    }

    // last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // crowded-state pressure: with many open bins, favor consolidation
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * crowding * (pr / cap);

    // new-bin candidate: only attractive when open bins fit poorly
    let mean_gap = (mean_residual - pr).abs();
    if bin_residual == bin_capacity {
        score -= 4.0;
        score += 30.0 * (mean_residual / cap).powi(2) * (0.3 + progress);
    }
    let _ = mean_gap;
    let _ = it;
    let _ = r;

    score
}

