            score += 15.0 * (2.0 - (fitting_bins_count as f64).min(2.0) / 2.0);
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // penalize awkward gap just above next item when fill is low (dead space risk)
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        // reward near-perfect fills more aggressively (fill > 0.92)
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        // scarcity coupling — when this is one of very few fitting bins,
        // filling it tightly matters more (fewer alternatives remain)
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // NEW: near-exact fill with tight post residual that still serves the
        // next item — best of both worlds, deepen the reward
        if fill > 0.8 && next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 2 {
            score -= 7.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Class 0: leftover divisible into large chunks (fits next item well)
    let next = next_item_size as f64;
    if next > 0.0 {
        if post_residual as f64 >= next {
            // Bin can also host the lookahead item: strong reward, scaled by tightness
            let slack = (post_residual as f64 - next) / cap;
            score -= 30.0 * (1.0 - slack) + 10.0;
        } else {
            // Lookahead won't fit here: penalize proportionally to wasted potential
            score += 8.0 + 12.0 * (next - post_residual as f64) / cap;
        }
    }

    // Integer-division thresholds on post_residual (harmonic bands)
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fill, excellent
    } else if pr <= 10 {
        score -= 15.0; // near-perfect
    } else if pr <= 25 {
        score -= 5.0;  // decent
    } else if pr <= 50 {
        score += 3.0;  // mediocre
    } else {
        score += 10.0; // large dead space risk
    }

    // Modulo arithmetic: leftover that divides capacity evenly is reusable
    if pr > 0 && bin_capacity % pr == 0 {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins with residual close to item_size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 15.0 * tightness;

    // Penalize opening a new bin when good fitting bins exist and stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 18.0 + 10.0 * (1.0 - progress) + 5.0 * pressure;
        // But if nothing fits well elsewhere, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference to balance residual against mean (avoid extreme fragmentation)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
