                    score -= 8.0;
                }
            }
        }
        // avoid opening fresh bins late when several open bins still fit
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0 * (2.0 - (fitting_bins_count as f64).min(2.0) / 2.0);
