            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // penalize awkward gap just above next item when fill is low (dead space risk)
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        // reward near-perfect fills more aggressively (fill > 0.92)
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        // scarcity coupling — when this is one of very few fitting bins,
        // filling it tightly matters more (fewer alternatives remain)
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // NEW: residual-chain viability — after placement, residual should still
        // be able to host the next item or be near zero; the in-between band
        // (just below next_item_size) is the worst dead-space zone
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            let shortfall = (next_item_size - post_residual) as f64;
            if shortfall < 10.0 {
                score += (10.0 - shortfall) * 0.9;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Strict dead-space avoidance ---
    // Dead space = post_residual too small to ever hold a plausible future item.
    // Items range 1..100, so treat gaps < 12 as near-unusable dead space.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        // Severe penalty for creating unusable slivers; worse as stream progresses
        // (late in the stream there is less chance to recover).
        score += (dead_threshold - post_residual as f64) * (3.0 + 4.0 * progress);
    }

    // Reward near-perfect fills (tight fit) superlinearly
    if post_residual == 0 {
        score -= 30.0; // perfect closure is always best
    } else if post_residual <= 6 {
        score -= 12.0; // almost-closed bin, unlikely to be reusable anyway
    }

    // Penalize medium gaps that block typical mid-size items but aren't closed
    if post_residual > 6 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.5;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also host the next item: chain potential, reward it
            let slack = post_residual - next_item_size;
            score -= 8.0 - (slack as f64) * 0.1; // prefer chain leaving small slack
        } else {
            // Post-residual cannot host next item: it risks becoming dead space
            let gap = next_item_size - post_residual;
            if gap <= 12 {
                score += gap as f64 * 0.6; // near-miss gap is painful
            }
        }
    }

    // --- Open-bin pressure ---
    // Many open bins: prefer filling existing ones to avoid bin sprawl.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * 2.0 + (open_bins_count as f64) * 0.3;

    // Mean residual coupling: if open bins are collectively full (low mean residual),
    // squeezing this item in is extra valuable.
    if mean_residual < (bin_capacity as f64) * 0.25 {
        score -= ((bin_capacity as f64) * 0.25 - mean_residual) * 0.8;
    } else if mean_residual > (bin_capacity as f64) * 0.6 {
        // Bins are mostly empty; no urgency to stuff this one, slight penalty
        score += (mean_residual - (bin_capacity as f64) * 0.6) * 0.2;
    }

    // --- Last-chance bonus ---
    // If this is the ONLY bin that can fit the item, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    // A brand-new empty bin has bin_residual == bin_capacity. It should only win
    // when no open bin is a decent fit. Give it a baseline cost so existing bins
    // with reasonable post_residual beat it, but it beats bins with terrible fits.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress; // opening new bins costs more later in stream
    } else if post_residual <= 10 {
        // Existing bin with a very tight fit: strongly favored over new bin
        score -= 5.0;
    }

    // Small stabilizing tie-breaker based on how full the bin already is
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 3.0;

    score
}

