                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
            // multiplicity-aware divisibility with scarcity boost
            if next_item_size > 1 && post_residual % next_item_size == 0 && fitting_bins_count <= 2 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 3 {
                    score -= 8.0;
                }
            }
            // NEW: post-fit residual should stay close to mean_residual so it
