pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: strongly reward if next item fits exactly into post_residual,
    // penalize if post_residual is awkwardly small (dead space for future items).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here: penalize wasted leftover proportional to its size
            score += 0.15 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Last-chance bin: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are very poor (large post_residual waste) or no bins fit well.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; scale with how many bins are open.
        score += 6.0 + 0.8 * open_bins_count as f64;
        // But if the item fits perfectly in a fresh bin, that's fine.
        if item_size == bin_capacity {
            score -= 40.0;
        }
    } else {
        // Reward using open bins that keep residual near the mean (balance),
        // penalize bins that are outliers (too full or too empty relative to mean).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Time horizon: early in the stream, be slightly more willing to open bins
    // (more future items to use residual); late, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Small penalty for leaving residual in the awkward 1..=9 dead zone.
    if post_residual >= 1 && post_residual < 10 {
        score += 8.0;
    }

    score
}

