        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
    }

    // mild preference to keep bins balanced late in the stream
    if step_index * 2 > total_items {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap; // normalized leftover

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * (1.0 - progress) * 4.0);
    score += 12.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (cap - pr) * (0.15 + 0.35 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize opening new bins when good fits exist, more so early on
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    } else {
        // Favor bins with residuals near the mean (balanced packing)
        score -= 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 0.4 * (1.0 - gap / cap).max(0.0) * (1.0 + progress);
        if pr >= nx {
            score -= 5.0;
        }
    }

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.2 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let ni = next_item_size as f64;
    let it = item_size as f64;
    let is_new = bin_residual == bin_capacity;
    let mut score = pr;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 700.0;
    }

    if next_item_size > 0 && post_residual > 0 {
        if pr >= ni {
            let slack = pr - ni;
            score -= (10.0 + 4.0 * (1.0 - progress)) * (ni / cap);
            // near-exact chain: residual barely above next item
            if slack < 0.03 * cap {
                score -= 1.7;
            }
            if slack < 0.08 * cap {
                score -= 0.9 * (1.0 - progress);
            }
            if slack < 0.12 * cap && fitting_bins_count >= 3 {
                score -= 0.6;
            }
            // small integer slack band: extremely reusable
            if slack <= 7.0 {
                score -= 6.0 * (1.0 - slack / 8.0);
            }
            // pair lookahead: residual reusable by next two items
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pslack = post_residual - pair;
                if pslack == 0 {
                    score -= 30.0;
                } else if (pslack as f64) < 0.06 * cap {
                    score -= 12.0;
                }
            }
            // harmonic anticipation: residual divisible by next item size
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 4.0 + k as f64;
                }
            }
            // penalize large leftover chains that waste space
            if slack > 0.35 * cap && fitting_bins_count >= 4 {
                score += 1.0;
            }
            if slack > 0.20 * cap && slack < 0.30 * cap && ni < 0.25 * cap {
                score += 0.5 * (1.0 - progress);
            }
            if slack > 0.10 * cap && slack < 0.18 * cap {
                score -= 0.45 * slack / cap;
            }
            // nearly-empty bins are valuable containers: keep them alive
            if br / cap < 0.06 && !is_new {
                score -= 0.8;
            }
            if pr == ni && progress > 0.5 {
                score -= 0.5;
            }
            // mid-stream: residuals larger than any possible item are dead weight
            if progress > 0.15 && post_residual > 100 {
                score += (post_residual - 100) as f64 * 0.3 * rem_frac;
            }
        } else {
            // dead space: too small for the next item
            let waste = ni - pr;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 5.0 * (1.0 - ni / cap);
            score += 0.02 * pr;
            score += waste * 0.4 * scarcity * rem_frac;
            if waste / cap > 0.15 {
                score += 1.0;
            }
            if fitting_bins_count <= 1 && !is_new {
                score += 1.2;
            }
            if waste > 0.5 * mean_residual && !is_new {
                score += 0.7 * (1.0 - progress);
            }
            // tiny unusable slivers: strong penalty scaled by rem_frac
            if post_residual < 12 {
                score += (12 - post_residual) as f64 * 1.2;
            }
            if pr < 0.05 * cap && !is_new {
                score += 1.4;
            }
            if waste / cap < 0.05 && fitting_bins_count > 2 {
                score -= 3.0;
            }
            if br / cap < 0.10 && !is_new {
                score -= 0.6;
            }
            if is_new && open_bins_count > 4 && waste / cap < 0.05 {
                score += 0.6;
            }
        }
    }

    // tiny unusable sliver
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits more strongly when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 2.0 * (it / cap);
    } else if !is_new {
        score -= 60.0; // last-chance bin: avoid opening a new bin
    }

    // Balance: penalize deviation from mean residual, softened late.
    let dev = (br - mean_residual).abs();
    score += (0.25 - 0.1 * progress) * dev;

    if is_new {
        let usable = mean_residual.max(0.0);
        let frag = usable / cap;
        if open_bins_count > 0 && usable >= it {
            score += 8.0 + 6.0 * frag;
        } else {
            score += 2.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        score -= (it / cap) * 150.0;
        // fresh bins less attractive for small items when open bins exist
        let fill = it / cap;
        if fill < 0.5 && open_bins_count > 0 {
            score += 3.0 * (0.5 - fill);
        }
        // large items deserve fresh bins when fragmentation is high
        if fill > 0.7 && frag > 0.25 && fitting_bins_count > 0 {
            score -= 15.0;
        }
        // extra caution against new bins late in the stream
        score += 0.5 * (1.0 - progress) + 1.5 * progress * (open_bins_count as f64).min(10.0) / 10.0;
        if (total_items - step_index) < 20 && fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Late in the stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    // Graded tightness bonus — reward placements whose leftover is a
    // small fraction of capacity, scaled by how many alternatives exist.
    if post_residual > 0 {
        let tight = 1.0 - pr / cap;
        score -= 3.0 * tight * tight * (fitting_bins_count as f64).min(4.0);
        if progress > 0.9 {
            score += pr * pr * 0.004;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - (slack * 0.5).min(55.0);
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            // pair lookahead: residual reusable by next two items
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation: residual divisible by next item size
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
            }
            // triple lookahead for tight residual chains
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 && fitting_bins_count <= 2 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 3 {
                    score -= 8.0;
                }
            }
            // NEW: slack relative to mean residual — prefer leaving room comparable to what other bins have
            if slack as f64 > mean_residual * 0.9 {
                score += (slack as f64 - mean_residual * 0.9) * 0.15 * rem_frac;
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
            // NEW: if the waste can be absorbed by another open bin's mean residual, soften penalty
            if waste > 0.0 && waste <= mean_residual && open_bins_count > 1 {
                score -= 6.0;
            }
        }
    }

    // dead-space penalty: small leftovers unlikely to be reused (tightened band)
    if post_residual > 0 && post_residual < 14 {
        score += (14 - post_residual) as f64 * 1.3;
    }
    // residual exactly reusable-sized band
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if dead < 0.10 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 9.0 * rem_frac;
        }
        if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) < item_size {
            score += 4.0 * rem_frac;
        }
        // anti-dead-space mid-stream: residuals no item (<=100) can fully use
        if progress > 0.15 && post_residual > 100 {
            let unusable = post_residual - 100;
            score += unusable as f64 * 0.35 * rem_frac;
        }
        if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && slack < 5.0 {
                score -= 6.0 * rem_frac;
            }
        }
        // NEW: late-stream bonus for residuals matching the running mean residual scale
        if progress > 0.5 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && (slack as f64).abs() - mean_residual.abs() < 0.0 {
                score -= 4.0 * rem_frac;
            }
        }
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // NEW: opening a fresh bin is attractive when the item nearly fills it and open bins are fragmented
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.8 && frag > 0.2 {
                score -= 10.0;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // NEW: post-fit residual smaller than next item AND smaller than mean residual => likely permanent waste
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size
            && (post_residual as f64) < mean_residual * 0.5 && progress > 0.3 {
            score += 5.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction does it fall into?
    let frac = post_residual as f64 / cap;
    // Class index via integer division thresholds on post_residual
    let class = post_residual / 10; // 0..=10 harmonic class

    // Reward small post_residual nonlinearly (tight packing)
    score -= (1.0 - frac).powi(3) * 30.0;

    // Penalize residuals that fall into "dead" harmonic classes:
    // residuals that very few future items (size 1..100) can use efficiently.
    // Small residuals (class 0..2) are nearly useless; large residuals are fine.
    if post_residual > 0 {
        let usable = (post_residual as f64).ln() / cap.ln();
        score -= usable * 15.0;
    } else {
        score -= 60.0; // perfect fit is best
    }

    // Modulo logic: residuals divisible by common item sizes (10,20,25,50) are reusable
    if post_residual % 50 == 0 { score -= 12.0; }
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 10 == 0 { score -= 4.0; }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            // reward proportionally, penalize leaving awkward gap
            let gap = post_residual - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / cap);
            if gap < 10 { score += 15.0; } // tiny gap after next item is bad
        } else {
            // next item cannot follow here: penalize if this bin is the only option
            if fitting_bins_count == 1 { score += 25.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: prefer reusing open bins early, allow opening when
    // open bins are very fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
        // open a new bin when existing bins are too full to be useful
        score -= 8.0 * fragmentation + pressure;
        if mean_residual < item_size as f64 * 1.2 { score -= 20.0; }
        if post_residual == bin_capacity { score -= 5.0; }
    } else {
        // using an existing bin keeps bin count low
        score -= 10.0;
        if post_residual < 10 && post_residual > 0 { score += 20.0; } // avoid crumbs
    }

    // Late in the stream, prioritize closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A gap is "dead" if it is too small for even the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fill is highly desirable
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity
    score += 25.0 * (post_residual as f64 / bin_capacity as f64);

    // Dead-space penalty scales with how much of the bin is wasted
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 35.0 * (0.1 - waste_ratio) / 0.1;
    }

    // Open-bin pressure: discourage spreading across many bins when few needed
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.8 * bin_pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward if next item fills post_residual nearly exactly
        let next_gap = post_residual - next_item_size;
        if next_gap < 10 {
            score -= 12.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post-residual unusable for the known next item: penalize
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean — placing into a below-mean-residual bin keeps large
    // residuals available for larger future items.
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 6.0 * dev;
    }

    // New-bin candidate: neutral-ish baseline so it's chosen only when
