pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the next item fits into the post-residual,
    // this bin is a great choice — reward proportionally to the match.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 - slack * 1.5;
        // Exact 2-item completion is ideal.
        if slack == 0.0 {
            score -= 300.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; penalize if the leftover
        // dead space is large relative to the next item's size.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.6;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter";
    // filling a tight bin is good, filling a loose bin wastes flexibility.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res_f - mean_residual;
        score += rel * 0.35;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all
    // open bins are poor fits (large post_residual elsewhere / no lookahead match).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64 * 0.85;
        // If many bins are open and any fit, discourage a new bin.
        score += open_bins_count as f64 * 4.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // Exception: a fresh bin perfectly hosts a large item with room for the next.
        if item_size >= bin_capacity * 7 / 10 {
            score -= 60.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && item_size >= bin_capacity / 2 {
            score -= 120.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward zone (11..=30) that few
    // items can use.
    if post_residual > 10 && post_residual < 30 {
        score += 25.0;
    }

    score
}

