            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // NEW: reward near-exact fills more aggressively when few bins can host the item
        if fill > 0.95 && fitting_bins_count <= 3 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // if post_residual is smaller than the smallest plausible item, it is waste.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: mild reward proportional to fit quality
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - lookahead_waste / (bin_capacity as f64));
        } else {
            // next item cannot use the leftover: penalize large leftovers
            score += 0.08 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Neutral base for a new bin; slight penalty so tight existing fits win,
        // but a bonus when many bins are open with fragmented residuals.
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count >= 1 {
            score += 15.0 + 2.0 * (fitting_bins_count as f64).sqrt();
        }
        // Late in the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Global fragmentation pressure: if mean residual across open bins is low
    // (bins nearly full), discourage spreading into partially-filled bins with big leftovers.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.05 * mean_gap;

    // Mild penalty per open bin to encourage consolidation when scores are close.
    score += 0.3 * open_bins_count as f64;

    // Early-stream exploration: slightly favor new bins early to build a diverse pool.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress * 5.0);
    }

    score
}

