    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);

    // New-bin candidate: smooth preference scaling with progress and item size.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 0.15 * item_size as f64;
    }

    score
}

