    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: reward residuals that fall into
    // "useful" classes (multiples of common item sizes), penalize dead space.
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic bucket (capacity 100 -> 10 buckets)
    match class {
        0 => score -= 40.0,                 // near-perfect fit (residual < 10)
        1 => score -= 25.0,                 // residual 10..19: fits small items
        2 => score -= 15.0,                 // residual 20..29
        3 => score -= 8.0,                  // residual 30..39
        4 => score -= 2.0,                  // residual 40..49
        5 => score += 3.0,                  // residual 50..59: half-full, mediocre
        6 => score += 8.0,
        7 => score += 12.0,
        _ => score += 18.0,                 // >70 left: wasteful placement
    }

    // Modulo coupling: residual that is a multiple of common size classes (10,20,25,50)
    // is more likely reusable by future items.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 6.0;
    }
    if pr > 0 && pr % 20 == 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: slight penalty proportional to overshoot
            let over = (next_item_size - pr) as f64;
            score += 4.0 * (over / 80.0);
        }
        // Harmonic threshold on next item: big items (>50) prefer bins with small residual
        if next_item_size > 50 && pr < next_item_size {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when existing bins
    // are fragmented (high mean residual spread) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0
            + 0.15 * mean_residual
            + 10.0 * (1.0 - progress)
            - 5.0 * (open_bins_count as f64).ln().max(0.0);
        // small items at the end: prefer filling existing bins
        if item_size <= 20 {
            score += 12.0;
        }
    }

    // Prefer bins that are already fairly full (small bin_residual relative to capacity).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    // Tie-break: slight preference for lower post_residual via fine-grained term.
    score += 0.01 * pr as f64;

    score
}

