        if fill > 0.7 && post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 4.0 {
            score -= 4.0;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10)
    // are effectively unusable, but small-but-usable gaps are also risky.
    // Penalize gaps that cannot host a plausible next item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // Unusable dead space: heavy penalty, worse the closer to zero usefulness.
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual > 0 && post_residual < 20 {
        // Fragile gap: only fits tiny items; moderate penalty.
        score += 12.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Penalize wasting a very large residual on a small item (bad packing).
    if post_residual > 60 {
        score += (post_residual - 60) as f64 * 0.8;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / 100.0);
    }
    // If next item cannot fit in this bin's post_residual but could fit residual now,
    // slight penalty for consuming space the future item might want.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless pressure is high or this is a
        // poor-fit situation. Base cost of opening a bin:
        score += 25.0 + pressure * 0.4;
        // But if current bin would leave a terrible dead gap, new bin looks better:
        // (the dead-space penalties above already push score up for such bins).
    }

    // Mild tie-break toward bins whose residual is close to the mean residual
    // (keeps bin states homogeneous, easier future packing).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - (slack * 0.5).min(55.0);
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            // pair lookahead: residual reusable by next two items
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation: residual divisible by next item size
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
            }
            // triple lookahead for tight residual chains
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
        }
    }

    // dead-space penalty: small leftovers unlikely to be reused
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    // residual exactly reusable-sized band
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if dead < 0.10 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 9.0 * rem_frac;
        }
        // anti-dead-space mid-stream: residuals no item (<=100) can fully use
        if progress > 0.15 && post_residual > 100 {
            let unusable = post_residual - 100;
            score += unusable as f64 * 0.35 * rem_frac;
