            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly fits next item -> strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near-perfect chain: next item fits with small slack -> reward proportionally.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: dead space penalty, worse when
        // post_residual is just below next_item_size (tight miss).
        let miss = (next_item_size - post_residual) as f64;
        score += 12.0 + 8.0 * (1.0 - miss / next_item_size as f64);
    }

    // Penalize dead space relative to mean residual of open bins (fragmentation pressure).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.6 * (mean_residual - pr);
    } else {
        score -= 0.25 * (pr - mean_residual);
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer compacting into already-open bins over opening new ones,
    // scaled by how crowded the bin set is.
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Slight late-stream bias toward tight packing (less tolerance for slack).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (pr / bin_capacity as f64);

    // New-bin candidate (empty bin) should only win when placement here is truly bad:
    // add a fixed handicap so open bins with decent fits beat it.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

