pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Penalize placing a small item into a large-residual bin (wasting usable space).
    let waste_ratio = (post_residual as f64) / (bin_residual as f64).max(1.0);
    score += waste_ratio * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement
    // (chaining compatibility); otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer opening a new bin only when the item fits very poorly everywhere else
    // (i.e., no open bin leaves a tight post-residual).
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with tight fits win; the base post_residual
        // (= capacity - item_size) is already large, add a bias.
        score += 5.0;
        // Late in the stream, avoid spawning excess bins.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += progress * 10.0;
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer consolidating into bins with below-average residual.
    if bin_residual as f64 > mean_residual {
