pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on wasted space
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling with stream progress: waste matters more early
    score += (1.0 - progress) * norm_pr * norm_pr * cap * 0.5;

    // Perfect fit reward, stronger late in stream
    let fit_quality = 1.0 - norm_pr;
    score -= fit_quality * fit_quality * (progress + 0.2) * 30.0;

    // Dead-space avoidance: residuals too small to fit typical items
    let dead_zone = (norm_pr * 4.0 - 1.0).tanh() * 0.5 + 0.5; // smooth ramp
    score += dead_zone * pr * 0.6;

    // Lookahead: reward if next item fits the post residual (smooth interaction)
    if next_item_size > 0 {
        let next_fits = ((pr - next_item_size as f64) / cap).max(0.0);
        score -= next_fits * 25.0 * (0.5 + progress);
        // penalize leaving residual that only barely fits next item
        let squeeze = (1.0 - (pr - next_item_size as f64).abs() / cap).max(0.0);
        score += squeeze * squeeze * 5.0;
    }

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 40.0 + fit_quality * 20.0;
    }

    // Mild preference to fill bins with large residual when few bins open
    score -= (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean residual alignment: prefer bins near mean to keep diversity
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 8.0;

    // New bin candidate: penalize opening a new bin unless residual waste is tiny
    if bin_residual == bin_capacity {
        score += 55.0 - fit_quality * 30.0 + progress * 20.0;
    }

    score
}

