        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction bucket it lands in.
    // Classes: 0 (perfect fit), 1..=4 quarter classes, 5 (tiny dead space).
    let class = match post_residual {
        0 => 0,
        1..=10 => 5,
        11..=25 => 4,
        26..=50 => 3,
        51..=75 => 2,
        _ => 1,
    };
    score -= match class {
        0 => 60.0,          // perfect fit is ideal
        5 => 30.0,          // tiny dead space is acceptable waste
        4 => 8.0,
        3 => 12.0,
        2 => 18.0,
        _ => 0.0,
    };

    // Integer-division threshold: post_residual divisible classes reward compactness.
    if post_residual > 0 {
        let div = bin_capacity / post_residual.max(1);
        if div >= 2 {
            score -= 4.0 * (div as f64).min(10.0);
        }
    }

    // Lookahead harmonic coupling: does next item fit harmonically into post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        score -= 20.0;
        // Extra reward if the chain continues (modular compatibility).
        if next_post % 10 == 0 || next_post == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space that even the lookahead cannot use: penalize proportionally.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance pressure: only this bin fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when residual is large and nothing fits well.
    if bin_residual == bin_capacity {
        score += 5.0;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Late in the stream, avoid opening bins for small leftovers.
        if post_residual as f64 > bin_capacity as f64 * 0.7 {
            score += 10.0;
        }
    }

    // Mild stream-progression regularization.
    score += 0.01 * (step_index as f64 / total_items.max(1) as f64);

    score
}

