pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    }

    // Penalize gaps that cannot fit the known next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening bins unless residual pressure is high.
    if bin_residual == bin_capacity {
        score += 120.0 + 8.0 * open_bins_count as f64;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, tolerate it.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight bias toward tighter bins relative to mean residual.
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

