    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff); // perfect 2-step match gets big discount
        // Bonus if next item fits exactly after this placement
        if post_residual == next_item_size {
            score -= 40.0;
