        // fresh bin for near-full items late in stream keeps old residuals flexible
        if fitting_bins_count > 0 && progress > 0.5 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.55 && mean_residual >= item_size as f64 {
                score -= 7.0;
            }
        }
        // NEW: when few bins can host next item, prefer keeping existing residuals
        if fitting_bins_count <= 2 && next_item_size > 0 && next_item_size <= mean_residual {
            score += 8.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.92 {
            score -= 22.0 * (fill - 0.92) / 0.08;
        } else if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // strong preference for near-exact fits when few bins can host the next item
        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // penalize awkward gap just above next item when fill is low (dead space risk)
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        // reward near-perfect fill leaving residual matching mean residual band
        if fill > 0.7 && post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 4.0 {
            score -= 4.0;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // NEW: penalize leaving residual that next item almost (but not) fits
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            let miss = (next_item_size - post_residual) as f64;
            if miss < 10.0 {
                score += (10.0 - miss) * 0.8 * rem_frac;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that is too small to ever be useful again.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual < min_useful && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item cannot fit in the post residual, penalize;
    // but if the next item fits perfectly, reward leaving that space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            if post_residual - next_item_size < 5 {
                score -= 8.0; // near-perfect two-item chain
            }
        } else {
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many fitting bins, prefer the tightest; add mild competition pressure.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // open bins already fit and when many bins are already open.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 55.0;
        if fitting_bins_count > 0 {
            new_bin_penalty += 20.0 + 5.0 * fitting_bins_count as f64;
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            new_bin_penalty += 10.0;
        }
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty *= 0.6 + 0.8 * progress;
        // A big item with a big next item justifies fresh space.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            new_bin_penalty -= 25.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate fragmentation toward similar residual levels).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight global pressure: when many bins are open, discourage spreading.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
