        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // penalize awkward gap just above next item when fill is low (dead space risk)
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        // reward near-perfect fill leaving residual matching mean residual band
        if fill > 0.7 && post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 4.0 {
            score -= 4.0;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // NEW: prefer bins whose post-residual remains a clean multiple band of mean residual
        if fill > 0.55 && post_residual > 0 && next_item_size > 0
            && (post_residual as f64) >= mean_residual * 0.9 && (post_residual as f64) <= mean_residual * 1.4 {
            score -= 3.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic dead-space penalty, modulated by stream progress
    let mut score = pr + 40.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Smooth coupling: reward tight fits more strongly as stream progresses
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Lookahead coupling: cubic interaction between post_residual and next item
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        let fit_bonus = (-gap.abs() * 8.0).exp();
        score -= 15.0 * fit_bonus * (1.0 + progress);
        // penalize residuals too small for the next item (dead space)
        if gap < 0.0 {
            score += 20.0 * (-gap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: smooth function of fitting bins count
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Congestion term: many open bins -> prefer consolidating (lower residual)
    let congestion = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * congestion * norm_pr;

    // Mean-residual deviation: prefer bins near mean to keep balance, smooth
    score += 3.0 * ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap);

    score
}

