        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        // reward near-perfect fill leaving residual matching mean residual band
        if fill > 0.7 && post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 4.0 {
            score -= 4.0;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: decile buckets (capacity 100 -> 10 classes).
    let res_class = (post_residual / 10) as f64;
    let next_class = (next_item_size / 10) as f64;
    let item_class = (item_size / 10) as f64;

    // Perfect fit (residual class 0): strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residual classes 1..3 (1..=29) are hard to reuse.
    if res_class >= 1.0 && res_class <= 2.0 && post_residual > 0 {
        score += 25.0 - 8.0 * res_class;
        // But if the lookahead item fits exactly into that dead space, it's fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Reward when lookahead item fits in the post-residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        // Reward proportional to how well the next item matches the leftover class.
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 15.0 - 0.3 * chain_fit;
        // Harmonic bonus: next item class equals residual class (same decile) -> great pairing.
        if next_class == res_class {
            score -= 8.0;
        }
    }

    // Penalize placing large items into large-residual bins when a small item could later
    // use that space (integer-division threshold on item class).
    if item_class >= 5.0 && res_class >= 5.0 {
        score += 5.0;
    }
    // Reward placing large items into bins with moderate residuals (good packing).
    if item_class >= 5.0 && res_class < 5.0 {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 15.0; // near-perfect fit on last chance
        }
    }

    // New-bin candidate logic: empty bin should win only when all fits are poor.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a decent fit.
        score += 12.0;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If mean residual is large relative to capacity, prefer reusing open bins.
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 0.5;
        }
        // Late in the stream, avoid opening bins unnecessarily.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // Small items: opening a new bin for them is almost always bad.
        if item_class <= 2.0 {
            score += 20.0;
        }
    }

    // Mild pressure to keep number of open bins low.
    score += 0.15 * open_bins_count as f64;

    score
}

