        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // near-perfect fill bonus scaled by remaining stream length
        if fill >= 0.98 {
            score -= 8.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // any item (min item size 1, but realistically tiny gaps are waste) are
    // heavily penalized. Exact fits are maximally rewarded.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: bin closed
    } else if post_residual < 10 {
        // unusable dead space in the worst sense
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        // usable residual: mild reward for leaving room sized like the lookahead item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // bin stays usable for the next item
        }
    }

    // Reward tight fits: small post_residual relative to capacity is good,
    // but only when still "usable" (already handled dead-space above).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 2.0 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if the average residual across open bins is
    // large, we have slack; if small, avoid wasting this bin's remaining space.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when no
    // open bin fits well. Make the empty bin slightly unattractive by
    // default so existing bins win unless their scores are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the next item is large and this item leaves a big residual,
        // opening a fresh bin can still be sensible: soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual > 40 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
