pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    let pr = post_residual as f64;
    let nis = next_item_size as f64;

    // Lookahead: perfect match between post_residual and next item is gold
    if next_item_size > 0 {
        let diff = (pr - nis).abs();
        // reward exact match strongly
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).exp() * (1.0 - diff / 50.0);
        // penalize dead space: post_residual too small for next item (wasted)
        if pr < nis {
            score += 12.0 * (nis - pr) / 10.0;
        }
        // mildly penalize leaving large unusable gap
        if pr > nis && pr - nis > 30.0 {
            score += 0.15 * (pr - nis - 30.0);
        }
    }

    // Relative to mean residual: prefer bins that are more filled than average
    score -= 0.5 * (mean_residual - pr);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // penalize opening a new bin generally
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else if next_item_size > 0 && post_residual >= next_item_size as u32 {
            // opening a fresh bin guarantees room for the next item
            score -= 10.0;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (1.0 - pr / bin_capacity as f64);

    // Penalize very large post_residual (fragmentation) nonlinearly
    score += 0.02 * pr * pr / bin_capacity as f64;

    score
}

