    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;                       // normalized post residual in [0,1]
    let item_frac = item_size as f64 / cap;       // normalized item size
    let next_frac = next_item_size as f64 / cap;  // normalized lookahead size

    // Base: post residual (smaller residual => lower score => tighter fit preferred)
    let mut score = pr;

    // Smooth non-linear coupling of post residual with stream progress:
    // late in the stream, tight fits matter more (waste is permanent).
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= urgency * (1.0 - norm_pr) * pr * 0.5;

    // Penalize residuals that are neither tiny (perfect fit) nor large (reusable):
    // a smooth bump centered around mid residuals, weighted by progress.
    let mid_penalty = norm_pr * (1.0 - norm_pr);
    score += urgency * mid_penalty * cap * 0.35;

    // Reward bins whose leftover can hold the next item (smooth match term).
    if next_item_size > 0 {
        let fit_next = 1.0 - ((pr - next_frac * cap) / cap).abs().min(1.0);
        score -= fit_next * cap * 0.2 * (1.0 - urgency);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= cap * 0.6 * (0.5 + 0.5 * urgency);
    } else {
        // Mild penalty when many bins fit, to break ties toward tightest fit.
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Slight preference for bins below mean residual (tighter than average).
    score += (pr - mean_residual) * 0.1;

    // New-bin candidate: only attractive when the stream is young or no bin fits well.
    let is_new_bin = (bin_residual as f64 - cap).abs() < f64::EPSILON;
    if is_new_bin {
        score += cap * 0.15 * (1.0 - urgency);
        score += open_bins_count as f64 * 1.5;
    }

    score
}

