    if post_residual != 0 && post_residual % quarter == 0 {
        score -= 12.0;
    } else if post_residual != 0 && post_residual % eighth == 0 {
        score -= 6.0;
    }

    // Dead-space penalty: residual too small for the smallest conceivable item class
    if post_residual < eighth {
        score += 20.0 + (eighth - post_residual) as f64;
    }

    // Harmonic compatibility: does next item divide into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward when next item's class aligns with residual class (integer division match)
            if next_item_size % eighth == post_residual % eighth {
                score -= 10.0;
            }
            if next_item_size == post_residual {
                score -= 25.0; // exact fill of successor
            }
        } else {
            score += 8.0; // next item cannot follow here
        }
    } else {
        // last item: prefer tightest fill
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize spreading across many bins when this bin is below mean fullness
    if (post_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Prefer keeping a moderate residual for future flexibility mid-stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let ideal_residual = (quarter as f64) * (1.0 - progress);
    score += (post_residual as f64 - ideal_residual).abs() * 0.15;

    // New-bin candidate: only attractive if no open bin is a decent harmonic fit
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if post_class >= 6 {
            score -= 5.0;
        } else {
            score += 25.0; // keep filling open bins with usable residuals
        }
    }

    // Mild tie-break toward tighter fits via item-to-residual ratio
    score += (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

