            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
    }

    // mild preference to keep bins balanced late in the stream
    if progress > 0.5 {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // Small gap that only tiny items can use: heavy penalty scaled by gap smallness.
        score += (30 - post_residual) as f64 * 2.0;
    } else if post_residual >= 30 && post_residual < 60 {
        score += (60 - post_residual) as f64 * 0.5;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 200.0;
    }

    // Tight-fit reward: item consumes a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let next_waste = post_residual - next_item_size;
            if next_waste < 10 {
                score -= 60.0;
            } else {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: this bin's residual becomes dead space for the lookahead.
            score += 25.0;
        }
    }

    // Last-chance bin: only this bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins;
    // a new empty bin should only win when fits are terrible.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline.
        score = bin_capacity as f64 - 30.0;
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        } else if fitting_bins_count == 0 {
            score -= 100.0; // no existing bin fits
        } else {
            // Penalize opening new bins when decent fits exist.
            score += open_bins_count as f64 * 8.0;
            if mean_residual > item_size as f64 + 10.0 {
                score += 60.0;
            }
        }
    } else {
        // Existing bin: slight bonus when few bins are open to discourage bin proliferation.
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Late in the stream, prioritize closing bins tightly (waste is irreversible).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

