    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + lookahead_gap);
        if post_residual == next_item_size {
            score -= 50.0; // perfect two-item closure
        }
        // Penalize post_residual that can never fit typical future items
        if post_residual < 10 {
            score += 25.0; // dead space penalty
        }
    } else {
        // Last item: minimize waste directly
        score -= 40.0;
    }

    // Relative tightness vs mean residual across open bins
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize unless it's the only option,
    // but keep it attractive when all existing fits would leave big waste.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 120.0;
