pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    if is_new_bin {
        // Base cost of opening a new bin; decays slightly as stream progresses
        // (late in the stream, consolidating matters more, so new bins cost more).
        let mut new_bin_cost = 55.0 + 45.0 * progress;
        // If few bins can fit this item, the fit elsewhere is likely tight anyway;
        // opening a fresh bin is less attractive when competition is high.
        if fitting_bins_count > 0 {
            new_bin_cost += 10.0 * (fitting_bins_count as f64).min(4.0);
        }
        // If the next item is small, a fresh bin keeps flexibility — mild discount.
        if next_item_size > 0 && next_item_size <= 30 {
            new_bin_cost -= 12.0;
        }
        // If the next item is huge, prefer conserving existing large residuals;
        // opening a bin now is fine since the fresh bin can host it later.
        if next_item_size >= 70 {
            new_bin_cost -= 6.0;
        }
        score = new_bin_cost;
        return score;
    }

    // Existing-bin evaluation: primary signal is wasted space (post_residual),
    // already the base. Penalize very small post_residual only mildly — it's
    // actually good (tight fit) unless it creates unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // dead-space sliver
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Lookahead: if the next item fits exactly/comfortably in post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; if post_residual is large, this bin
            // may become stranded — slight penalty proportional to waste.
            if post_residual > 40 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state coupling: when mean residual across open bins is high,
    // there is slack in the system — be pickier (penalize mediocre fits).
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Time horizon: late in the stream, strongly prefer filling existing bins
    // to avoid ending with many nearly-empty bins.
    score += 10.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

