        score += 5.0 + new_bin;
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * cap && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    let mut score = pr;

    // Reward tight fits (small post_residual) with smooth quadratic coupling to progress
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize dead space: post residuals too small for typical future items
    let dead = norm_pr * (1.0 - norm_pr); // peaks mid-range
    score -= 4.0 * dead * (1.0 + nxt);

    // Lookahead: reward bins whose post residual can fit next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * nxt * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 {
        score += 3.0 * nxt * (1.0 - norm_pr);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * fit;
    }

    // New-bin candidate: penalize opening new bins mildly, more early in stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Reward using bins with above-mean residual (balance residuals)
        if bin_residual as f64 > mean_residual {
            score -= 2.0 * (bin_residual as f64 - mean_residual) / cap;
        }
    }

    // Smooth non-linear stream coupling: tighten packing as stream progresses
    score -= 6.0 * (progress * (1.0 - progress) * 4.0) * (1.0 - norm_pr) * fit;

    score
}

