    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since no future item (min size 1..100 stream) reliably fills them.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 12.0; // dead-space penalty
    } else if pr == 0 {
        score -= 25.0; // perfect fit reward
    } else if pr >= 10 && pr <= 20 {
        // medium gaps are semi-usable; mild penalty scaled by stream remaining
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 * (1.0 - progress);
    }

    // Reward tight fits relative to residual (waste ratio)
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_ratio;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // brand-new bin candidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 2.0 + 10.0 * (1.0 - progress);
        // If next item could combine with current in a fresh bin, mild discount
        let combo = if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            12.0
        } else {
            0.0
        };
        score += pressure - combo;
        // a fresh bin has huge post_residual; neutralize part of it for fairness
        score -= (bin_capacity as f64) * 0.5;
    }

    // Mean-residual coupling: prefer bins whose residual is below average (tighter bins)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Lookahead: if next item exactly fits post_residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the gap -> dead space confirmed
        score += (post_residual.min(20) as f64) * 0.8;
    }

    score
}

