pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 30.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else if post_residual >= next_item_size {
            score -= 6.0; // bin remains usable for the next item
        }
        // Perfect two-item closure: this item + next fill the bin exactly.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_fraction = item_size as f64 / bin_residual as f64;
    score -= fill_fraction * open_bins_count as f64 * 2.0;

    // Penalize bins whose residual is far from the mean residual (outliers waste space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate: default neutral-to-slightly-high; allow it only when
    // no open bin offers a good fit (post_residual too large relative to capacity).
    if bin_residual == bin_capacity {
        score = 40.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anywhere: must open new bin
        } else if post_residual as f64 > mean_residual * 0.9 {
            score += 10.0; // opening a bin for a poor future is wasteful
        }
    }

    // Slight early-stream preference for keeping bins open (future flexibility),
    // late-stream preference for closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 - progress * 2.0;

    score
}

