    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr
        + 40.0 * x * x * (1.0 - progress)
        - 30.0 * x * progress * progress
        + 0.05 * (mean_residual - pr).abs()
        - 5.0 * (next_item_size as f64 / cap) * x * (1.0 - x) * 4.0;

    // Penalize tight fits slightly less late in the stream; reward compacting early.
    score -= (1.0 - progress) * (item_size as f64 / cap) * 10.0;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it wins only when fits are terrible.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - (slack * 0.5).min(55.0);
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            if slack == next_item_size as f64 {
                score -= 14.0;
            }
            // pair lookahead: residual reusable by next two items
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation: residual divisible by next item size
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
                if k >= 2 && k <= 3 && fitting_bins_count <= 2 {
                    score -= 8.0;
                }
            }
            // triple lookahead for tight residual chains
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
            // mild relief when residual is near-half of next item (mergeable later)
            if waste > 6.0 && (post_residual as f64) > next_item_size as f64 * 0.45 {
                score -= 4.0;
            }
        }
    }

    // dead-space penalty: small leftovers unlikely to be reused
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    // residual exactly reusable-sized band
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
