pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band does it live in?
    let item_class = item_size / 10; // 0..=10 harmonic band
    let next_class = next_item_size / 10;

    // Perfect-fit reward: exact fill is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals below the smallest item (size 1..10) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Modulo coupling: does post_residual match a common item class boundary?
    // Residuals that are multiples of 10 are "harmonic" and likely reusable.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else {
        score += (post_residual % 10) as f64 * 0.5;
    }

    // Lookahead harmony: can the next item exactly fit the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves further residue: mild reward scaled by tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * tightness;
        } else {
            // Next item cannot use this bin's residue: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Class adjacency bonus: next item in neighboring harmonic band pairs well.
        let gap = (item_class as f64 - next_class as f64).abs();
        if gap <= 1.0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // new bins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no open bin fits, opening is necessary: reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (tighter bins first).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.4;

    // Slight pressure against accumulating many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);
    let cap = bin_capacity as f64;

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - (slack * 0.5).min(55.0);
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            // pair lookahead: residual reusable by next two items
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * cap {
                    score -= 22.0;
                }
            }
            // harmonic anticipation: residual divisible by next item size
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
            }
            // triple lookahead for tight residual chains
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * cap {
                    score -= 14.0;
                }
            }
            if next_item_size > 1 && post_residual % next_item_size == 0 && fitting_bins_count <= 2 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 3 {
                    score -= 8.0;
                }
            }
            // NEW: residual exactly equal to next item plus a small-item band
            if post_residual >= next_item_size + 1 && post_residual <= next_item_size + 6 {
                score -= 4.0;
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
        }
    }

    // dead-space penalty: small leftovers unlikely to be reused
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    // residual exactly reusable-sized band
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
