            score += 10.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * cap && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // NEW: reward near-perfect fills even more when many bins compete
        if fill > 0.95 && fitting_bins_count > 1 {
            score -= 5.0 * (fill - 0.95) / 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps just above the minimum item size are also near-unusable.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize placements that leave a gap the next item *almost* fits into.
    if next_item_size > post_residual && (next_item_size - post_residual) <= 10 {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize new-bin candidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New bin: base cost plus pressure; only attractive when it yields
        // a much cleaner residual than existing bins (handled via score).
        score += 35.0 + 10.0 * pressure;
        // But if no existing bin fits well, new bin becomes viable:
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Slight reward for choosing bins whose residual deviates from mean
        // (prefer filling below-average-residual bins).
        score -= 3.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;
    }

    score
}

