pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Perfect 2-step match: both items fill the bin exactly.
            score -= 1000.0;
        } else if diff > 0 {
            // Next item fits: reward proportionally to tightness of the pair.
            let tightness = 1.0 - (diff as f64 / bin_capacity as f64);
            score -= 300.0 * tightness;
        } else {
            // Next item won't fit here; penalize large dead space.
            score += (-diff as f64) * 0.5;
        }
    }

    // Penalize post residual that is too small to ever be useful (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 200.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual is already below mean
    // (concentrate filling), unless a perfect lookahead match exists.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 50.0 * rel;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // or when the stream is early and there is plenty of room for future items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins when a decent fit exists elsewhere.
        score += 120.0;
        // But discount the penalty early in the stream.
        score -= 100.0 * (1.0 - progress);
        // If next item is large, a fresh bin keeps flexibility.
        if next_item_size >= 50 {
            score -= 60.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 2.0 * open_bins_count as f64;

    score
}

