                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
            // NEW: residual that leaves a dead sliver just below next item size
            let gap_to_next = (post_residual % next_item_size) as f64;
            if gap_to_next > 0.0 && gap_to_next < 6.0 && post_residual > next_item_size {
                score += (6.0 - gap_to_next) * 0.8 * rem_frac;
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
            // NEW: when only one bin fits and waste is large, discourage more
            if fitting_bins_count == 1 && waste > 15.0 && progress < 0.5 {
                score += waste * 0.3;
            }
