    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(5.0);
    score += pressure * (1.0 - bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Time horizon: early in the stream, be more willing to open fresh bins;
    // late in the stream, pack tightly into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: score it against existing bins.
        let mut new_bin_score = bin_capacity as f64 - item_size as f64;
        new_bin_score += 20.0 * (1.0 - t);          // cheaper to open early
        new_bin_score -= 15.0 * t;                  // discourage late opening
        if fitting_bins_count <= 1 {
            new_bin_score += 50.0;                  // forced anyway, deprioritize
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            new_bin_score -= 12.0;                  // room for lookahead item
        }
        score = new_bin_score;
    } else {
        // Existing bin: late stream favors tight usage more aggressively.
        score -= 15.0 * t * (bin_residual as f64 / bin_capacity as f64);
    }

    // Slight penalty for very fragmented global state.
    score += 0.02 * mean_residual * (1.0 - t);

    score
}

