pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: reward small post-residual, with non-linear (quadratic) emphasis
    let mut score = x * (1.0 + 0.8 * (1.0 - x));

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, tighter packing matters more
    let tightness = 1.0 + 1.5 * progress * (1.0 - x);
    score *= tightness;

    // Penalize large dead space quadratically as stream progresses
    score += 2.0 * progress * x * x;

    // Reward exact/near-perfect fits with a smooth bump
    let fit_quality = 1.0 - x; // fraction of residual used
    score -= 1.2 * fit_quality * fit_quality * (1.0 - progress);

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Discourage opening new bins when plenty of open bins have room
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count as f64) / (open_bins_count.max(1) as f64);
        score += 2.5 + 3.0 * (1.0 - pressure) * (0.5 + progress);
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = (pr - ns).abs() / cap;
        score += 0.5 * slack * slack;
        if ns <= pr {
            score -= 0.8 * (ns / cap);
        }
    }

    // Mild penalty if this bin's residual deviates from mean residual (balance)
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    score
}

