            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // NEW: opening a fresh bin is only justified when the item is large
        // and no existing bin is a near-perfect fit
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac < 0.35 {
                score += 10.0;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // NEW: reward near-exact fill even more when few bins can host the
        // next item (keeps scarce fitting capacity intact)
        if fill > 0.75 && next_item_size > 0 && fitting_bins_count <= 2 {
            score -= 4.0 * (fill - 0.75) / 0.25;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Small mod classes (0,1,2) are near-perfect fits -> reward heavily.
    let class = (post_residual % 10) as f64;
    score -= 12.0 * (10.0 - class) / 10.0 * (post_residual as f64 / bin_capacity as f64).min(1.0);

    // Threshold on integer division: residuals < 10 are dead space.
    if post_residual < 10 {
        score -= 20.0; // prefer filling a bin into its dead zone
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // Penalize residuals that cannot hold the next item (unusable lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to tightness of the fit for the next item.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * tight;
        } else {
            score += 5.0; // leaves a gap next item cannot use
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.45 * bin_capacity as f64;
        if bad_fit {
            score -= 18.0;
        } else {
            score += 25.0; // keep good fits in existing bins
        }
    }

    // Early in the stream, opening bins is cheap; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight pull toward bins near the mean residual (balance).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

