    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;

    // New-bin candidate: neutral-ish baseline so it is chosen only when open
    // bins offer poor fits (their lookahead/dead-space penalties push them above).
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    score
}

