pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post-residual dead space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small-but-nonzero post residual is a "trap" (dead space nothing else fits)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    let pressure = open_bins_count as f64 / (total_items as f64).max(1.0);
    score += pressure * 20.0;

    // Bin residual far from mean residual: mild penalty (keep bins homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Lookahead: reward bins whose post residual matches next item size
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.08;
        } else {
            // next item cannot go here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Time horizon: late in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral baseline with adaptive threshold.
    // Prefer opening a new bin only when item is large relative to residual
    // (poor fit) or all fits would leave big dead space.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // large items open bins easily; small items should use existing bins
        score = 40.0 - fit_quality * 45.0 + progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    score
}

