    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: normalized post residual, non-linearly coupled with stream progress.
    let mut score = (pr / cap).powf(1.0 + 0.8 * progress) * cap;

    // Tight fits are rewarded more strongly as the stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space that cannot fit the (likely) next item.
    if nx > 0.0 {
        let unusable = if pr < nx { pr / nx } else { 0.0 };
        score += unusable * unusable * 8.0;
        // Reward residual that still accommodates the lookahead item.
        if pr >= nx {
            score -= 4.0 * (1.0 - pr / cap) * progress;
        }
    }

