        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-ish baseline, prefer it only when the fit is bad elsewhere.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; reward when item is large relative to residual pattern.
        let mut nb = 45.0;
        // If item is huge, opening fresh is often fine.
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            nb -= 20.0;
        }
        // If lookahead item won't fit the leftover anyway, new bin is more attractive.
        if next_item_size > 0 && next_item_size > post_residual {
            nb -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        nb += 25.0 * t;
        return nb;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tight = (post_residual as f64) / (bin_capacity as f64);
        // Penalize leaving dead space, especially small unusable slivers.
        if post_residual < 10 {
            score += 60.0; // tiny sliver is dead space
        } else {
            score -= 30.0 * (1.0 - tight);
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Lookahead coupling: reward if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item uses the leftover
            let use_frac = next_item_size as f64 / post_residual as f64;
            if use_frac > 0.5 {
                score -= 25.0 * use_frac;
            } else {
                score += 10.0 * (1.0 - use_frac);
            }
        } else {
            // next item won't fit here: penalize leaving medium-sized leftovers
            if post_residual >= 10 && post_residual < next_item_size {
                score += 15.0;
            }
        }
    } else {
        // Last item in stream: fill anything available.
        score -= 50.0;
    }

    // Global state: if mean residual is high, bins are loose; prefer filling this one more.
    let diff = mean_residual - post_residual as f64;
