pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: minimize leftover space after placement (tight fits win).
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, small residuals are mildly favored; later, residual waste is
    // penalized super-linearly to push consolidation.
    let norm_post = post / cap;
    let coupling = norm_post * norm_post * (0.5 + 2.0 * progress) * cap;
    score += coupling;

    // Reward when the next item exactly fits the post residual (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            // next item fits exactly or nearly: strong reward
            score -= (1.0 - gap / cap) * (8.0 + 6.0 * progress);
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            score += (gap / cap) * 4.0 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // Penalize bins whose residual is far from the mean (imbalance), smoothly.
    let dev = (post - mean_residual).abs() / cap;
    score += dev * dev * 6.0;

    // New-bin candidate: make it attractive only when no open bin offers a
    // good fit; otherwise keep it slightly worse than a decent existing fit.
    if bin_residual == bin_capacity {
        // New bin leaves post_residual == capacity; baseline cost is cap.
        // Discount slightly with progress so late-stage consolidation is
        // discouraged (prefer filling existing bins).
        score = cap * (1.0 - 0.15 * progress) - 5.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        }
    }

    score
}

