pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold future items (items are >= 1, but practically small gaps) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver -> heavy penalty
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual,
    // reward this placement (chaining).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }

    // Mean residual coupling: placing into a bin whose residual deviates
    // from the mean (larger residual) is preferable, keeps balance.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Slight progression pressure: late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.5;
    }

    score
}

