        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base + crowd - 10.0 * progress;
    }

    // Slight preference for tighter fits overall (small post_residual)
    score += 0.05 * post_residual as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

