    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Strongly penalize wasted residual that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is worst-case waste
    }

    // Lookahead: if the next item fits perfectly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder; slightly penalize large leftovers
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count.min(20) as f64) * (1.0 - tightness);
    }

    // New-bin candidate logic: empty bin gets a base penalty that shrinks
    // if existing fits are poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        score += 18.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
        // late in the stream, avoid opening new bins unless necessary
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean residual coupling: if this bin's leftover beats the average, reward it.
    let avg_gap = (mean_residual - post_residual as f64).abs();
    if (post_residual as f64) < mean_residual {
        score -= 3.0 * avg_gap.min(20.0);
    } else {
        score += 2.0 * avg_gap.min(20.0);
    }

    score
}

