        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // NEW: near-perfect fill bonus scaled by remaining stream length
        if post_residual <= 2 && progress < 0.85 {
            score -= 3.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in a "usable"
    // residue class (divisible by small harmonics 10, 20, 25, 50) are more
    // likely to be filled by future items.
    let harmonic_bonus = if post_residual == 0 {
        60.0 // perfect fit: strongest reward
    } else if post_residual % 50 == 0 {
        40.0
    } else if post_residual % 25 == 0 {
        30.0
    } else if post_residual % 20 == 0 {
        25.0
    } else if post_residual % 10 == 0 {
        18.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: small dead space is bad (unusable),
    // very large post_residual means we wasted a big bin on a small item.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny dead space, nearly unusable
    } else if pr >= 10 && pr < 30 {
        score -= 5.0; // sweet spot for medium items
    } else if pr > 70 {
        score += 10.0; // underfilled bin
    }

    // Lookahead coupling: reward if next item fits exactly or near-exactly
    // in the resulting residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // chain perfect fit
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of the follow-up residual
            let nxt_bonus = if (pr - next_item_size) % 25 == 0 { 20.0 }
                else if (pr - next_item_size) % 10 == 0 { 12.0 }
                else { 0.0 };
            score -= 15.0 * (1.0 - slack / bin_capacity as f64) + nxt_bonus;
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when existing fits are poor
    // (large post_residual would be created elsewhere) or few bins fit.
    if bin_residual == bin_capacity {
        score = 45.0
            - if fitting_bins_count == 0 { 100.0 } else { 0.0 }
            + (open_bins_count as f64) * 0.5
            - harmonic_bonus * 0.2;
    }

    // Late-stream consolidation: prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.3;

    score
}

