    }

    // Dead space avoidance: small unusable gaps are the enemy.
    // If post_residual is too small for the smallest possible item (1..100 unknown
    // distribution -> treat gaps below a conservative threshold as dead).
    let dead_threshold = 9.0; // below min plausible item size
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 500.0;
    }

    // Soft dead-zone: gaps that likely can't host the lookahead item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap is unusable for the next item; penalize proportionally to wasted space.
        score += 40.0 + 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap can host the next item: strong reward for chaining.
        score -= 30.0 + 0.3 * (post_residual - next_item_size) as f64;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open bins pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones; with few open bins, allow spreading.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 2.0 * pressure;
        // But if this bin is the last chance and fit is terrible, opening is fine.
        if fitting_bins_count == 1 && (post_residual as f64) > 0.6 * bin_capacity as f64 {
            score -= 200.0;
        }
    } else {
        // Existing bin: reward slightly more when many bins are open (consolidation).
        score -= 1.0 * pressure.min(10.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin unless the fit is awful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
