pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post-residual can accommodate the next item comfortably
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Penalize dead space relative to mean residual across open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 1.5 * (mean_residual - pr);
    } else {
        score -= 0.5 * (pr - mean_residual).min(50.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize very small unusable residuals (< 10) — dead space
    if post_residual < 10 {
        score += 30.0;
    }

    // Early in the stream, keep bins tight; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight preference for bins that are already well-filled
    score -= 0.3 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    // New-bin candidate: only attractive if item is huge relative to capacity
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * item_size as f64;
    }

    score
}

