        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if next item fits in the post-residual, big reward.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize wasting this bin's space.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins, more when many open bins
    // or when some existing bin fits reasonably well.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            // Compare: how well would the item fit an existing bin?
            let existing_waste = (bin_capacity as f64 - item_size as f64) - mean_residual.min(bin_capacity as f64 - item_size as f64);
            score += 10.0 * (1.0 - (mean_residual / bin_capacity as f64)).max(0.0);
            let _ = existing_waste;
        }
        // Late in the stream, opening new bins is cheaper (fewer future items to consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Prefer bins whose residual is close to mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Global pressure: when few bins fit the item, favor filling this one.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

