            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // mutation: mild preference for fills whose post_residual stays within the
        // reusable band relative to mean residual (keeps future fits flexible)
        if post_residual > 0 && next_item_size > 0 && (post_residual as f64) >= mean_residual * 0.9 && (post_residual as f64) <= mean_residual * 1.1 {
            score -= 3.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: residual quantized into capacity fractions (1/8 classes)
    let frac = post_residual as f64 / bin_capacity as f64;
    let cls = (frac * 8.0).floor() as i32; // 0..8 harmonic class

    // Reward tight fits: lower class = tighter fill
    score -= (8 - cls) as f64 * 4.0;

    // Penalize dead space that is too small for the smallest item (1..100 unknown range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo coupling: post_residual mod 10 — small remainders are wasteful
    let rem10 = post_residual % 10;
    score += rem10 as f64 * 0.8;

    // Integer-division threshold on next_item_size: does the item's complement
    // pair with the lookahead? Reward when next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chain placement possible
            // extra reward if lookahead exactly divides post_residual
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0; // lookahead won't fit here
        }
        // harmonic class match between complement and lookahead
        let next_cls = (next_item_size as f64 / bin_capacity as f64 * 8.0).floor() as i32;
        if (next_cls - cls).abs() <= 1 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // unless item is huge relative to mean residual (poor fit everywhere)
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) > mean_residual + 0.5 * bin_capacity as f64;
        if poor_fit {
            score -= 15.0; // open new bin rather than wreck an old one
        } else {
            score += 18.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Prefer dense bins (below mean residual means this bin is tighter than average)
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Late-stream consolidation: as stream progresses, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.15;

    score
}

