pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small to ever be usable (assume min item ~1,
    // but practically gaps < 10 are near-waste; escalate for tiny gaps).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 25 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin used.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creates a gap the next item cannot use: penalize.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if no open bin fits well, new bin becomes attractive relative to bad fits.
        if item_size as f64 / bin_capacity as f64 > 0.5 {
            score -= 25.0;
        }
    } else {
        // Slight preference to fill already-open bins as stream progresses.
        score += 2.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Prefer bins whose residual deviates below the mean (fill the emptier ones less,
    // concentrate waste): reward bins tighter than average.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    score
}

