pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leave no dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 500.0; // exact 2-chain match
        } else {
            score -= 150.0 / (1.0 + gap);
        }
    } else if next_item_size > 0 {
        // Next item cannot use the residual: penalize proportionally to wasted capacity.
        score += (next_item_size as f64).min(post_residual as f64 + 1.0) * 0.5;
    }

    // Prefer bins with residual below the mean (tighter bins first), keep fat bins for big items.
    score -= (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits extremely well
    // (residual after placement small enough to plausibly host future items).
    if bin_residual == bin_capacity {
        score += 200.0;
        if post_residual <= 20 {
            score -= 250.0; // opening is fine if item nearly fills a fresh bin
        }
    }

    // Slight preference to fill older/more crowded bins rather than proliferate bins.
    score -= open_bins_count as f64 * 0.1;

    // Late in stream: prioritize compactness over preserving space.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

