                score -= 6.0 * rem_frac;
            }
        }
        // new: penalize residuals that cannot hold next item even after this one,
        // but only when other bins could absorb the next item instead
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && fitting_bins_count > 1 {
            score += 5.0 * rem_frac;
        }
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // new: opening a fresh bin for a large item whose complement matches
        // the mean residual size preserves future packing options
        if next_item_size > 0 && frag < 0.30 && item_size >= 60 && (bin_capacity - item_size) as f64 >= mean_residual * 0.9 {
            score += 8.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // new: extra reward for near-perfect fills that leave no dead space
        if fill > 0.95 && post_residual == 0 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u64) <= post_residual as u64 {
        let leftover_after_next = post_residual as i64 - next_item_size as i64;
        score -= 15.0 + 0.2 * leftover_after_next.max(0) as f64;
    } else if next_item_size > 0 && (next_item_size as u64) > post_residual as u64 {
        // Penalize leaving dead space the next item cannot use.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely useful
    // (e.g., no good existing fit or early stream with few bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base_penalty = 12.0 + 18.0 * progress;
        // Opening a bin is more attractive when many bins are open and residuals are large.
        let relief = 0.05 * open_bins_count as f64 + 0.1 * mean_residual;
        score += base_penalty - relief.min(20.0);
        // If the next item is big and would pair well with this item in a fresh bin, soften penalty.
        if next_item_size >= 40 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild global pressure: when mean residual is high, prefer bins that reduce variance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Time horizon: late in the stream, avoid creating tiny unusable residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * (0.5 + progress);
    }

    score
}

