pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post-residual cost, non-linearly scaled
    let mut score = pr * pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fills matter more (dead space penalty grows)
    let coupling = pr / cap;
    score += coupling * (0.5 + 2.0 * progress * progress) * 30.0;

    // Reward filling bins tightly: subtract for low post_residual, smoothly
    score -= (1.0 - coupling) * (1.0 - coupling) * 25.0;

    // Penalize bins whose post-residual is awkward relative to mean residual
    let dev = pr - mean_residual;
    score += dev * dev / cap * 0.5;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward leaving space for the next item, penalize blocking it
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= (1.0 - ((pr - n) / cap).powf(2.0)) * 12.0;
        } else {
            score += (n - pr) * 0.6;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3 * (1.0 - coupling);

    // Favor opening a new bin only when the current bin's residual would be tiny
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

