pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals in "nice" classes (multiples of 10, or small complements) are more reusable.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -6.0,                       // perfectly harmonic residual
        1 | 9 => 2.0,                    // awkward sliver
        2 | 8 => 1.0,
        5 => -3.0,                       // half-class, very reusable
        _ => 0.5,
    };
    score += class_penalty;

    // Integer-division threshold: residual bucket by capacity / 4
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 8.0;                    // dead space penalty
    } else if post_residual < 2 * quarter {
        score -= 1.0;
    } else {
        score -= 2.0;                    // roomy residual is good
    }

    // Lookahead coupling: does this bin's post residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // exact harmonic match with next item is highly desirable
            if post_residual == next_item_size {
                score -= 10.0;
            }
            // next item lands this bin into a harmonic class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else {
            score += 4.0;                // bin becomes dead after this placement
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate: make it attractive only when current bins would waste badly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer new bin early or when item is large relative to mean residual
        let waste_if_used = (mean_residual - item_size as f64).max(0.0);
        score = 12.0 + waste_if_used - 8.0 * progress;
        if item_size >= 3 * quarter {
            score -= 6.0;                // big items deserve fresh bins
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0;                // fresh bin serves the future too
        }
    }

    // Mild pressure against bin proliferation
    score += 0.05 * open_bins_count as f64;

    score
}

