            score += 3.0 * rem_frac;
        }
        // new: reward near-full fills more strongly when many open bins compete
        if fill > 0.8 && open_bins_count > 6 {
            score -= 4.0 * (fill - 0.8) / 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that future items
    // (mod-10 classes) can still fill exactly.
    let post = post_residual;
    let class = post % 10;
    // Residuals divisible by 10 are "harmonic" with the item-size grid.
    if class == 0 && post > 0 {
        score -= 12.0; // perfect-decade residual, highly reusable
    } else if class <= 2 || class >= 8 {
        score += 3.0; // near-decade but not exact: awkward dead space
    }

    // Small residuals are dead space unless they exactly match a likely item.
    if post < 10 {
        score += 15.0;
    }

    // Integer-division thresholds: can next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // lookahead fits: strong reward, scaled by how tightly it fits
            let tightness = (post - next_item_size) as f64;
            score -= 20.0 - tightness * 0.3;
        } else {
            // lookahead cannot use this bin's remainder
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Brand-new empty bin candidate: only attractive when current bin would
    // leave large unusable residue and the item is large.
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly; offset when item is big
        score += 10.0 - (item_size as f64) * 0.15;
    }

    // Prefer fuller bins: reward low relative residual via capacity fraction.
    let frac = post as f64 / bin_capacity as f64;
    score += frac * frac * 20.0;

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    // If mean residual is low, keeping tight fits matters more.
    if (post as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

