    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (next_item_size as f64) * 0.25;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating dead space the lookahead cannot use, scaled by how dead it is.
        let dead = post_residual as f64;
        if dead > 0.0 && dead < next_item_size as f64 {
            score += dead * 0.3;
        }
    }

    // Prefer tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, mildly prefer keeping low-fit bins in reserve; prefer larger residuals elsewhere.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Global state coupling: when mean residual is high, spreading items is cheap;
    // when mean residual is low, avoid wasting the few remaining large gaps.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += mean_gap * 0.05;

    // Penalize opening a new bin (residual == capacity) especially early in the stream
    // or when many bins are already open with usable space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
    }

    // Slight preference to fill bins that are already quite full.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill * 5.0;

    score
}

