pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;

    // Non-linear penalty on post_residual, weighted by stream progress:
    // later in the stream, wasted space matters more (quadratic coupling).
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.5;

    // Reward tight fits via smooth exponential-like term (bounded polynomial proxy).
    let tightness = 1.0 - (pr / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bin: smooth reward ramping with progress.
    if fitting_bins_count == 1 {
        score -= 5.0 + 5.0 * progress;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 * (1.0 - ((pr - next_item_size as f64) / cap).abs());
    }

    // Penalize bins far from mean residual (smooth dispersion penalty).
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Slight penalty when many bins are open (encourage consolidation early).
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * fit;

    score
}

