            score += 5.0 * rem_frac;
        }
        // NEW: reward residuals that can still hold the mean-size future item
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as f64) <= mean_residual.max(1.0) * 1.2 && progress > 0.25 {
            score -= 4.0 * rem_frac;
        }
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // NEW: opening a fresh bin for a large item that leaves a perfectly
        // next-item-shaped residual is a strong compaction move
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size && (bin_capacity - item_size - next_item_size) < 4 {
            score -= 16.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 12 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // NEW: when many bins fit, mildly prefer the emptiest-fit to consolidate
        // waste into fewer bins (reduces residual fragmentation across the fleet)
        if fitting_bins_count > 4 && fill < 0.4 {
            score += (fitting_bins_count as f64).min(10.0) * 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    // into "usable" bands. Small leftovers (<20) are dead space -> penalize.
    let small_dead = (post_residual < 20) as i32;
    let perfect = (post_residual == 0) as i32;

    // Reward near-perfect fits strongly.
    score -= 40.0 * perfect as f64;
    // Penalize tiny dead space non-linearly.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Harmonic complementarity: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let chain_left = post_residual - next_item_size;
            // reward chains leaving small-but-not-dead residues in band [10,30]
            if chain_left <= 30 {
                score -= (30 - chain_left) as f64 * 1.5;
            } else {
                score += (chain_left as f64 - 30.0) * 0.3;
            }
        } else {
            // next item cannot use this bin's leftover; mild penalty scaled by gap
            score += (next_item_size - post_residual).min(30) as f64 * 0.4;
        }
    }

    // Modulo-arithmetic class of residual: residues divisible by 10 pair well
    // with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin
    // would leave large awkward residue and mean residual is already high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = (bin_residual - item_size) as f64;
        if awkward > 40.0 || mean_residual > 45.0 {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 15.0; // discourage opening new bins when fits are decent
        }
    }

    // Prefer denser bins (below-mean residual) among open bins.
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Slight late-stream conservatism: keep scores stable, tiny tie-break noise
    // via deterministic coupling on step_index.
    score += ((step_index % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
