pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Small but potentially usable gaps: mild penalty, scaled by gap size.
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 4.0 * pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 20.0; // dead space confirmed by lookahead
        }
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // But if this bin is the only fitting bin, opening new is competitive.
        if fitting_bins_count == 1 {
            score -= 55.0;
        }
        // Early in stream, allow more bins; late, discourage sprawl.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            score -= 10.0; // next item won't fit here anyway in a tight sense
        }
    }

    // Slight preference for bins with residual close to item size (best-fit core).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    score
}

