        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // mutation: stronger penalty for leaving residual just below next item size
        // (guaranteed dead space unless a smaller item arrives)
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let miss = next_item_size - post_residual;
            if miss <= 8 {
                score += miss as f64 * 0.8 * rem_frac;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal dead space after placement.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (next item exactly fills leftover) -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: reward tightness of that secondary fit.
            score -= 25.0 - gap * 0.5;
        } else {
            // Next item cannot follow into this bin: penalize proportional to overflow gap.
            score += gap * 0.35;
        }
    }

    // Reward leaving residuals near the small-item floor (unusable dead space penalty).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny useless sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: placing into a below-average bin balances the pool.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // New-bin candidate handling: prefer opening a new bin only when all open bins
    // would leave large dead space or the bin pool is small/early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Mild baseline so a new bin loses to decent fits but wins over bad ones.
        score += 15.0 + progress * 10.0;
        // If next item is large and current item is small, new bin can host future pairs.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Slight preference to fill fuller bins first (larger item_size relative to residual).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

