        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // new mutation: large items into fresh bins when few bins fit them anyway
        if fitting_bins_count <= 2 && item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 8.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // new mutation: mild reward for near-perfect fills with lookahead safety
        if fill > 0.95 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small residuals are "harmonically closed"
    // (waste is bounded), large residuals that are NOT multiples of common item
    // classes are dead-space risks.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if pr <= 10 {
        // Unusable sliver for items >= 1... but tiny items exist; mild reward for near-perfect.
        score -= 120.0 - (pr as f64) * 6.0;
    } else {
        // Penalize residuals that cannot combine with the next item (lookahead coupling).
        if next_item_size > 0 {
            if next_item_size > pr {
                // Next item can't use this bin's leftover at all: dead-space penalty
                // proportional to how much of the residual is stranded.
                score += 0.35 * (pr as f64);
            } else {
                // Next item fits: reward proportional to how fully it would fill.
                let fill_frac = next_item_size as f64 / pr as f64;
                score -= 60.0 * fill_frac;
                // Harmonic bonus: next item exactly closes the bin afterwards.
                if pr - next_item_size == 0 {
                    score -= 200.0;
                } else if pr - next_item_size < 10 {
                    score -= 40.0;
                }
            }
        }

        // Modulo-class analysis of residual against capacity fractions.
        // Residuals in harmonic classes {0, 25, 50, 75} of 100 combine well with
        // typical item sizes; others get graded penalties.
        let q = pr / 25;
        let r = pr % 25;
        let class_penalty = match q {
            0 => 0.0,             // 1..24: partial class
            1 => 5.0,             // 25..49
            2 => 10.0,            // 50..74
            3 => 15.0,            // 75..99
            _ => 0.0,
        };
        score += class_penalty + 0.25 * (r as f64);

        // Integer-division threshold: residuals that are exact multiples of 10
        // align with common item sizes (10..80 in decades) -> small reward.
        if pr % 10 == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins unless the fit into
    // existing bins is truly bad. Base penalty grows with number of open bins.
    if bin_residual == bin_capacity {
        score += 60.0 + 6.0 * (open_bins_count as f64);
        // But if item is large, a fresh bin gives maximal future flexibility.
        if item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Prefer bins whose residual is already below the mean (tighten tight bins),
    // spreading large residuals across bins.
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.10 * diff;

    // Mild preference for bins with many competitors avoided: if several bins fit,
    // keep ranking driven mainly by post_residual (already dominant).

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
