pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful later are pure waste.
    // Treat post_residual < 10 (or < smallest plausible item) as dead space -> heavy penalty.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 500.0;
    } else if post_residual < 10 {
        // Unusable sliver: penalize proportionally to how close to a perfect fit it looked.
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        // Usable residual: mild quadratic penalty to prefer tighter fits among usable options.
        score += (post_residual as f64).powi(2) * 0.01;
    }

    // Reward bins whose residual was already small (compacting large items first).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }
    // Many fitting bins: mild penalty to spread preference toward best-fit only.
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(10.0);
    }

    // Open-bin pressure: penalize placements that keep many bins alive when mean residual is high.
    score += open_bins_count as f64 * 0.5;
    score += (mean_residual - post_residual as f64) * 0.2;

    // Lookahead: if next item fits exactly in post_residual, big reward; if post_residual
    // can't hold next item but bin_residual could have, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive early (plenty of stream left
    // to fill it) but expensive late. Base score for empty bin should be competitive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early: cheap to open; late: expensive, prefer existing bins / tight fits.
        score = 40.0 + progress * 120.0 - (item_size as f64 * 0.3);
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
        }
        if fitting_bins_count == 1 {
            score += 60.0; // don't abandon the last-chance bin
        }
    }

    score
}

