pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match with next item
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        if pr >= nx {
            // next item fits perfectly -> big reward
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 40.0;
            }
        } else {
            // post_residual too small for next item; penalize if the leftover
            // is dead space (below typical minimum item size)
            if pr < 1.0 {
                score += 0.0;
            }
            // small residual unusable-ish: mild penalty proportional to wasted space
            score += 0.5 * pr;
        }
    }

    // Compare post_residual against mean residual: leaving near-average slack is fine,
    // leaving far below mean wastes bin utility
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.3 * (mean_residual - pr);
    } else {
        score -= 0.1 * (pr - mean_residual);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize unless nothing else is good
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64;
        // but if no open bin fits, new bin is the only option; fitting_bins_count
        // counts fitting open bins, so a lone new-bin call still gets high score
        // unless lookahead makes it attractive — keep penalty dominant.
    }

    // Slight preference to consolidate into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

