pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10.
    let pr = post_residual;
    let class = pr % 10;
    // Small residues (0..3) are "harmonically usable" dead space -> reward.
    if class <= 3 {
        score -= 6.0 - 2.0 * class as f64;
    } else if class >= 7 {
        // Large residue classes tend to be dead space -> penalize.
        score += (class - 6) as f64 * 2.0;
    }

    // Perfect fit is always excellent.
    if pr == 0 {
        score -= 40.0;
    }

    // Reward if the lookahead item fits the post residual exactly (chained packing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // Next item fits, but leaves a residue; reward scaled by how tight.
            let nr = pr - next_item_size;
            score -= 12.0 - (nr % 10) as f64 * 0.8;
        } else {
            // Next item cannot use this bin's remainder: mild penalty scaled by gap.
            score += ((next_item_size - pr) as f64).min(30.0) * 0.3;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer bins where the fit is tightest (handled by base),
        // but add slight dispersion penalty so we don't always spread load.
        score += 1.5;
    }

    // Fractional capacity coupling: reward filling bins past harmonic thresholds
    // (25%, 50%, 75% used).
    let used_frac = (bin_capacity - pr) as f64 / bin_capacity as f64;
    if used_frac >= 0.75 {
        score -= 8.0;
    } else if used_frac >= 0.5 {
        score -= 4.0;
    } else if used_frac >= 0.25 {
        score -= 1.0;
    }

    // New empty bin candidate: penalize unless open bins are crowded or item is large.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let crowd = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        let big_item = (item_size > bin_capacity / 2) as f64;
        score += 25.0 - crowd.min(20.0) - big_item * 10.0;
    }

    // Late in the stream, close out bins aggressively (avoid stragglers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Mild preference toward bins tighter than the current mean residual.
    score += (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.2;

    score
}

