    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only option
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.35 * (1.0 - progress);

