        // Next item cannot fit anywhere else in this chain anyway
        if post_residual < next_item_size {
            score += 25.0;
        }
    } else {
        // Last item: minimize leftover
        score -= 20.0;
    }

    // Penalize dead space that is too small for typical items (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual across open bins
    let cap = bin_capacity as f64;
    let mean_gap = (post_residual as f64 - mean_residual) / cap;
    score += 15.0 * mean_gap;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Early in stream: encourage compact packing, avoid bin proliferation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt());

