pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large relative post-residual more strongly.
    let tightness = post_residual as f64 / cap;
    score += 2.0 * tightness * tightness * cap;

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Leaving residual that next item cannot use: mild penalty scaled by wasted space.
            score += 3.0 * ((post_residual as f64).min(nxt) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    // (large dead space) or many bins already open and residual is fragmented.
    if bin_residual == bin_capacity {
        let dead = post_residual as f64; // full remaining capacity of a fresh bin
        let poor_fit = (bin_residual - item_size) as f64 / cap;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins normally, discount penalty when fit elsewhere is bad.
        score = dead - 40.0 + 45.0 * poor_fit + 20.0 * pressure * (0.5 + 0.5 * progress);
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.3 * mean_residual;
    }

    // Mild bonus for bins below mean residual (keeps residual distribution balanced).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    // Slight time-varying consolidation pressure: later in stream, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

