pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot" of capacity it falls into.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let cls = (post_residual / eighth) as f64; // 0..=8 class index

    // Reward small post_residual (tight fits), with non-linear emphasis.
    score -= (cap - post_residual as f64) * 0.35;

    // Harmonic dead-space penalty: residuals in the awkward middle classes
    // (too small for typical items) are penalized super-linearly.
    let awkward = (post_residual > 0 && post_residual < 10) as u32;
    score += awkward as f64 * 60.0;

    // Integer-division threshold: post_residual divisible by common item sizes
    // is a perfect future fit (reward).
    let perfect = (post_residual >= 10
        && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0)) as u32;
    score -= perfect as f64 * 12.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // next item leaves another harmonic residue
        let nxt_post = post_residual - next_item_size;
        if nxt_post % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // this bin becomes dead after this placement; penalize by class
        score += cls * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when
    // existing fits are poor (their scores stay high via penalties above).
    if bin_residual == bin_capacity {
        score = cap * 0.9;
        // early stream: prefer consolidation less
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // many open bins: opening another is fine
        score -= (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Modulo class of item_size against residual: near-full wrap reward.
    if item_size as f64 / cap > 0.8 {
        score -= 10.0; // big items should go somewhere, anywhere
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
