    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable dead space.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0; // heavy penalty for tiny unusable gaps
    }
    // Penalize mid-range gaps that can't fit the smallest plausible item (1..100 range: gap < ~15 is near-dead)
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Perfect / near-perfect fits strongly rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= (gap == 0) as i32 as f64 * 80.0;
        score -= ((100.0 - gap as f64) / 100.0) * 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: leftover becomes dead space
        score += 10.0;
    }

    // Open-bin pressure: discourage proliferating bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bins should only win when all fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 0.5;
        // late in the stream, prefer consolidation into open bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    }

    // Prefer filling bins with larger residual (best-fit flavor) relative to mean.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

