            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // strong preference for near-exact fits when few bins can host the next item
        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // penalize awkward gap just above next item when fill is low (dead space risk)
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        // reward near-perfect fill leaving residual matching mean residual band
        if fill > 0.7 && post_residual > 0 && (post_residual as f64 - mean_residual).abs() < 4.0 {
            score -= 4.0;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // penalize mid-range fills that strand residual between item-size bands
        if fill > 0.35 && fill < 0.7 && post_residual > 20 && (post_residual as f64) < mean_residual {
            score += 3.0 * rem_frac;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, with non-linear shaping (quartic trough penalizing tiny dead space)
    let mut score = pr
        - 18.0 * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm)
        + 30.0 * pr_norm * pr_norm * pr_norm * pr_norm;

    // Smooth stream-progress coupling: later in stream, reward tight fits more
    score *= 1.0 + 0.6 * progress * (1.0 - pr_norm);
    score -= 12.0 * progress * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 6.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > post_residual {
        score += 4.0 * progress;
    }

    // Last-chance bin: penalize opening new bin by rewarding this one
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Mean-residual dispersion coupling (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - pr_norm);

    // Mild penalty for many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // New-bin candidate: neutral-ish baseline, only attractive when fits are bad
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.35 * progress) + 5.0 * pr_norm;
    }

    score
}

