        score += (next_item_size as f64 - post_residual as f64) * 0.35;
    }

    // Penalize small unusable leftovers (dead space), scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 + 10.0 * progress;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

