            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // Prefer fresh bin when no open bin leaves room for the next item.
        if next_item_size > 0 && fitting_bins_count > 1 && (bin_capacity as u32).saturating_sub(item_size) < next_item_size {
            score += 0.8;
        }
    } else {
        let fill = item_size as f64 / br;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && pr < 0.05 * cap && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
