        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below a
    // plausible next-item threshold is wasted. Penalize residuals that are
    // "useless" (too small to host typical items).
    let useless = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
    score += useless;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; mild penalty proportional to leftover.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (post_residual large relative to mean residual) or when
    // many bins are open (fragmentation risk).
    if bin_residual == bin_capacity {
        let decent = (mean_residual - item_size as f64).max(0.0);
        let pressure = open_bins_count as f64 / 20.0;
        score = 100.0 + pressure * 30.0 - decent * 0.8;
        if post_residual >= 50 { score -= 10.0; }
    } else {
        // Prefer bins with residual close to item size (relative fit quality).
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fit_ratio;
        // Spread load across bins when many are open and mean residual is high.
        if mean_residual > 60.0 && post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Time horizon: early in stream, be conservative (favor tight packing);
    // late in stream, avoid leaving tiny residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

