pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Core: quadratic coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear fit-quality term: reward tight fits smoothly
    score -= 30.0 * (1.0 - pr_norm).powi(3) * (1.0 - progress);

    // Penalize large dead space non-linearly
    score += 15.0 * pr_norm * pr_norm * (0.5 + progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead coupling: reward if next item fits smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if nx <= pr { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * (nx / cap);
    }

    // Mild pressure to consolidate when many bins open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer typical bins
    score += 0.1 * (pr - mean_residual).abs();

    score
}

