    // Useful classes: 0 (perfect), and small residuals that other items can top off.
    if res == 0 {
        score -= 40.0; // perfect fit, reward strongly
    } else if res >= 10 {
        // Fractional waste relative to capacity
        let waste_frac = res as f64 / cap;
        score += waste_frac * 30.0;
        // Penalize awkward residues (odd, non-multiples of 5) which are hard to fill
        if res % 5 != 0 {
            score += 6.0;
        }
        if res % 2 == 1 {
            score += 2.0;
        }
        // Integer-division tier: residuals in [50, 100) are still very reusable
        let tier = res / 25; // 0..4
        score -= tier as f64 * 4.0;
    } else {
        // residual 1..9: mostly dead space unless it matches a small item class
        score += 10.0;
        // small residuals that could fit a 10-class item are okay
        score += residue * 0.5;
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // chain fit: excellent
        } else if post_residual >= next_item_size {
            score -= 8.0; // can still host next item
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3; // stranded capacity
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins are crowded.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above good fits; drop it if bins are tight.
        let tightness = if mean_residual > 0.0 { mean_residual / cap } else { 1.0 };
        score = cap as f64 * 0.5 + (1.0 - tightness) * 20.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin anyway
