pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it uses the leftover.
            score -= 0.6 * (next_item_size as f64 / post_residual as f64) * 100.0;
        } else {
            // Next item won't fit here: penalize large dead space.
            score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Compare residual against mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist (empty-bin candidate gets a penalty
    // unless residuals everywhere are poor).
    if bin_residual == bin_capacity {
        score += 120.0 - 0.4 * mean_residual;
    }

    // Late in the stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small penalty per open bin to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

