        if fill > 0.75 && post_residual > 0 && post_residual < 8 {
            score += (8 - post_residual) as f64 * 1.8 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, but with non-linear (quartic) dead-space penalty
    let mut score = 2.5 * x + 1.8 * x * x + 1.2 * x * x * x * x;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate loose fits (spread items); late, demand tight packing
    let progress_coupling = (0.9 - 1.6 * progress + 0.9 * progress * progress) * x * (1.0 - x) * 4.0;
    score += progress_coupling;

    // Reward filling a bin nearly exactly, weighted by progress
    let perfect = (cap - pr) / cap; // fill fraction
    score -= 1.5 * perfect * perfect * (0.6 + 0.8 * progress);

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 - (pr - nxt) / cap } else { 0.0 };
        score -= 1.1 * fit_next * fit_next;
        // penalize post residual that wastes space relative to next item
        let waste = ((pr - nxt) / cap).max(0.0);
        score += 1.4 * waste * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.2 + 1.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild preference when many alternatives exist
        score += 0.15 * (fitting_bins_count as f64).ln();
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced)
    let dev = (pr - mean_residual) / cap;
    score += 0.6 * dev * dev;

    // Slight penalty for proliferating open bins early
    score += 0.03 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate bias: only attractive when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        let badness = x * x; // placing here wastes the whole empty bin potential
        score += 0.4 + 2.0 * badness - 1.2 * (1.0 - perfect);
        if fitting_bins_count >= 1 {
            score += 0.5; // discourage opening new bin when alternatives exist
        }
    }

    score
}

