        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // mutation: discourage leaving residuals below mean demand that nothing will reuse
        if post_residual > 0 && next_item_size > 0 && (post_residual as f64) < mean_residual * 0.5 && (post_residual as u32) < next_item_size {
            score += 5.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions
    let item_class = item_size / 10;              // 0..10 harmonic class
    let post_class = post_residual / 10;          // residual class after placement

    // Perfect fits (post_residual == 0) are gold
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward small post_residual, but penalize "dead" residuals that no
    // small item (>=1) can usefully fill; residual classes 1..9 are the
    // awkward zone. Harmonic penalty grows for mid classes.
    let harmonic_penalty = match post_class {
        0 => 0.0,
        1 => 8.0,
        2 => 14.0,
        3 => 18.0,
        4 => 20.0,
        5 => 18.0,
        _ => 12.0,
    };
    score += harmonic_penalty;

    // If next item fits exactly into post_residual, big reward (pairing)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: reward proportional to how well it fills
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * fill;
    } else if next_item_size > 0 {
        // next item would not fit here: mild penalty for blocking lookahead
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Modulo coupling: items whose class complements residual to 10 (full decade)
    if (item_class + post_class + (post_residual % 10 > 0) as u32) == 10 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a bin, softened if many bins already open
        score += 25.0;
        if item_size >= 60 {
            score -= 15.0; // big items start fresh bins happily
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
        if fitting_bins_count > 0 {
            // penalize new bin more if a decent fit exists elsewhere
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Early in the stream, keep bins tight; later, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0 * open_bins_count as f64 / 10.0;

    // Nudge toward bins with residual above mean (balance avoidance of many half-empty bins)
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
