    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 10) can use
    // are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 1000.0;
    } else if post_residual == 0 {
        // Perfect fill is ideal.
        score -= 500.0;
    }

    // Non-linear tightness reward: quadratic reward for small usable leftovers.
    score -= (100.0 - post_residual as f64).powi(2) * 0.05;

    // Penalize bins whose residual deviates far from the mean residual
    // (keep bin states homogeneous, easier to pack future items).
    score += (bin_residual as f64 - mean_residual).abs() * 0.5;

    // Open-bin pressure: discourage spreading across many bins.
    if bin_residual < bin_capacity {
        score -= 5.0; // slight preference for existing bins over new bins
        score += open_bins_count as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // if post-residual is small but nonzero and next item won't fit, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual > 0 {
            score += 40.0;
        }
    }

    // Early in the stream, be more tolerant of opening bins (exploration);
    // late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 + 80.0 * progress; // new bins get progressively worse
    }

    score
}

