pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for any plausible item (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for a near-perfect chain fit.
            let chain_left = post_residual - next_item_size;
            if chain_left < 10 {
                score -= 10.0;
            }
        } else {
            // Penalize leaving residual too small for the known next item.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Fragmentation pressure: many open bins with high mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score -= 5.0 * mean_residual / bin_capacity as f64;
    }

    // Late in the stream, consolidation matters more.
    score -= 6.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for new bin; reduced if the item is large and current bins are fragmented.
        let mut new_bin_penalty = 45.0;
        if item_size >= 70 {
            new_bin_penalty -= 10.0;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 40.0;
        }
        // If the only fitting bin would leave a very poor residual, allow opening a new bin.
        if fitting_bins_count == 1 {
            let worst_case_waste = (bin_residual - item_size) as f64;
            if worst_case_waste > 0.0 && worst_case_waste < 10.0 {
                new_bin_penalty -= 15.0;
            }
        }
        score += new_bin_penalty;
        // A fresh bin gives a perfectly predictable residual equal to item's complement.
        score -= 5.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild preference for bins whose residual deviates favorably from the mean.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

