    // Lookahead bonus: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0 + 0.25 * (next_item_size as f64);
    }
    // If next item would NOT fit here but fits a fresh bin, discourage near-full fills
    // that strand the next item.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins with high mean residual: prefer consolidation into fuller bins.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.08 * residual_gap; // bins with less residual than average get lower score
    score += 0.03 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate logic: opening a new bin is attractive only for large items
    // or when the current bin leaves an awkward remainder.
    if bin_residual == bin_capacity {
        let awkward = post_residual > 0 && post_residual < 10;
        let big_item = item_size > bin_capacity / 2;
        if awkward || (big_item && open_bins_count > 2) {
            score -= 8.0 + 0.05 * open_bins_count as f64;
        } else {
            score += 12.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Mild time-horizon modulation: late in stream, be greedy about tight fits.
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

