    // modulated by stream progress (later in stream -> punish dead space more).
    let waste_coupling = norm_pr * norm_pr * cap * (0.5 + 1.5 * progress);
    score += waste_coupling;

    // Smooth reward for tight fits: exp-like decay on small residuals.
    let tightness = (-norm_pr * 8.0).exp();
    score -= tightness * cap * 0.6;

    // Last-chance bin: strong smooth bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Lookahead: reward leaving space that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let gap_norm = gap / cap;
        score += gap_norm * gap_norm * cap * 0.35;
        if pr >= nx {
            score -= 6.0 * (1.0 - gap_norm);
        }
    }

    // Prefer filling bins with lower residual relative to mean (balance avoidance
    // of many half-empty bins), smoothly via mean_residual coupling.
    let mean_dev = (mean_residual - pr) / cap;
    score += mean_dev * mean_dev * cap * 0.15;

    // Mild penalty for spreading across too many open bins as stream progresses.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - (slack * 0.5).min(55.0);
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            // pair lookahead: residual reusable by next two items
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation: residual divisible by next item size
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
            }
            // triple lookahead for tight residual chains
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
            // refined: waste slightly larger than the item itself is very bad
            if waste as u32 >= item_size && remaining > 100.0 {
                score += waste * 0.35 * rem_frac;
            }
        }
    }

    // dead-space penalty: small leftovers unlikely to be reused
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    // residual exactly reusable-sized band
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if dead < 0.10 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 9.0 * rem_frac;
        }
        if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) < item_size {
            score += 4.0 * rem_frac;
        }
        // anti-dead-space mid-stream: residuals no item (<=100) can fully use
        if progress > 0.15 && post_residual > 100 {
            let unusable = post_residual - 100;
            score += unusable as f64 * 0.35 * rem_frac;
        }
        if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && slack < 5.0 {
                score -= 6.0 * rem_frac;
            }
        }
        // mutation: residuals in the awkward 13..20 band rarely get filled; penalize mid-stream
        if post_residual >= 13 && post_residual <= 20 && progress > 0.2 {
            score += 5.0 * rem_frac;
        }
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // mutation: opening a fresh bin is more attractive when it would leave an
        // exact complement for the next item (perfect split lookahead)
        if next_item_size > 0 && bin_capacity > item_size + next_item_size {
            let comp = bin_capacity - item_size - next_item_size;
            if comp == 0 {
                score -= 25.0;
            } else if (comp as f64) < 0.05 * bin_capacity as f64 {
                score -= 12.0;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // mutation: extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // mutation: strong preference for near-perfect fills late in the stream
        if progress > 0.7 && fill > 0.95 {
            score -= 8.0 * (fill - 0.95) / 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which capacity fraction does the leftover fall in?
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    let three_quarter = 3 * quarter; // 75

    // Reward tight fits: post_residual in the smallest harmonic class is excellent.
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else if post_residual < quarter {
        score -= 30.0 + (quarter - post_residual) as f64 * 0.5;
    } else if post_residual < half {
        score -= 10.0;
    } else if post_residual < three_quarter {
        score += 5.0; // large dead space penalty
    } else {
        score += 15.0;
    }

    // Modulo-10 harmonic class of post_residual: small multiples of 10 pair well
    // with typical item sizes (also 1..=100 integers).
    let pr_mod = post_residual % 10;
    if pr_mod == 0 {
        score -= 8.0;
    } else {
        score += pr_mod as f64 * 0.4; // ragged leftovers are harder to fill
    }

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // even better if next item exactly consumes it (modulo match)
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                score -= 12.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            let overshoot = next_item_size - post_residual;
            score += overshoot as f64 * 0.3;
        }
    } else {
        // last item: strongly prefer perfect fill
        if post_residual == 0 { score -= 50.0; }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (bin_capacity - post_residual) as f64 * 0.1;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit. Judge by mean residual and fit quality.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = (bin_capacity - item_size) as f64 + 25.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // if open bins are already crowded with tiny residuals, new bin is fine
        if mean_residual < (item_size as f64) {
            score -= 15.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // many open bins: discourage opening yet another
        score += open_bins_count as f64 * 1.5;
    }

    // Slight preference for fuller bins overall (waste-aware tiebreak)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

