pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward bins whose residual can still host the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 12.0; // dead space that next item cannot use
        }
    }

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when this bin's fit would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0 + 0.8 * open_bins_count as f64;
        // But if placing here would strand a tiny gap in an existing bin, new bin wins.
        if post_residual >= bin_capacity - item_size {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // new bin can host a pair
        }
    }

    // Late in stream: tighter packing preferred.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (larger gaps) for big items.
    if (bin_residual as f64) < mean_residual && item_size > 50 {
