    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item almost fills the bin after placement.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Tightness reward decays quadratically with gap.
        score -= 40.0 * (1.0 - gap / (bin_capacity as f64)).powi(2) - gap * 0.1;
    }
    // Next item cannot use the leftover: penalize dead space more strongly.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // Reward leaving residuals below the minimum item size (1) is impossible;
    // instead reward residuals too small for typical items (dead-space cutoff).
    if post_residual < 10 {
        score -= 25.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        let mut new_score = 70.0;
        // If no open bin fits well (post_residual for open bins would be large),
        // opening fresh is competitive: scale by open bin count pressure.
        new_score -= 2.0 * open_bins_count as f64;
