        // Perfect lookahead fit into a fresh bin (item then next item).
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            new_score -= 45.0;
        }
        return new_score;
    }

    // Mild normalization: prefer filling already-open bins as stream progresses.
    score += 0.02 * (post_residual as f64 - mean_residual).abs();

    score
}

