        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // mid-band dead-space: residual leaving 8-20 unused after this item, with poor lookahead
        if post_residual > 8 && post_residual < 20 && next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (capacity fraction buckets) ---
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / c; // 0.0 .. 1.0

    // Dead-space penalty: residuals in "unusable" harmonic classes
    // (too small for typical items) get punished super-linearly.
    if post > 0 && post < 10 {
        score += 60.0; // dead space: nothing can ever fit
    } else if post < 20 {
        score += 18.0 * (1.0 - frac * 5.0); // nearly-dead class
    }

    // Integer-division thresholds on post_residual: reward residuals
    // that lie in "reusable" classes (multiples of common item bands).
    let band = post_residual / 10; // harmonic class 0..10
    let band_bonus: f64 = match band {
        0 => 0.0,
        1 => 2.0,   // 10-19: fits small items
        2 => 5.0,   // 20-29
        3 => 8.0,   // 30-39
        4 => 10.0,  // 40-49
        5 => 12.0,  // 50-59
        6 => 14.0,  // 60-69
        7 => 15.0,  // 70-79
        _ => 16.0,  // 80+
    };
    score -= band_bonus;

    // Exact-fit reward: perfect packing is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
            // harmonic match: next item lands in same modulo class
            if (post_residual % 10) >= (next_item_size % 10) {
                score -= 3.0;
            }
        } else {
            // next item cannot use leftover: mild penalty scaled by gap
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fit is poor (large post_residual) or
    // many bins are open (spread load).
    if bin_residual == bin_capacity {
        score = c - post; // = 0 baseline for empty bin
        // penalize opening new bins when a good fit exists elsewhere
        if fitting_bins_count >= 1 && post_residual < 30 {
            score += 45.0;
        }
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
        // early stream: slightly favor consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Mild tie-break: prefer bins whose residual is near the mean
    // (keeps bin loads balanced within harmonic classes).
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Prefer filling fuller bins (best-fit flavor) via residual fraction.
    score += 20.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
