            // mutation: slack tolerance scales with mean residual scarcity
            let mean_frac = mean_residual / bin_capacity as f64;
            if mean_frac < 0.15 && slack > 0.0 && slack < 10.0 {
                score -= (10.0 - slack) * 0.8 * rem_frac;
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
