pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else {
        // Smooth tightness reward: smaller usable residual is better.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize wasting a bin that could hold the next item if the next item
    // would no longer fit after this placement.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // and discourage opening yet another bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // New-bin candidate (empty bin): make it unattractive unless it is
    // genuinely needed (handled by the pressure term above).
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Mild deviation from mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

