}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly matches
    // the post-residual (perfect chaining), or fits into it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 40.0; // perfect match: next item fills this bin completely
        } else if next_item_size <= post_residual {
            // next item fits; reward tighter coupling
            score -= 25.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large dead space slightly
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is below the mean (tighter bins fill first),
    // keeping large residuals available for large future items.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    // or the fit here is terrible (large dead space).
    if bin_residual == bin_capacity {
        let dead = post_residual as f64;
        let crowded = (open_bins_count as f64).max(1.0);
        score += 15.0 + 10.0 * (1.0 / crowded); // baseline penalty for opening a bin
        if dead > 60.0 {
            score += 20.0; // very poor fit elsewhere -> new bin more acceptable
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    score
}

