    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that cannot host the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // dead space: unusable for the next item
            score += 0.35 * (post_residual as f64) * (1.0 + 0.5 * nxt / bin_capacity as f64);
        } else {
            // reward bins that can also host the next item (chaining)
            score -= 6.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to spread load when alternatives exist
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: penalize opening a new bin when open bins fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 25.0 + 2.0 * open_bins_count as f64;
        } else {
            score -= 5.0; // no alternative: opening is fine
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins
    // with residuals far from the mean (balance the pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 2.0 * dev / bin_capacity as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Time horizon: late in the stream, be more aggressive about tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;
    score -= 4.0 * progress * fit_ratio;

    score
}

