        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // mutation: variance-reduction — favor residuals close to mean residual
        if next_item_size > 0 && post_residual >= next_item_size {
            let dev = ((post_residual as f64) - mean_residual).abs();
            if dev < 8.0 {
                score -= (8.0 - dev) * 0.5;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: penalize wasted space, with a super-linear (quadratic + cubic) component
    // that punishes small dead-space leftovers more aggressively.
    let mut score = post + 40.0 * post_norm * post_norm + 30.0 * post_norm * post_norm * post_norm;

    // Smooth coupling of dead-space penalty with stream progress:
    // early in the stream, keep residuals flexible (reward larger post_residual slightly);
    // late in the stream, tight packing matters more.
    let flex = 1.0 - progress;
    score -= 25.0 * flex * post_norm;

    // Exact fit bonus (smooth via normalized term, no hard threshold).
    let fit_ratio = item_size as f64 / cap;
    score -= 15.0 * (1.0 - post_norm) * (1.0 - post_norm) * fit_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 50.0;
    } else {
        // Slight penalty when many bins compete, favoring the tightest fit naturally.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward leaving room for the next item if it would fit;
    // penalize if post_residual is just barely too small for next_item_size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 10.0 * (1.0 - (post - nx) / cap);
        } else {
            let gap = (nx - post) / cap;
            score += 20.0 * gap * (1.0 - gap);
        }
    }

    // Mean-residual coupling: if this bin's residual deviates strongly from the mean,
    // mildly prefer bins that homogenize residual distribution (smooth interaction).
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Open-bin pressure: many open bins -> discourage new bins implicitly by
    // rewarding use of existing bins with high residual.
    score -= (open_bins_count as f64).ln() * post_norm * 5.0;

    // New-bin candidate adjustment: empty bin has post == cap; make it attractive
    // only when the item is large relative to capacity and few bins fit it.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 30.0 * (1.0 - large_item) * (1.0 - large_item) + 10.0 * (fitting_bins_count as f64);
    }

    score
}

