pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity-fraction classes.
    // Residuals that fall in "awkward" classes (small, unusable slivers) are penalized.
    let c = bin_capacity as f64;

    // Class A: post_residual in [1,10] -> dead space penalty (nearly unusable).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }

    // Class B: post_residual in (10, 25] -> moderately awkward.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Class C: post_residual mod 20 == 0 -> perfectly harmonic residual, reward.
    if post_residual % 20 == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Integer-division threshold: how many items of size <=20 could still fit.
    let slots = post_residual / 20;
    score -= slots as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Harmonic check: does next item leave a harmonic residual?
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            score -= 4.0;
        } else {
            // Next item cannot use this bin's residual: penalize leftover.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: empty bin gets a baseline cost so it's only chosen
    // when open bins score poorly. Reward grows with stream progression.
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tight packing), penalize bins far above mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild pressure to prefer already-open bins as open bin count grows.
    score += 0.3 * open_bins_count as f64;

    score
}

