pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=10)
    // are pure waste; penalize sharply the closer they are to "unusable".
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 10.0 {
        score += 60.0 * (1.0 - pr / 10.0); // tiny gaps are the worst
    } else if pr > 10.0 && pr <= 30.0 {
