    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size <= 5 {
            score -= 50.0; // chain leaves near-zero waste
        } else {
