    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into new bins,
    // but the new-bin candidate (full residual) should be penalized when bins exist.
    if bin_residual == bin_capacity {
