        let chain = post_residual - next_item_size;
        score -= (chain as f64).min(20.0) * 0.4;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use leftover: penalize proportionally
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_fit = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // open a new bin if mean residual is small (fragmented bins) or few bins open
        let fragmentation = (bin_capacity as f64 - avg_open_fit) / bin_capacity as f64;
        if fragmentation > 0.5 || open_bins_count == 0 {
            score -= 22.0 * fragmentation + 5.0 * progress;
        } else {
            score += 15.0 + 20.0 * (1.0 - fragmentation);
