        // late in stream, prefer filling existing bins
        if progress > 0.8 {
            score += 25.0;
        }
    }

    // Mild penalty for placing into bins with large residual when many bins are open
    // (encourages consolidating into nearly-full bins first).
    if bin_residual < bin_capacity {
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= tightness * 10.0;
    }

    // Dynamic time horizon: early on, be more exploratory (open bins freely);
    // later, be greedy about filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

