        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are ideal.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonic"
    // fractions of capacity (25, 33, 50, 20, 10) are reusable by common items.
    let harmonic: [u32; 6] = [0, 10, 20, 25, 33, 50];
    if harmonic.contains(&post_residual) {
        score -= 120.0;
    }
    // Penalize dead space that is small and non-harmonic (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Integer-division classes: post_residual bucketed by eighths of capacity.
    let bucket = post_residual / (bin_capacity / 8);
    score += bucket as f64 * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 3.0;
        } else {
            // Next item cannot use this bin's leftover; penalize leftover more.
            score += post * 0.15;
        }
    }

    // Prefer tighter bins overall: compare against mean residual.
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.5;

    // New-bin candidate: only attractive when current bin leaves a bad remainder
    // or nothing fits well. Make an empty bin slightly unattractive by default.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        // But if the item is huge relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.6 * cap {
            score -= 90.0;
        }
    }

    // Mild stream-progression pressure: later in stream, be more conservative
    // about wasting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * progress * 0.3;

    score
}

