pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item,
    // penalize leftovers that are too small to be useful.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            // Chain potential: the next item can also go here.
            score -= 40.0 + (nr / bin_capacity as f64) * 60.0;
        } else {
            // Dead-space penalty grows as leftover approaches "just barely too small".
            let waste = post_residual as f64 / nr;
            score += 60.0 * (1.0 - waste).max(0.0);
        }
        // Exact chain: post_residual == next_item_size is a perfect 2-step fit.
        if post_residual == next_item_size {
            score -= 200.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fill_ratio;

    // Compare against mean residual: placing into a large-residual bin balances load.
    if (bin_residual as f64) > mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize creating very small unusable gaps (< 10 units, the minimum item size analog).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Early in the stream, be more willing to open fresh bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive if item is large (leaves little dead space).
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        if progress < 0.2 {
            score -= 30.0;
        }
    }

    // Slight preference for keeping the number of open bins from exploding late.
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    score
}

