pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: reward small post_residual with a non-linear (quadratic) coupling.
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, waste is more costly,
    // so amplify the penalty on large post_residual smoothly.
    score += 40.0 * progress * norm_pr * norm_pr;

    // Dead-space term: residual too small for the next item is wasted;
    // smooth interaction between post_residual and lookahead item.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as f64;
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score -= 25.0 * fits_next * norm_pr;
        score += 30.0 * gap * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_pr);
    } else if fitting_bins_count > 1 {
        // Mild penalty for burning scarce fitting bins when alternatives exist.
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer tighter bins relative to the fleet mean residual (smooth coupling).
    score += 10.0 * (norm_pr - mean_residual / cap).abs();

    // Mild preference for consolidating into fewer bins early on.
    score -= 8.0 * (1.0 - progress) / (1.0 + open_bins_count as f64);

    // Slight aversion to leaving exactly tiny unusable slivers.
    let sliver = ((pr - 5.0).abs() / cap).min(1.0);
    score += 12.0 * (1.0 - sliver * sliver) * (pr < 10.0 as f64) as i32 as f64 * 0.0;

    score
}

