    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which residue class does
    // post_residual fall into modulo common item-size bands?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect closure (post_residual == 0) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class B: dead space (post_residual < 10) -> the bin is effectively
    // closed with zero waste; reward strongly.
    if post_residual > 0 && post_residual < 10 {
        score -= 300.0;
    }

    // Class C: post_residual in low harmonic band [10, 20) — only small
    // items can still use it; mildly good if the stream is late.
    if post_residual >= 10 && post_residual < 20 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 + 60.0 * progress;
    }

    // Class D: mid band [20, 50) — usable by many items; neutral-ish,
    // slight penalty because it invites fragmentation.
    if post_residual >= 20 && post_residual < 50 {
        score += 15.0;
    }

    // Class E: high band [50, cap) — big leftover, only acceptable if the
    // item itself was large; penalize large leftovers.
    if post_residual >= 50 {
        score += 0.5 * (pr - 50.0);
    }

    // Lookahead coupling: if the next item cannot fit into the post
    // residual, this bin's remaining space is likely stranded.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 25.0 + 0.3 * (next_item_size - post_residual) as f64;
        } else {
            // Next item fits exactly into a harmonic slot: reward.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 500.0;
            } else if gap < 10 {
                score -= 150.0;
            } else {
                score -= 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // placing here avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Penalize opening a new bin for small/medium items.
        score += 400.0 * (1.0 - frac) * (1.0 - frac);
        // But late in the stream with many open bins, prefer fresh bins
        // for big items to keep small leftovers usable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if frac > 0.6 {
            score -= 100.0 * progress;
        }
    }

    // Mean-residual coupling: when the fleet of open bins is already
    // fragmented (high mean residual), prefer filling tight bins here.
    score += 0.2 * mean_residual;

    // Mild pressure to close bins early rather than accumulate many
    // lightly-filled bins.
    score += 2.0 * open_bins_count as f64;

    score
}

