        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // mutation: extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // refined: reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && progress > 0.3 {
            score -= 8.0 * (fill - 0.95) / 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual below the minimum item size (1) is impossible, but small residuals (< ~30)
    // are unlikely to be filled later, so punish them super-linearly.
    let dead_zone: f64 = 30.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 0.15;
    }

    // Reward tight fits: small post_residual relative to bin capacity gets a bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the next item can exactly fill the post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If the next item fits in the post_residual, mild bonus (keeps chain packing alive).
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }
    // If next item cannot fit in the residual, penalize slightly (dead space likely).
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // Open bins pressure: with many open bins, prefer reusing existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual != bin_capacity {
        // Existing bin: subtract pressure so it beats the new-bin candidate.
        score -= pressure * 2.0;
    } else {
        // New-bin candidate: add pressure so it loses when open bins are viable.
        score += pressure * 2.0;
        // Also penalize new bins when mean residual across open bins is large
        // (existing bins have plenty of room).
        score += mean_residual * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids wasting the remaining space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight preference for fuller bins among open bins (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
