        if post_residual > 0 && (post_residual as f64) / (bin_capacity as f64) < 0.03 {
            score -= 9.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty for wasting a fresh bin; scaled by how many bins exist.
        score += 35.0 + 2.0 * open_bins_count as f64;
        // If the current item nearly fills a fresh bin, allow it (big items early).
        if item_size >= bin_capacity * 7 / 10 {
            score -= 30.0;
        }
        // Late in the stream, opening new bins is more acceptable (fewer future regrets).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Reward leaving room for the next item proportionally.
            score -= 10.0 * (next_item_size as f64) / (post_residual.max(1) as f64);
        } else {
            // Penalize leaving a residual smaller than the next item (dead space).
            score += 8.0 * (1.0 - post_residual as f64 / (next_item_size as f64).max(1.0));
        }
    }

    // Global state coupling: prefer bins whose residual is near the mean (balanced packing).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * deviation;

    // Slight preference for filling fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

