    // Non-linear polynomial penalty on dead space: small residuals are wasteful
    let norm_post = post / cap;
    score += 12.0 * norm_post * norm_post * (1.0 - norm_post) * cap * 0.1;

    // Smooth coupling: tight fits rewarded more as stream progresses
    let tightness = 1.0 - norm_post;
