pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well does the leftover space
    // align with the small-item granularity? Residuals that are multiples
    // of small denominations are reusable; odd remainders are dead space.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -8.0 // perfect fit, reward strongly
    } else if pr % 10 == 0 {
        -2.0
    } else if pr % 5 == 0 {
        -1.0
    } else if pr < 10 {
        4.0 // tiny unusable sliver
    } else {
        0.5
    };
    score += class;

    // Integer-division threshold: residuals in [10, 20] can host the
    // smallest guaranteed item class; residuals below 10 are nearly dead.
    if pr >= 10 && pr < 20 {
        score -= 1.5;
    } else if pr < 10 {
        score += 3.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // chainability reward, stronger when the chain is tight
            let tightness = (pr - next_item_size) as f64;
            score -= 2.0 - tightness * 0.02;
        } else {
            // next item won't chain here; penalize proportionally to waste
            score += 1.0 + (next_item_size as f64) * 0.01;
        }
        // harmonic class match between next item and residual
        if next_item_size % 10 == 0 && pr % 10 == 0 && pr >= next_item_size {
            score -= 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Prefer it only when existing bins would leave bad classes.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many bins are open
        // and stream is early (future items can fill fresh bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 6.0 - 2.0 * progress;
        score = open_cost + (bin_capacity - item_size) as f64 * 0.05;
        // if existing bins are few, opening is more expensive
        if open_bins_count <= 2 {
            score += 2.0;
        }
        // if next item is large and current item is small, fresh bin keeps
        // big-item bins intact
        if next_item_size > 50 && item_size <= 30 {
            score -= 2.0;
        }
    }

    // Mild normalization: prefer filling bins closer to mean residual usage
    score += (bin_residual as f64 - mean_residual) * 0.02;

    score
}

