            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // mutation: extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // mutation: prefer near-perfect fills late in the stream
        if progress > 0.85 && fill > 0.95 {
            score -= 8.0 * (fill - 0.95) / 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: penalize relative waste quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post-residual can host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }
    // Penalize if post-residual is a stranded sliver: too small for anything useful
    // (assume min item size ~1, but dead space below ~10 is nearly unusable).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we only
    // open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, prefer consolidating into open bins more strongly.
        score += 18.0 + 10.0 * progress;
        // But if the item is large relative to capacity, a fresh bin is natural.
        score -= 0.1 * item_size as f64;
    }

    // Prefer bins with residual far below the mean residual (they are already
    // "specialized" small bins); avoid dumping into large-residual bins that
    // could host future big items.
    let resid_gap = mean_residual - bin_residual as f64;
    score += 0.05 * resid_gap;

    // Mild penalty on many open bins to encourage closure of nearly-full bins.
    if post_residual <= 5 {
        score -= 6.0; // nearly closed bin: excellent outcome
    }
    score += 0.02 * open_bins_count as f64;

    // Small time-horizon coupling: as the stream progresses, tighten preference
    // for perfect packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
        score -= 900.0;
    }

    let min_useful = if next_item_size > 0 { next_item_size.min(80).max(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + 3.0 * (min_useful - post_residual) as f64;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 850.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - (slack * 0.1).min(9.0);
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            // pair lookahead
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
            }
            // triple chain
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
        }
    }

    // reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // dead-space penalty
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
