    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 6.0 + 10.0 * (1.0 - prn);
        } else {
            score += 4.0 * prn * p2;
        }
    }

    // Mild penalty for bin proliferation early; stronger later
    score += open_bins_count as f64 * (0.5 + 1.5 * p3);

    // Deviation from mean residual: prefer bins near the mean, smooth cubic term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * dev * 5.0 + dev * dev * 3.0;

    // Slight bias against opening a new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + 25.0 * p2 + 15.0 * p3;
    }

    score
}

