pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual (classes of width 10)
    let post_class = (post_residual / 10) as f64;
    let next_class = if next_item_size > 0 { (next_item_size / 10) as f64 } else { 0.0 };

    // Reward if post_residual class can host next item's class
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + next_class * 2.0;
        } else {
            score += 8.0; // dead space for lookahead
        }
        // exact mod-based coupling: post_residual % 10 small means near-perfect fit
        let rem = post_residual % 10;
        score -= (10 - rem) as f64 * 0.8;
    }

    // Penalize tiny unusable residuals (mod classes 1..=5)
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    // Prefer keeping residuals in mid harmonic classes (20..50) reusable
    score -= post_class * 1.5;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bins are nearly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 - 10.0 * progress;
        if mean_residual > item_size as f64 {
            score += 10.0; // open bins have room; avoid new bin
        }
    }

    // Tight-fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

