pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (low post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let match_gap = post - nxt;
            // Exact match for the next item is excellent
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
            // Penalize small leftover slivers that no future item can use
            if match_gap > 0.0 && match_gap < 10.0 {
                score += 25.0;
            }
        } else {
            // Next item cannot fit in this bin after placement: mild penalty
            score += 10.0;
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins)
    let mean_gap = mean_residual - post_residual as f64;
    score -= 5.0 * mean_gap / bin_capacity as f64;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Discourage opening new bins early when open bins fit reasonably
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin baseline cost: high, but relaxes if current fit is terrible
        score += 60.0 - 20.0 * progress;
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            // A fresh bin can host both current and next item
            score -= 45.0;
        }
    }

    // Slight penalty for very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
