pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits strongly (low post residual is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer opening new bins early or when existing
    // bins are fragmented (high mean residual spread), prefer reuse later.
    if is_new_bin {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let early_bonus = 30.0 * (1.0 - progress);
        let crowded_penalty = 2.0 * open_bins_count as f64;
        score -= early_bonus - crowded_penalty + 0.15 * fragmentation;
        // If no open bin fits well, opening a fresh bin is attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Reward bins whose residual is close to mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
        // Mild reward for using existing bins as stream progresses.
        score -= 5.0 * progress;
    }

    // Global pressure: many open bins -> favor consolidation into existing bins.
    if open_bins_count > 8 {
        score += if is_new_bin { 10.0 } else { -3.0 };
    }

