pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the current item: coarse capacity-fraction buckets.
    let item_class = item_size / 25;              // 0..3 (small, medium, large, huge)
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 25 };

    // Reward tight fits: low post_residual is good.
    score -= 12.0 / (1.0 + post_residual as f64);

    // Penalize dead space that is too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0; // only tiny items fit
    }

    // Modulo-arithmetic harmony: if post_residual is divisible by small item
    // classes, the leftover space is reusable — reward it.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits, but how well? Reward proportional leftover quality.
        let next_post = post_residual - next_item_size;
        score -= 10.0 / (1.0 + next_post as f64);
        if next_post < 10 {
            score += 5.0; // chains into a sliver
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize if this bin was its only hope.
        if next_item_size <= bin_residual && post_residual < next_item_size {
            score += 7.0;
        }
    }

    // Class-compatibility: pairing large items with large residuals is good;
    // putting a small item into a huge residual wastes capacity.
    let residual_class = bin_residual / 25;
    if item_class as i32 - residual_class as i32 >= 2 {
        score += 10.0; // small item devouring a big bin
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual < 10 {
            score -= 5.0; // even a sliver-leaving fit beats a fresh bin
        }
    }

    // New-bin candidate handling: an empty bin has huge post_residual, so the
    // base score already penalizes it. Calibrate so a new bin is chosen only
    // when fits into open bins leave very poor residuals.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: definitely open a new bin
        }
        if next_item_size > 60 {
            score -= 10.0; // big next item: fresh bin is attractive
        }
    }

    // Stream progression: late in the stream, consolidate harder (fewer bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    // Mean residual pressure: if open bins are on average tight, prefer using
    // whatever fits rather than opening new bins.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
