            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // near-perfect fill refinement: reward fill ratios in [0.95, 1.0)
        // more strongly than the generic >0.92 band
        if fill >= 0.95 {
            score -= 6.0 * (fill - 0.95) / 0.05;
        }
        // mid-band waste: fills in [0.35, 0.6) leave awkward dual-use space;
        // penalize slightly unless residual stays chainable
        if fill >= 0.35 && fill < 0.6 && next_item_size > 0 && post_residual < next_item_size {
            score += 3.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Reward when next item also fits into the resulting residual (chain placement)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
    }

    // Penalize residual too small for the next item (dead space relative to lookahead)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.4 * (next_item_size as f64 - post_residual as f64);
    }

    // Favor bins tighter than the mean residual (good fits close out bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mildly discourage opening new bins when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * item_size as f64;
        // New bin is attractive only if the item is large (fills it well)
        if item_size >= 70 {
            score -= 40.0;
        }
    }

    // Penalize leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
