pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward tight fits (low post-residual waste), non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * fit_ratio * fit_ratio;

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item uses leftover
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fit;
        } else {
            // next item won't fit here: penalize leaving large dead space
            score += 0.15 * post_residual as f64;
        }
    } else {
        // last item: only absolute tightness matters
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over a new bin
    // unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 20.0 * (1.0 - t);
        if post_residual > 30 {
            score += 25.0; // too much waste, maybe open new bin instead
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost that tight fits in
    // existing bins can beat, but poor fits cannot.
    if bin_residual == bin_capacity {
        score += 35.0;
        // early in stream, opening bins is cheaper; late, prefer consolidation
        score += 30.0 * (1.0 - t);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins below mean residual when item is large (keep big gaps for big items).
    if (item_size as f64) > bin_capacity as f64 * 0.5 {
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Slight penalty for spreading across many open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * t;

    // Prefer filling bins with larger residual (consolidate waste) when item is small.
    if item_size <= 30 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - (slack * 0.5).min(55.0);
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            // pair lookahead: residual reusable by next two items
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation: residual divisible by next item size
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
            }
            // triple lookahead for tight residual chains
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
            // new: slack relative to mean residual — prefer fits that keep
            // the bin's leftover near the fleet-average reusable size
            let slack_vs_mean = mean_residual - slack;
            if slack_vs_mean > 0.0 && slack_vs_mean < 10.0 && progress > 0.1 {
                score -= 5.0 * (1.0 - slack_vs_mean / 10.0);
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
            // new: penalize more heavily when the wasted residual is a
            // large fraction of the bin's current residual (irrecoverable)
            let waste_frac = waste / bin_residual.max(1) as f64;
            if waste_frac > 0.5 {
                score += waste_frac * 10.0 * rem_frac;
            }
        }
    }

    // dead-space penalty: small leftovers unlikely to be reused
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    // residual exactly reusable-sized band
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if dead < 0.10 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 9.0 * rem_frac;
        }
        if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) < item_size {
            score += 4.0 * rem_frac;
        }
        // anti-dead-space mid-stream: residuals no item (<=100) can fully use
        if progress > 0.15 && post_residual > 100 {
            let unusable = post_residual - 100;
            score += unusable as f64 * 0.35 * rem_frac;
        }
        if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && slack < 5.0 {
                score -= 6.0 * rem_frac;
            }
        }
        // new: late-stream, residuals just above the largest plausible item
        // (near capacity/2) are hard to fill — mild penalty grows with progress
        if progress > 0.5 && post_residual > bin_capacity / 2 && post_residual <= bin_capacity / 2 + 15 {
            score += 7.0 * (progress - 0.5);
