    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // new: opening a fresh bin for a large item that exactly complements
        // a typical open-bin residual is often better than squeezing — reward
        // when item fills > 60% of a new bin
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.6 && frag > 0.2 {
            score -= 10.0 * (item_frac - 0.6) / 0.4;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // new: strengthen near-exact fills in the mid range — bins whose
        // post-residual is tiny but nonzero get an extra squeeze when the
        // item fills most of the residual
        if post_residual > 0 && post_residual <= 4 && fill > 0.75 {
            score -= 9.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // early on, waste matters less; later, tighten packing harder
    score += 40.0 * norm_pr * progress * (1.0 - progress + 0.25);

    // Penalize bins whose residual deviates from mean residual (fragmentation)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // Reward tight fits via smooth sigmoid-like term
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_frac * fit_frac * (1.0 + progress);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * progress;

    score
}

