    let mut score = post_residual as f64;

    // Reward near-perfect fits: harmonic class of post_residual
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space in small residue classes (unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Harmonic class: residues divisible into nice future-fit buckets
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 6.0; // bin still half-full: flexible
    } else if frac < 0.1 {
        score += 5.0; // nearly full: rigid
    }

    // Lookahead: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chain placement possible
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 6.0; // double-tight chain
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    } else {
        // last item: prefer exact fill
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Prefer filling existing bins over opening new ones when many open
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless current bins are badly fragmented
        score += (open_bins_count as f64) * 2.0;
        if mean_residual > item_size as f64 * 1.5 {
            score -= 15.0; // plenty of room elsewhere; avoid new bin
        }
    } else {
        score -= 3.0; // mild preference for existing bins
    }

    // Modulo class on post_residual: multiples of 10 are "harmonic" slots
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

