pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward bins whose post_residual
    // matches the next item size exactly or nearly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can also fit here: strong reward for tight match.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would not fit after this placement: penalize,
            // scaled by how much dead space is created.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Exact match bonus for a perfect two-item fill.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Penalize large leftover dead space relative to mean residual.
    if (post_residual as f64) > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item fits
    // badly everywhere (large item with no good match).
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > 60 && next_item_size > 40 {
            score -= 15.0;
        }
    }

    // Late in the stream: tighten packing, avoid leaving many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
