            score += 10.0;
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Penalize post_residual that cannot fit typical small items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead coupling: if next item fits in post residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins with residual below mean residual (denser bins) mildly
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: penalize opening new bins, more so early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 200.0 - 80.0 * progress;
        // Allow new bin if the item leaves a nice residual for the lookahead item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        // If only this candidate fits, new bin is forced anyway
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mildly discourage scattering across many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

