pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 0.8 * progress) - 1.6 * norm_post * norm_post * (0.5 + 0.9 * progress) + 0.9 * norm_post.powi(3);
    let mut score = post * (1.0 + 0.5 * progress) + 20.0 * poly;

    // Penalize dead space that likely becomes unusable, weighted by progress
    let dead_threshold = 0.15 * cap * (1.0 - 0.5 * progress);
    if post < dead_threshold && post > 0.0 {
        score += 15.0 * (dead_threshold - post) / cap * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post >= ns {
            score -= 6.0 * (1.0 - (post - ns) / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 8.0 * (ns - post) / cap;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    } else {
        // Favor tight fits relative to mean residual
        score -= 4.0 * (mean_residual - post) / cap;
    }

    score
}

