    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 25 (capacity quarters)
    // leave room for common item sizes, so reward them.
    let quarter_class = post_residual % 25;
    score -= match quarter_class {
        0 => 12.0,
        5 => 6.0,
        10 => 3.0,
        _ => 0.0,
    };

    // Penalize dead space that cannot fit even the smallest item (1..10 dead zone)
    if post_residual < 10 {
        score += 15.0;
    }

    // Harmonic pairing: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 8.0; // perfect harmonic completion
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item can't use this leftover: penalize proportionally to wasted fraction
        score += 0.25 * (post_residual as f64) * (1.0 + 0.5 * (next_item_size as f64 / bin_capacity as f64));
    }

    // Integer-division threshold on post_residual: mid-range leftovers (30..60) are
    // the most reusable; extremes are less valuable.
    let half = post_residual / 2;
    if (20..=60).contains(&post_residual) {
        score -= 4.0 + (half % 10) as f64;
    } else if post_residual > 70 {
        score += 3.0; // large leftover means poor packing now
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual < 10 {
            score -= 10.0; // perfect near-exact fill on last chance
        }
    }

    // New-bin candidate: penalize mildly so we prefer real bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0 - 0.05 * open_bins_count as f64;
        // But if current item is huge and nothing else fits well, new bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Tight fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Late in stream, prefer closing bins tightly over spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Coupling with mean residual: avoid making this bin an outlier of waste.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

