pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if no plausible future item (min size 1, but typical
    // items are substantial) can pair with it; penalize the awkward band hardest.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Awkward band: residual too small to be useful, too big to ignore.
        if pr <= 10.0 {
            score += 40.0 * (1.0 - pr / 10.0); // tiny slivers: nearly full waste
        } else if pr <= 30.0 {
            // dead zone: 11..30 can't host typical items from unknown streams
            score += 25.0 - 0.5 * pr;
        } else {
            // larger residuals are reusable, mild reward for keeping them
            score -= 5.0;
        }
    } else {
        // Perfect fill: strongest reward.
        score -= 60.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / cap;
    score -= 20.0 * fill_ratio;

    // Lookahead synergy: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr - nx).abs() < 0.5 {
            score -= 35.0;
        } else if nx <= pr {
            score -= 10.0 * (nx / pr.max(1.0));
        } else {
            // next item won't fit here; dead space likely
            score += 8.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of bins when mean residual
    // across open bins is already high.
    let pressure = open_bins_count as f64 * (mean_residual / cap);
    score += 3.0 * pressure;

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when all open bins score poorly (bad fits / dead-space creation).
    if bin_residual == bin_capacity {
        // cost grows with stream progress and number of open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 10.0 * progress + 2.0 * open_bins_count as f64;
        // but if next item is large and mean residual is low, new bin is fine
        if next_item_size as f64 >= 0.7 * cap {
            score -= 20.0;
        }
    }

    score
}

