        // largest item it can still host; discount residuals that exceed the max
        // plausible reuse (next_item + mean slack) by a small dead-weight charge
        if next_item_size > 0 && post_residual > next_item_size {
            let excess = (post_residual - next_item_size) as f64;
            if excess > 20.0 && mean_residual > 0.0 && (post_residual as f64) > mean_residual * 1.6 {
                score += excess * 0.12 * rem_frac;
