        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: consolidation tiebreak — when many bins fit and the post residual
        // matches the mean residual closely, prefer that bin (keeps residual
        // distribution homogeneous so future items have predictable homes)
        if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size
            && mean_residual > 0.0 {
            let drift = ((post_residual as f64 - mean_residual).abs()) / mean_residual;
            if drift < 0.15 {
                score -= 5.0 * (1.0 - drift / 0.15);
            }
        }
    }

    score
}

