        let item_frac2 = item_size as f64 / bin_capacity as f64;
        if item_frac2 < 0.35 && open_bins_count > 3 && fitting_bins_count > 0 {
            score += 10.0 + (open_bins_count.min(10) as f64) * 1.5;
        }
    } else {
