        // residuals (0.12–0.30 of capacity) that are hard to fill but too big to ignore
        if dead >= 0.12 && dead < 0.30 && progress > 0.25 {
            score += (dead - 0.12) * 55.0 * rem_frac;
        }
        // mutation: reward residuals that remain useful for the average future item —
        // if post_residual can hold mean_residual with little waste, favor it
        if mean_residual > 0.0 && post_residual as f64 >= mean_residual {
