        // reward when the leftover is reusable-sized, penalize odd leftovers
        if next_item_size > 0 && fitting_bins_count > 0 {
            let leftover = bin_capacity - item_size;
            if leftover >= next_item_size {
                let lslack = leftover - next_item_size;
                if lslack <= 2 {
