        // residual stays close to the fleet mean residual, keeping a uniform
        // pool of reusable leftovers instead of one orphaned tiny gap
        if post_residual > 0 && mean_residual > 4.0 && progress > 0.2 && progress < 0.85 {
            let dev = (post_residual as f64 - mean_residual).abs();
            if dev < 15.0 {
                score -= (15.0 - dev) * 0.25;
            }
        }
    }

    score
}

