    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
