        if lookahead_waste < 10 {
            score += 30.0; // tiny slivers are dead space
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in this bin after placement: penalize.
        score += 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when fit is poor.
    if bin_residual == bin_capacity {
        // Empty bin baseline: mildly penalize so real bins win unless they fit badly.
        score += 60.0;
        if next_item_size > 0 && item_size <= bin_capacity / 2 {
            score += 20.0;
        }
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

