}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Base: post residual (bigger leftover => better fit)
    let mut score = pr;

    // Smooth non-linear coupling: quadratic in normalized post-residual modulated by progress
    score += 40.0 * (pr_norm - 0.5) * (pr_norm - 0.5) * (0.5 + progress) * 10.0;

    // Penalize dead space that is too small to be useful, smoothly
    let dead = (pr as f64).min(next_item_size as f64).max(0.0);
    score -= 25.0 * (dead / 100.0) * (1.0 - (dead / 100.0));

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        score -= 30.0 * fits_next * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if only this bin fits, strongly favor it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mild penalty for opening new bins late in stream
    score += is_new * (20.0 + 40.0 * progress);

    // Spread-awareness: prefer bins with residual near mean (balance)
    score += 10.0 * (pr - mean_residual).abs() / cap;

    score
}

