        // new-bin bonus scaled by pairing quality
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 10.0;
            } else if leftover <= 4 {
                score -= 5.0;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.92 {
            score -= 22.0 * (fill - 0.92) / 0.08;
        } else if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // strong preference for near-exact fits when few bins can host the next item
        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // mutation: scarcity-aware tightness — consume a lone fitting bin fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: near-perfect fill band mid-stream
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // mutation: sliver-gap penalty for low fills
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let fit = post_residual as f64 / cap;

    // Base: post residual (waste), non-linearly shaped by stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth polynomial coupling: prefer small normalized post-residual, especially early
    score += 8.0 * fit * (1.0 - fit) * (1.0 - progress);

    // Penalize near-empty leftovers that become dead space (smooth bump around small residuals)
    score += 6.0 * (1.0 - fit).powi(4);

    // Reward tight fits strongly
    score -= 12.0 * (1.0 - fit).powi(2);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = (pr - ni) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * ((ni - pr) / cap).powi(2);
        }
    }

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins with residual close to item need
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: make it moderately unattractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    }

    let min_useful = if next_item_size > 0 { next_item_size.min(80).max(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + 3.0 * (min_useful - post_residual) as f64;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - (slack * 0.3).min(27.0);
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            // pair lookahead
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
            }
            // triple chain
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
            // quad lookahead
            if next_item_size > 1 && post_residual >= next_item_size * 4 {
                let quad = post_residual - next_item_size * 4;
                if quad == 0 {
                    score -= 26.0;
                } else if (quad as f64) < 0.03 * bin_capacity as f64 {
                    score -= 11.0;
                }
            }
            // quint lookahead for small items
            if next_item_size > 1 && next_item_size <= 20 && post_residual >= next_item_size * 5 {
                let quint = post_residual - next_item_size * 5;
                if quint == 0 {
                    score -= 20.0;
                } else if (quint as f64) < 0.02 * bin_capacity as f64 {
                    score -= 8.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
        }
    }

    // reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // dead-space penalty
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if dead < 0.10 && next_item_size > 0 && post_residual < next_item_size {
            score += 9.0 * rem_frac;
        }
        if progress > 0.15 && post_residual > 100 {
            score += (post_residual - 100) as f64 * 0.35 * rem_frac;
        }
        if progress > 0.95 && post_residual > 0 {
            score += post_residual as f64 * 0.5 * rem_frac;
        }
        // unusable sliver above next item — nearly dead space
        if progress > 0.45 && next_item_size > 0 && post_residual > next_item_size {
            let sliver = post_residual - next_item_size;
            if sliver <= 6 {
                score += sliver as f64 * 0.9 * rem_frac;
            }
        }
        if progress > 0.35 && next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6 * rem_frac;
        }
        if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && slack < 5.0 {
                score -= 6.0 * rem_frac;
            }
        }
    }

    // open-bin pressure
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // new-bin pairing quality: fresh bin whose leftover exactly fits next item
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 14.0;
        }
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 10.0;
            } else if leftover <= 4 {
                score -= 5.0;
            }
        }
        // fallback base penalty for new bin
        score += 30.0 + mean_residual * 0.15;
    } else {
        score += (bin_residual - item_size) as f64 * 0.05;
        score -= (mean_residual - bin_residual as f64) * 0.05;

        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap;
            }
        }
        // scarcity-aware tightness: single fitting bin should be consumed fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score = score * (0.6 + 0.8 * progress);

    // Harmonic class penalty: post_residual modulo small divisors.
    // Residuals that are "nice" (divisible by common small sizes) are reusable.
    let pr = post_residual;
    let nice = if pr == 0 { 3.0 }
        else if pr % 10 == 0 { 2.0 }
        else if pr % 5 == 0 { 1.0 }
        else if pr % 25 == 0 { 1.5 }
        else if pr % 2 == 0 { 0.3 }
        else { 0.0 };
    score -= nice * (1.0 + 0.5 * progress);

    // Dead-space penalty: very small unusable post_residual.
    if pr > 0 && pr < 10 {
        score += 8.0 * (10.0 - pr as f64) * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot class
            let over = (next_item_size - pr) % 10;
            score += 0.4 * over as f64;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or fit is poor. Penalize opening a bin by default.
    if bin_residual == bin_capacity {
        let avg_fit = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let crowded = (open_bins_count as f64) * (avg_fit / cap);
        score += 30.0 - 20.0 * crowded.min(1.5);
        if item_size as f64 > 0.8 * cap {
            score -= 15.0; // big items like fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for pairing
        }
    }

    // Prefer filling bins with large residual when many bins are open.
    score -= 0.05 * (bin_residual as f64 - mean_residual).max(0.0) * (open_bins_count.min(20) as f64 / 20.0);

    score
}

