        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: drain-the-laggard — when this bin's residual sits well above
        // the fleet mean, filling it aggressively prevents a stranded large gap
        if post_residual > 0 && mean_residual > 0.0 && (post_residual as f64) > mean_residual * 1.6 && fill > 0.4 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) are worthless; residuals below a practical
    // threshold are near-worthless dead space.
    if post_residual == 0 {
        // Perfect fit: heavily reward closing the bin.
        score -= 1000.0;
    } else {
        // Penalize unusable dead space quadratically as it approaches
        // the smallest conceivable item size.
        let dead = (post_residual as f64).min(20.0);
        score += (20.0 - dead) * (20.0 - dead) * 0.8;
    }

    // Reward tight packing: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    score += pressure * 0.5;

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward leaving that room; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 15.0;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item (tight fit) rather than wildly larger.
    let tightness = (bin_residual as f64 - item_size as f64);
    score += tightness * 0.2;

    // New-bin candidate (empty bin): make it unattractive unless the item
    // fits poorly everywhere else — add a standing penalty that shrinks
    // with open-bin pressure.
    if bin_residual == bin_capacity {
        score += 45.0 + pressure * 2.0;
        // But if nothing else really fits well, allow opening: offset by
        // how large the item is (big items are hard to place later).
        score -= fill_ratio * 40.0;
    }

    // Mean-residual coupling: if open bins are already mostly empty,
    // reusing them is cheap; penalize placements that leave mean residual high.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

