        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // opening a new bin is only attractive for big items that pair with next
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 14.0;
        }
        // allow new bins for large items even without pairing, but only early/mid-stream
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
        // new-bin bonus scaled by pairing quality — if the leftover after this
        // item exactly matches the next item, opening a fresh bin is near-optimal
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 10.0;
            } else if leftover <= 4 {
                score -= 5.0;
            } else if leftover <= 8 && progress > 0.5 {
                // refined: mildly discourage new bins whose leftover is a loose
                // sliver above next_item — dead space in a fresh bin
                score += 4.0 * rem_frac;
            }
        }
        // refined: if the best open-bin residual would leave a near-dead sliver,
        // but a fresh bin could hold this item plus next exactly, prefer fresh
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size
            && bin_capacity - item_size - next_item_size <= 3
            && mean_residual > 6.0 && fitting_bins_count >= 1 {
            score -= 6.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // refined: when the post residual after this fit can exactly hold the
        // next item, weight the fit by fill ratio to break ties toward fuller bins
        if next_item_size > 0 && post_residual == next_item_size && fill > 0.4 {
            score -= 4.0 * (fill - 0.4) / 0.6;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (50.0 - slack.min(50.0)) * 0.5;
        } else {
            // next item can't fit here; penalize wasted residual
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize leaving dead space below the minimum item size (1..100 unknown; use 10 heuristic band)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Prefer filling already-open bins over opening new ones as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses and many bins open
        score += 120.0 + 300.0 * progress + 5.0 * open_bins_count as f64;
        // but allow new bin if current bin would leave very awkward residual
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.3 {
            score -= 100.0;
        }
    } else {
        score -= 30.0;
    }

    score
}

