pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty proportional to waste
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * (bin_residual - item_size) as f64 / bin_capacity as f64;
    }

    // New-bin candidate handling: opening a bin is attractive when existing
    // residuals are large and fragmented, less so when this bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over the stream as
        // fragmentation grows.
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        score = bin_capacity as f64 - 20.0 * fragmentation - 15.0 * t;
        // If next item is large, a fresh bin is a good hedge.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // If only one fitting bin exists, prefer using it over opening new.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    // Mild global pressure: spread load when many bins are open with high mean residual.
    if bin_residual != bin_capacity {
        score += 0.02 * (open_bins_count as f64) * (1.0 - mean_residual / bin_capacity as f64);
    }

    score
}

