        // item exactly matches the next item, opening a fresh bin is near-optimal
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 10.0;
            } else if leftover <= 4 {
                score -= 5.0;
            }
        }
        // mutation: new-bin scarcity gate — when few open bins can fit the current
        // item and the item is large, a fresh bin preserves the scarce residual space
        // of existing bins for the next (smaller) item
        if fitting_bins_count == 1 && item_frac > 0.6 && next_item_size > 0
            && (next_item_size as f64) < mean_residual.max(1.0) {
