pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling: post_residual weighted by stream progress.
    // Early on, keep flexibility (penalize tight fits mildly); later, reward tight fits strongly.
    score += 20.0 * norm_pr * (1.0 - progress) - 15.0 * norm_pr * norm_pr * progress;

    // Dead-space penalty: post_residual too small to fit typical future items
    let dead = (1.0 - (pr / 10.0)).max(0.0).min(1.0);
    score += 12.0 * dead * dead * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 8.0 * snug;
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild preference toward bins with below-average residual (conserves large-space bins)
    score += 0.1 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    score
}

