                score -= 5.0;
            }
        }
        // mutation: discourage new bins when the item is small and open bins are
        // still mostly empty — spreading small items wastes capacity
        if item_frac < 0.3 && frag > 0.2 && fitting_bins_count > 0 {
            score += 14.0 * rem_frac;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer consuming it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: exact-fill chain bonus — if post_residual equals next_item and the
        // item after that could also chain, push this fit even harder
        if next_item_size > 1 && post_residual == next_item_size && fill > 0.4 {
            score -= 6.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (multiples of 10 or small enough to be fillable by typical items).
    let harmonic_class = post_residual % 10;
    let class_bonus: f64 = match harmonic_class {
        0 => -12.0,                    // perfect harmonic alignment
        1 | 2 | 3 => 6.0,              // awkward slivers -> penalize
        4 | 5 | 6 => -2.0,             // moderately useful
        _ => 3.0,                      // 7..9: usable by mid-size items
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: dead-space bands
    let dead_band = post_residual / 25; // 0..4 bands
    score += match dead_band {
        0 => 8.0,                      // < 25 left: near-dead space
        1 => -6.0,                     // 25..49: good target zone
        2 => -3.0,                     // 50..74
        3 => -1.0,                     // 75..99
        _ => 0.0,
    };

    // Coupling with next_item_size: if the lookahead item fits exactly in
    // post_residual, strongly reward; if it cannot fit, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 10.0;
            score += (slack % 10) as f64 * 0.5;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins
    // are crowded or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score = bin_capacity as f64
            - 20.0 * item_frac
            + 10.0 * progress
            - 4.0 * crowd;
        if fitting_bins_count <= 1 {
            score += 25.0; // don't open new bin when a real option exists
        }
    }

    // Small global tiebreakers
    score += 0.01 * (item_size as f64 / bin_capacity as f64);
    score -= 0.05 * mean_residual / bin_capacity as f64;

    score
}

