        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // scarcity-aware tightness: when only one open bin fits, prefer consuming it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // near-perfect fills mid-stream
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 500.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact match with next item is the best outcome.
            if post_residual == next_item_size {
                score -= 400.0;
            } else {
                score -= 100.0;
                // Scale lookahead bonus by how snugly the next item fits.
                let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
                score -= 100.0 * snug;
            }
        } else {
            // Penalize creating residual the next item cannot use (dead space).
            score += 50.0;
            // Extra penalty proportional to how much dead space is created.
            score += 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins with below-average residual
    // (tight bins) so loose bins stay available for future items.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f).min(50.0) * 1.5;
    } else {
        score += (residual_f - mean_residual).min(50.0) * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well.
        score += 150.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is great if the next item is huge and current item
            // would waste a nearly full bin... keep mild pressure against it.
            score += 0.5 * item_size as f64;
        }
    }

    // Slight stream-progression pressure: later in the stream, prefer
    // compacting into existing bins rather than opening new ones.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 100.0 * progress;
        } else {
            score -= 20.0 * progress;
        }
    }

    // Mild preference to reduce number of open bins overall.
    score += 0.1 * open_bins_count as f64;

    score
}

