pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Penalize large dead space quadratically, modulated by progress
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly late in stream
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_item) * progress;

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 6.0 * (nxt / cap);
        }
    }

    // Mild penalty for proliferation of open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_pr).abs();

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are bad
    if bin_residual == bin_capacity {
        score = pr + 5.0 + 20.0 * (mean_residual / cap) * (1.0 - progress);
    }

    score
}

