            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: exact-multiple residual chase — if the post residual is an
        // exact multiple of the next item within the 2..=6 range, reward harder
        // at higher fill ratios to squeeze chains into fewer bins
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 {
            let k = post_residual / next_item_size;
            if k >= 2 && k <= 6 && fill > 0.7 {
                score -= (fill - 0.7) * 20.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall into?
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer division thresholds: dead-space classes
    // class 0: leftover <= 10 (near-perfect), class 1: <= 20, class 2: <= 33, class 3: <= 50, else big gap
    let class = if post_residual <= 10 { 0 } else if post_residual <= 20 { 1 } else if post_residual <= 33 { 2 } else if post_residual <= 50 { 3 } else { 4 };

    // Reward small leftovers strongly (nonlinear)
    let class_bonus = match class {
        0 => -60.0,
        1 => -35.0,
        2 => -15.0,
        3 => 5.0,
        _ => 0.0,
    };
    score += class_bonus;

    // Modulo arithmetic: leftover divisible into small chunks is reusable
    if post_residual > 0 {
        // leftover usable by common small sizes (mod 5 / mod 10 harmony)
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        }
    }

    // Coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here regardless; mild penalty scaled by wasted potential
            score += 8.0;
        }
    }

    // Last-chance bin: penalize skipping it (new bin would be opened)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current residuals are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin if the best existing leftover would be tiny but awkward
        // i.e. when mean residual is low (open bins nearly full) -> opening is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 20.0 * (1.0 - progress) - 0.3 * mean_residual;
        if post_residual >= item_size {
            // empty bin always fits; keep baseline moderate
            score += 5.0;
        }
    } else {
        // Slight preference for tighter existing bins beyond raw post_residual
        score -= 0.15 * mean_residual;
    }

    // Harmonic capacity-fraction alignment: reward when item fills bin to a "clean" fraction
    let used = bin_capacity - post_residual;
    let clean = |x: u32| x % 25 == 0 || x % 20 == 0;
    if clean(used) {
        score -= 10.0;
    }

    // Penalize creating leftover in the awkward 51..=70 dead zone (hard to reuse)
    if post_residual > 50 && post_residual <= 70 {
        score += 10.0;
    }

    score
}

