        // than the next item and small in absolute terms, penalize proportionally
        // to how much space is being stranded, scaled by remaining stream
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 25 {
            score += (25 - post_residual) as f64 * 0.3 * rem_frac;
        }
    }

    score
}

