                    score -= 8.0;
                }
            }
            // mutation: chain-depth bonus — residual that can absorb the next item
            // several times with zero slack is a perfect multi-step plan
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 5 && k <= 8 {
                    score -= 5.0 + 0.8 * k as f64;
