        // mutation: fresh-bin viability check — only open a new bin when the leftover
        // space is compatible with the observed mean residual scale, otherwise the
        // new bin will accumulate the same dead-space problem
        if next_item_size > 0 && fitting_bins_count > 0 && progress > 0.3 {
            let leftover = bin_capacity.saturating_sub(item_size);
            let lo = leftover as f64;
