        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: exact-drain preference — when the item nearly empties the bin,
        // give a stronger late-stream nudge so residual variance shrinks
        if post_residual > 0 && post_residual <= 3 && progress > 0.4 {
            score -= 7.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to host any plausible
    // future item are the worst outcome. Penalize sharply in the small gap zone.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: almost total waste of this residual space.
            score += 40.0 + 3.0 * (10 - post_residual) as f64;
        } else if post_residual < 20 {
            // Only very small items could fit here; heavy penalty.
            score += 25.0;
        } else if post_residual < 35 {
            // Moderately risky gap.
            score += 10.0;
        }
    } else {
        // Perfect fit: fully closes the bin. Strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to the item itself.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Exact match of post_residual to next item lookahead: excellent reuse.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap that can host the next item is valuable; scale by how snugly.
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 / (1.0 + slack);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing ones; few open bins -> new bin is cheaper.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure so it is chosen only
        // when open bins are few or the fit into them is bad.
        score += 20.0 + 2.5 * pressure;
    } else {
        // Existing bin gets mildly better as pressure grows.
        score -= 1.5 * pressure;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a laggard bin; consolidating into it is good.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Slight preference to act early in the stream (keeps options open later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

