        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: coverage-aware fill — reward placements whose post_residual can
        // still hold several future items (high coverage) even if fill is moderate
        if next_item_size > 1 && post_residual > 0 && fill > 0.4 {
            let cover = (post_residual / next_item_size) as f64 * (next_item_size as f64) / (post_residual as f64);
            if cover > 0.85 {
                score -= 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 18.0 * (1.0 - tightness / bin_capacity as f64);

    // Penalize dead space that no future item (>=10... but sizes unknown 1..100) can use.
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 6.0 * post_residual as f64 / 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item can't use this residual: slight penalty proportional to waste
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (favor empty bin slightly);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins open.
        score += 10.0 * progress + 0.3 * open_bins_count as f64;
    }

    // Prefer bins with residual above the mean (keep low-residual bins for small items),
    // unless this item is large.
    let diff = bin_residual as f64 - mean_residual;
    if item_size < 40 {
        score += 0.15 * diff;
    } else {
        score -= 0.10 * diff;
    }

    // Mild penalty for spreading across too many bins when a good fit exists.
    if open_bins_count > 4 && post_residual < 20 {
        score += 3.0;
    }

    score
}

