pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr * pr * (1.0 + progress) - 2.0 * pr * progress;
    score += 25.0 * poly;

    // Penalize dead space more as stream progresses
    score += 10.0 * pr * pr * progress;

    // Reward tight fits (small post_residual) with smooth falloff
    score -= 15.0 * (1.0 - pr) * (1.0 - pr);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (nxt / cap);
        } else {
            score += 6.0 * (1.0 - nxt / cap);
        }
    }

    // New-bin candidate: mild penalty so it loses to good fits, wins over bad fits
    if bin_residual == bin_capacity {
        score += 5.0 - 5.0 * progress;
    }

    // Smooth coupling with mean residual divergence
    score += 3.0 * (post - mean_residual) / cap;

    score
}

