pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Medium gaps (10..20) are risky: only fit future items <= gap, penalize moderately
    else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Reward bins whose residual matches the lookahead item exactly (set up next placement)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Penalize leaving a gap just below the next item (near-miss dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }
    // Reward leaving room for the next item when it fits
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current fit is poor or no good option exists
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        if poor_fit || (fitting_bins_count <= 1 && post_residual > 20) {
            score -= 80.0;
        } else {
            // discourage opening new bins when decent fits exist
            score += 150.0 + open_bins_count as f64 * -5.0;
        }
    }

    // Open-bin pressure: mildly prefer consolidating into fewer bins
    score += open_bins_count as f64 * 0.5;

    // Prefer tighter bins (small residual before placement) to keep big gaps open
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

