        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // scarcity-aware tightness — one fitting bin: consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // near-perfect band late: tight small residuals are valuable
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: which modulo classes of item sizes
    // can still be packed into post_residual? Small post_residual values that
    // fall on "nice" boundaries (multiples of common item sizes) are valuable.
    let cap = bin_capacity as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness;

    // Harmonic classes: post_residual divisible by 10 or 25 leaves reusable space
    // for typical item sizes (10..80 stream, but interface allows 1..100).
    let pr = post_residual as u32;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 3.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        if pr % 50 == 0 {
            score -= 2.0;
        }
        // Penalize residuals in "dead" classes: 1..9 range wastes space
        if pr < 10 {
            score += 5.0;
        }
    } else {
        // Perfect fit — best possible outcome.
        score -= 12.0;
    }

    // Lookahead coupling: does post_residual still fit next_item_size?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward keeping room for the next item, scaled by how well it fits.
            let slack = (pr - next_item_size) as f64;
            score -= 4.0 - 0.04 * slack;
        } else {
            // Penalize blocking the next item.
            score += 3.0;
        }
        // Harmonic pairing: item + next exactly filling a bin is ideal.
        if next_item_size == pr {
            score -= 6.0;
        }
        // Integer-division threshold: post_residual / next_item_size ratio classes
        let n = next_item_size.max(1) as f64;
        let ratio_class = ((pr as f64) / n).floor();
        if ratio_class >= 2.0 {
            score -= 2.0; // room for at least two more items of that size
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins have poor residuals (large mean_residual means space is spread
    // thin but fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // Opening a new bin costs ~1 bin; worth it only if existing residuals
        // are badly fragmented relative to item size.
        let poor_fit = (item_size as f64) > fragmentation * cap * 0.9;
        if poor_fit {
            score -= 2.0 + 4.0 * progress;
        } else {
            score += 4.0;
        }
    }

    // Mild penalty for proliferation of open bins.
    score += 0.15 * open_bins_count as f64;

    // Integer-division threshold on item_size classes: large items (>50) prefer
    // fresh space; small items (<20) should fill gaps.
    if item_size > 50 && bin_residual == bin_capacity {
        score -= 1.5;
    }
    if item_size < 20 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
