pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items >= 10 originally, but sizes 1..100 possible here), so penalize
    // post_residual that falls below the smallest plausible item footprint.
    let dead_threshold = 12.0_f64.min(next_item_size.max(1.0) as f64);
    let mut score = post;

    if post > 0.0 && post < dead_threshold {
        // Unusable sliver: heavy penalty proportional to wasted capacity.
        score += 60.0 * (dead_threshold - post) / dead_threshold;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading items into new bins,
    // encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual != bin_capacity {
        score -= 2.0 * open_pressure.min(20.0);
    } else {
        // New-bin candidate: base cost of opening a bin, reduced when existing
        // residuals are large and fragmented (mean residual high but unusable).
        let fragmentation = (mean_residual - post) / cap;
        score += 35.0 + 10.0 * (1.0 - progress) - 15.0 * fragmentation.max(0.0);
    }

    // Lookahead: if next item fits in the post-residual, reward leaving a useful gap.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += 0.05 * (post - mean_residual).max(-30.0).min(30.0);

    score
}

