        score -= 50.0 + (bin_capacity as f64 - next_post) * 0.5;
    }

    // Penalize leaving dead space that no plausible next item can use.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins could still absorb the item,
    // unless residuals across open bins are already tight (little usable space).
    if bin_residual == bin_capacity {
        let avg_usable = mean_residual;
        let pressure = (open_bins_count as f64).max(1.0);
