        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // opening a new bin is only attractive for big items that pair with next
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 14.0;
        }
        // allow new bins for large items even without pairing, but only early/mid-stream
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
        // new-bin bonus scaled by pairing quality — if the leftover after this
        // item exactly matches the next item, opening a fresh bin is near-optimal
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 10.0;
            } else if leftover <= 4 {
                score -= 5.0;
            }
        }
        // mutation: fresh-bin pairing depth — when the leftover after this item can
        // hold the next item twice (or thrice) exactly, a new bin seeds a tight chain
        if next_item_size > 1 && bin_capacity >= item_size + next_item_size * 2 {
            let leftover = bin_capacity - item_size - next_item_size * 2;
            if leftover == 0 {
                score -= 7.0;
            } else if leftover <= 3 {
                score -= 3.0;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: chain-divisibility refinement — when the post residual is an
        // exact multiple of the next item AND leaves zero waste, deepen the reward
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && fill > 0.4 {
            let k = post_residual / next_item_size;
            if k >= 2 && k <= 6 {
                score -= 2.0 * (7.0 - k as f64).min(4.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: post_residual that no future item (min size 1..)
    // can realistically use. Small residuals are fine; mid residuals waste.
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // nearly perfect fill
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0; // awkward dead zone
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many options, mildly prefer bins with less residual (best-fit bias)
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // Perfect chain: next item exactly fills the remainder
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else if next_item_size >= item_size {
            // Next item is large; keeping residual large may help it
            score += 0.02 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Time horizon: early in the stream, be conservative with bin count;
    // late in the stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Penalize opening new bins, more so when many bins are already open
    // and their mean residual is high (poor global packing).
    if bin_residual == bin_capacity {
        let global_waste = mean_residual * open_bins_count as f64;
        score += 30.0 + 0.01 * global_waste;
        // But if current bin fits poorly and next item is large, new bin is okay
        if next_item_size > 0 && post_residual < next_item_size && next_item_size > item_size {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: new bin is mandatory anyway
        }
    }

    // Mild preference for bins already below mean residual (balance-aware)
    score += 0.03 * (bin_residual as f64 - mean_residual).max(0.0);

    // Small penalty tied to open bin count to discourage bin proliferation
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
