}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tight_fit = (item_size as f64 / bin_residual.max(1) as f64).powi(2);
    let mut score = pr * (0.6 + 0.8 * progress * progress) - 25.0 * tight_fit * (0.3 + progress);

    // Penalize dead space (small unusable post residual) with smooth term
    if norm_pr > 0.0 {
        score += 8.0 * (-(norm_pr * 6.0)).exp() * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward leaving room for the next item smoothly
    let n = next_item_size as f64;
    if n > 0.0 {
        let fit_next = (n / (pr + 1.0)).min(1.0);
        score -= 10.0 * fit_next * (1.0 - fit_next) * 4.0 * (0.5 + 0.5 * progress);
    }

    // Mean residual context: penalize deviating far from mean residual
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: mild penalty so we prefer existing bins unless very poor fit
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
    }

    score += poly * 4.0;
    score
}

