        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // refinement: exact-fill bonus — consuming the entire residual is the
        // single best outcome; deepen the reward for perfect closures
        if post_residual == 0 {
            score -= 6.0 * (1.0 - progress);
        }
        // refinement: waste-band penalty — leaving a residual just below the
        // next item wastes nearly the whole gap; scale with closeness
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let ratio = post_residual as f64 / next_item_size as f64;
            if ratio > 0.7 {
                score += (ratio - 0.7) * 20.0 * rem_frac;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
