            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: consolidation pressure — when many bins compete, mildly favor
        // the emptiest fits so low-residual bins drain toward zero instead of
        // leaving many half-used bins.
        if fitting_bins_count > 4 && fill < 0.5 && post_residual > 0 {
            score += (0.5 - fill) * 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residuals that are too small
    // to be useful (unusable gaps), scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 20.0 + 10.0 * progress;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (2.0 + 2.0 * progress);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits (small but still-usable residual).
    if post_residual > 0 && post_residual <= 15 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover: penalize proportionally to wasted space.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new empty bin has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = 15.0 + 3.0 * open_bins_count as f64 + 10.0 * (mean_residual / bin_capacity as f64);
        score += pressure;
    } else {
        // Slight preference for bins below mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Prefer filling larger-residual bins when few bins are open (avoid fragmentation).
    if open_bins_count <= 2 {
        score -= (bin_residual as f64) * 0.05;
    }

    score
}

