            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // mutation: scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t2 = t * t;

    // Non-linear coupling: post_residual penalized more as stream progresses
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let progress_weight = 1.0 + 2.0 * t2 + t * t2;
    score += progress_weight * pr_norm * pr_norm * cap;

    // Reward tight fits (small post_residual) with smooth exponential-like polynomial
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize if next item cannot fit in post_residual (smooth quadratic)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            let gap = (ns - pr) / cap;
            score += 15.0 * gap * gap * cap;
        } else {
            let slack = (pr - ns) / cap;
            score -= 3.0 * slack * (1.0 - slack);
        }
    }

    // Last-chance bin bonus: only fitting bin, smooth in open_bins_count
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score -= 12.0 * scarcity;
    }

    // New-bin candidate: penalize mildly, more so early in the stream
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - t2);
    }

    // Mean residual divergence: prefer bins close to mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.5 * dev * dev / cap;

    score
}

