                }
            }
            // quint lookahead for tiny items — long chains of small pieces
            if next_item_size > 1 && next_item_size <= 20 && post_residual >= next_item_size * 5 {
                let quint = post_residual - next_item_size * 5;
                if quint == 0 {
                    score -= 20.0;
                } else if (quint as f64) < 0.02 * bin_capacity as f64 {
                    score -= 8.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
        }
    }

    // dead-space penalty: small leftovers unlikely to be reused
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    // residual exactly reusable-sized band
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if dead < 0.10 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 9.0 * rem_frac;
        }
        if next_item_size > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) < item_size {
            score += 4.0 * rem_frac;
        }
        // anti-dead-space mid-stream: residuals no item (<=100) can fully use
        if progress > 0.15 && post_residual > 100 {
            let unusable = post_residual - 100;
            score += unusable as f64 * 0.35 * rem_frac;
        }
        if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && slack < 5.0 {
                score -= 6.0 * rem_frac;
            }
        }
        // endgame tightness — late stream, avoid leaving any residual at all
        if progress > 0.95 && post_residual > 0 {
            score += post_residual as f64 * 0.5 * rem_frac;
        }
        // mid-stream dead-space ramp — penalize unusable residuals earlier and harder
        if progress > 0.35 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6 * rem_frac;
        }
        // unusable-gap ramp — residuals between next_item and next_item+small gap
        // are nearly dead; the sliver above next_item will rarely be reused
        if progress > 0.40 && next_item_size > 0 && post_residual > next_item_size {
            let sliver = post_residual - next_item_size;
            if sliver <= 6 {
                score += sliver as f64 * 1.1 * rem_frac;
            }
        }
        // mutation: dead-space curvature — residuals in the 15..40 band are the
        // hardest to reuse once the stream moves past small items; ramp a mild
        // penalty scaled by how far they exceed the next item's size
        if progress > 0.3 && post_residual >= 15 && post_residual <= 40 {
            let rel = if next_item_size > 0 && post_residual > next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                0.0
            };
            score += (3.0 + rel * 0.25) * rem_frac;
        }
        // mutation: mean-residual alignment — if this residual is far above the
        // mean residual of open bins, it is an outlier likely to stay dead
        if progress > 0.4 && next_item_size > 0 && post_residual as f64 > mean_residual * 1.8 && post_residual < next_item_size {
            score += 5.0 * rem_frac;
        }
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // opening a new bin is only attractive for big items that pair with next
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 14.0;
        }
        // allow new bins for large items even without pairing, but only early/mid-stream
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
        // new-bin bonus scaled by pairing quality — if the leftover after this
        // item exactly matches the next item, opening a fresh bin is near-optimal
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 12.0;
            } else if leftover <= 4 {
                score -= 6.0;
            }
        }
        // mutation: avoid opening fresh bins when open-bin alternatives are tight
        // (small slack fits) — a new bin here just fragments the layout
        if fitting_bins_count > 0 && next_item_size > 0 {
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if next_frac < 0.15 && progress > 0.5 {
                score += 7.0;
            }
        }
        // mutation: late-stream new-bin suppression — never open a bin in the
        // endgame unless the item alone nearly fills it
        if progress > 0.9 && item_frac < 0.9 {
            score += 10.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: zero-residual chase refinement — when the post-fit residual
        // is tiny (< 1/20 of capacity) and the next item could not use it anyway,
        // reward the fill slightly more to squeeze out the last bins
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score -= 5.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residuals divisible by 10 pair well
    // with the 10..80 item grid, so reward "clean" residual classes.
    let class = post_residual % 10;
    if class == 0 {
        score -= 8.0; // perfectly harmonized residual
    } else if class <= 3 {
        score -= 2.0;
    } else if class >= 8 {
        score += 4.0; // sliver residuals are near-dead space
    }

    // Integer-division thresholds: reward residuals that can host a
    // mid-size item (>= 20) after this placement.
    if post_residual / 10 >= 2 {
        score -= 3.0;
    }
    // Penalize residuals that can only host tiny items.
    if post_residual < 10 {
        score += 12.0; // dead space
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
            // modulo harmony between next item and residual
            if (post_residual % next_item_size.max(1)) < 5 {
                score -= 3.0;
            }
        } else {
            // next item cannot use this residual: leftover is more likely dead
            score += 3.0;
            if post_residual > 0 && next_item_size > post_residual {
                score += (post as f64 / 20.0).min(6.0);
            }
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin when the item
    // fits an existing bin decently, unless the item is huge (near-capacity)
    // and existing residuals are small.
    if bin_residual == bin_capacity {
        // fraction of capacity consumed by this first item
        let fill = item_size as f64 / cap;
        let mut new_bin_score = 30.0; // base reluctance to open a new bin
        // big items harmonize best in a fresh bin (avoid mixing)
        if item_size >= 60 {
            new_bin_score -= 25.0;
        }
        // if no bin can even come close (fitting count refers to open bins;
        // a fresh-bin call still gets fitting info of open bins)
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0;
        }
        // stream progression: late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 10.0;
        // many open bins with large mean residual: consolidate instead
        if mean_residual > fill * cap {
            new_bin_score += 5.0;
        }
        if open_bins_count == 0 {
            new_bin_score -= 100.0; // must open
        }
        score = score.min(new_bin_score) + new_bin_score.min(0.0).abs() * 0.0;
        score = new_bin_score + post * 0.1;
    }

    // Tight-fit reward: minimal waste placements are best.
    let waste = post;
    score -= (1.0 - waste / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    }

    let min_useful = if next_item_size > 0 { next_item_size.min(80).max(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + 3.0 * (min_useful - post_residual) as f64;
    }

    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // stronger gradient slack discount (from best heuristic)
            score -= 60.0 - (slack * 0.5).min(55.0);
            if slack < 14.0 {
                score -= (14.0 - slack) * 1.1;
            }
            if slack > 0.0 && slack < 7.0 {
                score -= 18.0;
            }
            if slack >= 20.0 && slack < 40.0 {
                score -= 8.0;
            }
            // pair lookahead
            let pair = next_item_size * 2;
            if post_residual >= pair {
                let pair_slack = post_residual - pair;
                if pair_slack == 0 {
                    score -= 45.0;
                } else if (pair_slack as f64) < 0.06 * bin_capacity as f64 {
                    score -= 22.0;
                }
            }
            // harmonic anticipation
            if next_item_size > 1 && post_residual % next_item_size == 0 {
                let k = post_residual / next_item_size;
                if k >= 2 && k <= 4 {
                    score -= 6.0 + k as f64;
                }
                if k >= 3 && k <= 6 {
                    score -= 10.0;
                }
            }
            // triple chain
            if next_item_size > 1 && post_residual >= next_item_size * 3 {
                let trip = post_residual - next_item_size * 3;
                if trip == 0 {
                    score -= 30.0;
                } else if (trip as f64) < 0.04 * bin_capacity as f64 {
                    score -= 14.0;
                }
            }
            // quad lookahead
            if next_item_size > 1 && post_residual >= next_item_size * 4 {
                let quad = post_residual - next_item_size * 4;
                if quad == 0 {
                    score -= 26.0;
                } else if (quad as f64) < 0.03 * bin_capacity as f64 {
                    score -= 11.0;
                }
            }
            // quint lookahead for small items
            if next_item_size > 1 && next_item_size <= 20 && post_residual >= next_item_size * 5 {
                let quint = post_residual - next_item_size * 5;
                if quint == 0 {
                    score -= 20.0;
                } else if (quint as f64) < 0.02 * bin_capacity as f64 {
                    score -= 8.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
        }
    }

    // reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // dead-space penalty
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if dead < 0.10 && next_item_size > 0 && post_residual < next_item_size {
            score += 9.0 * rem_frac;
        }
        if progress > 0.15 && post_residual > 100 {
            score += (post_residual - 100) as f64 * 0.35 * rem_frac;
        }
        if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && slack < 5.0 {
                score -= 6.0 * rem_frac;
            }
        }
        if progress > 0.95 && post_residual > 0 {
            score += post_residual as f64 * 0.5 * rem_frac;
        }
        // sliver above next item is nearly dead
        if progress > 0.45 && next_item_size > 0 && post_residual > next_item_size {
            let sliver = post_residual - next_item_size;
            if sliver <= 6 {
                score += sliver as f64 * 0.9 * rem_frac;
            }
        }
        // new: mid-stream dead-space ramp — unusable residuals before next item
        if progress > 0.35 && next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6 * rem_frac;
        }
        // new: residual too small for both current-lookahead and next item
        if next_item_size > 0 && post_residual < next_item_size && post_residual < item_size {
            score += 4.0 * rem_frac;
        }
    }

    // open-bin pressure
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // new-bin bonus scaled by pairing quality
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 14.0;
            } else if leftover <= 4 {
                score -= 7.0;
            }
        }
        // allow new bins for large items mid-stream
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
        // fallback base penalty for new bin
        score += 30.0 + mean_residual * 0.15;
    } else {
        score += (bin_residual - item_size) as f64 * 0.05;
        score -= (mean_residual - bin_residual as f64) * 0.05;

        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-aware tightness: single fitting bin, consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
