}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small nonzero gaps are nearly unusable.
        if post_residual <= 10 {
            score += 60.0;
        } else if post_residual < item_size {
            // Gap too small for any similar item — dead space.
            score += 25.0;
        }
        // Reward residuals that still fit typical future items.
        if post_residual >= 50 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins when open bins exist and fit.
        score += 150.0 * (open_bins_count as f64).min(5.0);
        // But if the item exactly fills a fresh bin, opening is great.
        if item_size == bin_capacity {
            score -= 2000.0;
        }
        // Late in the stream, fewer bins matter more; discourage new bins less.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * progress;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += 3.0 * open_bins_count as f64;

    // Prefer bins with residual close to item (tight fit) relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    score
}

