        // scarcity-aware tightness: single fitting bin, consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // combined: prefer deeper consumption when many bins compete and fill is high
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // guard against shallow fills leaving tiny unusable residuals
        if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 && next_item_size <= bin_capacity {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nxt;
        if diff == 0.0 {
            // Perfect fit for the next item: strongly favor this bin.
            score -= 60.0;
        } else if diff > 0.0 {
            // Next item fits after this one: mild reward, decaying with slack.
            score -= 25.0 * (nxt / pr).min(1.0);
        } else {
            // Next item won't fit: penalize proportionally to dead space created.
            score += 20.0 * (-diff / nxt).min(1.5);
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average (good fit),
    // penalize bins that are already unusually loose (wasted capacity).
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer filling nearly-full bins to consolidate waste.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill * fill;

    // New-bin candidate: make opening a fresh bin moderately costly unless
    // the item truly fits poorly everywhere (dead-space penalty dominates).
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
