pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tight_fit * tight_fit * bin_capacity as f64;

    // Penalize dead space that is too small for typical future items,
    // but reward residuals that could still host a medium item.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 40.0; // nearly unusable sliver
        } else if next_item_size > 0 && (next_item_size as f64) > dead {
            score += 0.35 * dead; // next item can't use this leftover
        } else if next_item_size > 0 {
            score -= 8.0; // lookahead item fits nicely here
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Brand-new bin candidate: open a new bin only when current bins
    // are crowded or the fit would be poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        let late_stream = step_index as f64 / (total_items.max(1) as f64);
        if poor_fit && crowding > 0.0 {
            score -= 12.0 + 6.0 * late_stream;
        }
        if next_item_size > item_size && next_item_size > 0 {
            score -= 5.0; // keep space for a bigger upcoming item
        }
        if crowding == 0.0 {
            score -= 100.0;
        }
        // Discard new-bin preference when an open bin fits perfectly.
        if post_residual == 0 {
            score += 60.0;
        }
    }

    // Global pressure: when mean residual across open bins is low,
    // prefer filling existing bins rather than fragmenting space.
    let pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 4.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Mild time horizon adaptation: early stream favors consolidation,
    // late stream favors tightness even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

