        }
        if fill > 0.9 && post_residual > 0 && pr < 0.08 * cap && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
    }

    // Late in stream: prefer closing bins tightly.
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += 12.0 * quad * (0.5 + progress) - 8.0 * cube * (1.0 - progress);

    // Penalize dead space relative to next item's needs
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.6 * gap / cap;
        if pr >= nxt && pr - nxt < 10.0 {
