        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // scarcity-aware tightness
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // tiny near-dead residual with multiple alternatives: prefer consuming it
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact fill: perfect placement, strongest reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residual too small for the lookahead item becomes waste.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        score += post_residual as f64 * (0.5 + 0.5 * (1.0 - progress));
    }

    // Harmonic class: residuals that are multiples of 10 tend to recombine with
    // future items drawn from a wide size range; reward these "clean" classes.
    let harmonic_class = post_residual % 10;
    if harmonic_class == 0 {
        score -= 5.0;
    } else if harmonic_class >= 7 {
        // Awkward sliver class: likely dead space.
        score += 3.0;
    }

    // Half-capacity class is highly reusable (pairs with anything <= 50).
    if post_residual == bin_capacity / 2 {
        score -= 8.0;
    }

    // New-bin candidate: by default less attractive than reusing an open bin.
    if is_new_bin {
        score += 30.0;
        // But if this bin is effectively the only option, open it eagerly.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // Late in the stream, avoid opening bins for small leftovers.
        if progress > 0.8 && item_size < 40 {
            score += 10.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance: use this bin or waste capacity on a new one.
        score -= 20.0;
    }

    // Reward bins that are already well-filled (keeps many tight bins, few loose).
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Lookahead coupling: if the next item still fits here, prefer leaving a
    // snug (but sufficient) remainder rather than a loose one.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size).min(20);
        score -= snug as f64 * 0.2;
    }

    // Slight pull toward the mean residual to consolidate loose capacity.
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

