        // mutation: fresh-bin attractiveness should also consider that a new bin
        // guarantees zero inherited fragmentation; when open bins are heavily
        // fragmented (high mean residual), a clean start is worth more
        if frag > 0.3 && item_frac > 0.5 && progress < 0.85 {
            score -= 7.0 * (frag - 0.3).min(0.3) / 0.3;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
