            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: near-exhaustion bonus — when the residual after placement is
        // tiny relative to the next item, this placement effectively seals the
        // bin; reward scaling with how close the bin is to full
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            let sealed = 1.0 - post_residual as f64 / next_item_size as f64;
            score -= sealed * 5.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items are wasted.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Tightness bonus: fraction of the residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Penalize large leftover gaps relative to capacity (encourage balanced packing).
    score += (post_residual as f64 / bin_capacity as f64) * 12.0;

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow opening a new bin when the current bin would leave a bad gap.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin only if placing here would strand a large residual
        // that cannot fit the next item, or if this bin is the last chance.
        let strands_next = next_item_size > 0 && (post_residual as u32) < next_item_size && (bin_residual as u32) >= next_item_size;
        if strands_next && post_residual < 20 {
            score -= 30.0;
        } else if fitting_bins_count <= 1 && post_residual < 15 {
            score -= 20.0;
        } else {
            // Default: prefer existing bins over opening new ones.
            score += 35.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening an extra bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mild pull toward bins with below-average residual (fill emptier bins less,
    // keep roomy bins usable) — invert: favor bins with residual close to item size.
    let target = mean_residual - item_size as f64;
    score += (post_residual as f64 - target).abs() * 0.05;

    score
}

