                score += sliver as f64 * 0.9 * rem_frac;
            }
        }
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        // new-bin pairing quality: fresh bin attractive when leftover pairs with next item
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 12.0;
            } else if leftover <= 4 {
                score -= 6.0;
            }
        }
        // allow new bins for large items mid-stream when alternatives exist
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.92 {
            score -= 22.0 * (fill - 0.92) / 0.08;
        } else if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // strong preference for near-exact fits when few bins can host next item
        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // scarcity-aware tightness: single fitting bin — consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // near-perfect band mid/late stream
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // low-fill gap penalty: residual barely above next item
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or closely) accommodates the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 800.0;
        } else if (post_residual as f64 - next).abs() <= 10.0 {
            score -= 300.0 - 20.0 * (post_residual as f64 - next).abs();
        }
        // Penalize leaving dead space the next item cannot use.
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 0.5 * (next - post_residual as f64);
        }
    } else {
        // Last item: only exact fits matter.
        if post_residual == 0 {
            score -= 500.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting a large residual bin on a small item.
    score += 0.2 * (item_size as f64 / bin_residual.max(1) as f64) * (bin_residual as f64);

    // New-bin candidate handling: make empty bins moderately attractive only when
    // no open bin fits well (post_residual small) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 60.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 40.0;
        }
    }

    // Stream progression: as the stream ends, tighten up and prefer filling
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 100.0 * progress;
    } else {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
