        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-aware tightness: single fitting bin, consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize large dead space that likely cannot host future items.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.10 {
            score -= 8.0 * (1.0 - dead * 10.0);
        } else {
            score += 6.0 * dead * dead;
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64 / bin_capacity as f64;
        score -= 5.0 + 10.0 * chain;
    } else if next_item_size > 0 {
        // Penalize leaving a gap just below the next item's size (worst case).
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 && gap <= 10.0 {
            score += 7.0 * (1.0 - gap / 10.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins with slack: discourage fragmenting across bins.
    if open_bins_count > 3 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.6 * spread;
        score += 0.3 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 > mean_residual;
        if bad_fit && fitting_bins_count > 0 {
            score += 20.0 + 10.0 * progress; // keep using existing bins when fits exist
        } else {
            score -= 4.0 * (1.0 - progress); // early stream: opening bins is cheap
        }
    }

    // Mild time-horizon modulation: late in stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * tightness;

    score
}

