        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // near-perfect fills mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_f / cap * 8.0).floor(); // 8 harmonic classes of residual

    // Penalize residuals that fall into "unusable" harmonic classes.
    // Class 0: perfect fit (heavily reward). Class 1: tiny sliver (penalize).
    match class as u32 {
        0 => { score -= 25.0; }
        1 => { score += 15.0; }
        2 => { score += 5.0; }
        3 => { score -= 3.0; }
        _ => {}
    }

    // Modular coupling: post_residual congruent classes mod small integers.
    // Residuals divisible by 10 pair well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 7 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Integer-division threshold: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // reward proportionally to how tightly next item nests
            let nest = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - nest / cap);
        } else {
            // next item cannot fit here; slight penalty if we waste the slot
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by stream progress and crowding.
        score = 45.0
            + 20.0 * (step_index as f64 / total_items.max(1) as f64)
            - 0.5 * open_bins_count as f64;
        // If mean residual is large, open bins are fragmented -> new bin attractive.
        score -= (mean_residual / cap).min(1.0) * 10.0;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    if open_bins_count > 4 {
        score -= 1.5 * (open_bins_count as f64).log2();
    }

    // Early stream: keep bins balanced, mild preference for tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_f / cap) * 5.0;

    score
}

