pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // matches the next item size exactly (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let diff = pr - nxt;
            score -= 200.0 / (1.0 + diff * 0.1);
        } else {
            // next item won't fit here; penalize dead space relative to next item
            score += (nxt - pr) * 1.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 2.0;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when item is small and stream is early/mid.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * (1.0 - progress) + item_size as f64 * 0.5;
    }

    // Mild penalty for leaving large awkward residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0;
    } else if post_residual >= 10 {
        score += post_residual as f64 * 0.05;
    }

    score
}

