        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early: mild quadratic; Late: strongly convex so tight fits win.
    let prog2 = progress * progress;
    let base = post * (1.0 + 2.5 * prog2 * post_norm + 1.5 * prog2);

    // Dead-space penalty: residuals too small to ever fit another item
    // (below the minimum size 1..100, use 10 as soft floor) get extra cost.
    let dead = if post < 10.0 { post * post * 0.05 } else { 0.0 };

    // Lookahead: reward leaving room for the next item (smooth Gaussian-like bump).
    let next = next_item_size as f64;
    let lookahead = if next > 0.0 {
        let d = post_norm - next / cap;
        -8.0 * (-(d * d) * 12.0).exp()
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count <= 1 { -12.0 } else { 0.0 };

    // Prefer filling fuller bins relative to the fleet mean residual.
    let mean_term = 0.15 * (mean_residual - post);

    // Mild penalty on many open bins to discourage spreading.
    let spread = 0.02 * open_bins_count as f64 * post_norm;

    base + dead + lookahead + last_chance + mean_term + spread
}

