    // Residuals divisible by 4 are "usable" slots for small items; reward them.
    let m4 = post_residual % 4;
    if m4 == 0 {
        score -= 3.0;
    } else if m4 == 2 {
        score += 1.0;
    } else {
        score += 2.5; // odd residuals are the worst dead space
    }

    // Integer-division tiers on post_residual: how many "size 10" slots fit
    let slots = post_residual / 10;
    score -= (slots as f64) * 1.5;

    // Perfect fit: near-zero post residual is ideal
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Coupling with the lookahead item: harmonic compatibility check.
    // If the next item can exactly fill the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly next item packs the remainder
            let tight = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - tight / cap_f);
        } else {
            // next item cannot use this residual at all -> penalize wasted space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large (leaves a clean harmonic residual) and existing bins are crowded.
    if bin_residual == bin_capacity {
        // base penalty so new bins are not opened frivolously
        score += 18.0;
        // large items leave large, reusable residuals -> discount
        let frac = (item_size as f64) / cap_f;
        score -= 22.0 * frac;
        // if existing bins are fairly full on average, new bin is reasonable
        score -= 0.05 * mean_residual;
        // many fitting bins => no reason to open a new one
        score += (fitting_bins_count.saturating_sub(1) as f64) * 6.0;
        // early in the stream, allow more bins (spread future flexibility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
    }

    // Tightness bonus: residual close to item size means snug fit
    let snug = (bin_residual as f64 - item_size as f64) / cap_f;
    score += 4.0 * snug * snug;

    // Mild pressure against hoarding many half-empty bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
