            score -= 22.0 * (fill - 0.92) / 0.08;
        } else if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // strong preference for near-exact fits when few bins can host the next item
        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // scarcity-aware tightness — with one fitting bin, consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // near-perfect band late stream
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize if the next item would be stranded by this placement.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Many open bins: prefer consolidating into bins with below-average residual
    // (tighter bins) to keep large residuals available.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
        // Mild pressure to close bins when many are open.
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be more conservative (favor new bins
    // for poor fits); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio < 0.5 {
        // Loose fit: early stream penalize, late stream tolerate.
        score += (1.0 - progress) * 30.0 * (1.0 - fit_ratio);
    } else {
        // Tight fit: reward more as stream progresses.
        score -= progress * 20.0 * fit_ratio;
    }

    // New-bin candidate baseline: make empty bins attractive only when the
    // item is large relative to capacity or fits are scarce.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score = 60.0 + 0.6 * item_size as f64 - 80.0 * scarcity - 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
