pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual (larger leftover = better packing, but scaled non-linearly)
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear penalty for mid-range dead space (wasted residual that few future items can use)
    let pr_norm = pr / cap;
    score += 8.0 * pr_norm * (1.0 - pr_norm) * (1.0 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - pr_norm).powi(3) * (0.5 + progress);

    // Lookahead: if next item fits into post-residual, strongly reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        } else {
            score += 3.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: this is the only fitting bin; avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins below mean residual (concentrate filling)
    score += 0.4 * (pr - mean_residual);

    // Mild preference for keeping number of open bins low early on
    score -= 0.3 * (1.0 - progress) / (1.0 + open_bins_count as f64);

    score
}

