        // mutation: new-bin lookahead vs. best open fit — if the leftover after
        // pairing this item with next is smaller than the typical open-bin
        // residual, a fresh bin wastes less total space
        if next_item_size > 0 && fitting_bins_count > 0 {
            let paired_leftover = bin_capacity.saturating_sub(item_size + next_item_size);
