pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Small residuals (< C/10) are near-dead; penalize less if item was large
    if frac < 0.1 {
        score -= 20.0; // tiny leftover is fine, almost perfect fit
    } else if frac < 0.25 {
        // awkward dead zone: leftover too small for most items (sizes >= 10... but unknown dist)
        score += 30.0;
    } else if frac < 0.5 {
        score += 10.0;
    } else {
        // large residual: bin stays useful, mild reward
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item still fits: reward proportionally
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize leaving medium dead space
        score += 15.0;
    }

    // Harmonic / modulo class of next_item_size relative to capacity
    if next_item_size > 0 {
        let half = next_item_size * 2 == bin_capacity;
        let quarter = next_item_size * 4 == bin_capacity;
        if half || quarter {
            // complementary sizes are valuable: prefer preserving bins that pair with them
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        // base penalty so new bins are used sparingly
        score += 150.0;
        // relax when many bins open but few fit (fragmentation) or stream early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 0.6;
        if crowded {
            score -= 120.0;
        }
        if open_bins_count == 0 {
            score -= 1000.0;
        }
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // late in stream, prefer consolidation
        if progress > 0.8 {
            score += 40.0;
        }
    }

    // Prefer fuller bins overall: tie-break with mean residual context
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Integer-division harmonic threshold on post_residual
    let class = post_residual / 10; // classes 0..10
    score += class as f64 * 2.0; // larger class = larger waste, monotone penalty

    score
}

