pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent — residual gets reused
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
            if post_residual == next_item_size {
                score -= 15.0; // exact 2-step chain
            }
        } else {
            // Next item won't fit here; residual likely dead space
            let dead = post_residual as f64;
            let gap = (next_item_size - post_residual) as f64;
            // penalize more when dead space is large and close to next item size (near-miss waste)
            score += 0.05 * dead;
            if gap < 20.0 {
                score += 6.0 * (1.0 - gap / 20.0); // near-miss penalty
            }
        }
    } else {
        // Last item: prefer exact fill, otherwise any bin is fine
        score -= 5.0 * tightness;
    }

    // Compare against mean residual across open bins
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 4.0 * (1.0 - rel); // better than average residual
        } else {
            score += 2.0 * (rel - 1.0).min(3.0); // worse than average
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    // Penalize new bin normally; relax when current bin fit is poor and lookahead mismatches.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0;
        let poor_fit = (post_residual as f64) > 40.0 && next_item_size > post_residual;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.1;
        if poor_fit && !early {
            // allow opening a new bin for a better long-term layout
            score -= 10.0;
        } else if early {
            score -= 5.0; // early stream: fresh bins are cheap
        }
        score += base_penalty;
    }

    // Mild preference to consolidate into fewer bins when many are open
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

