    let mut score = post_residual as f64;

    // Normalize residuals
    let cap = bin_capacity as f64;
    let pre_ratio = bin_residual as f64 / cap;
    let post_ratio = post_residual as f64 / cap;

    // Tight fit reward: prefer bins where the item fills a large fraction
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_frac * fill_frac;

    // Penalize large dead space, especially small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver is almost always dead space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / cap);
        } else {
            score += 10.0; // cannot host next item
        }
        // If next item is large, prefer leaving big contiguous space
        if next_item_size >= 50 {
            score += post_ratio * 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // More competing bins -> mild penalty for spreading too thin
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global residual pressure: if mean residual is low, conserve space in fuller bins
    let mean_ratio = mean_residual / cap;
    score += (pre_ratio - mean_ratio) * 12.0;

    // Time horizon: early in stream, be selective (penalize poor fits more);
    // late in stream, prioritize closing bins out (reward high fill)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.35 * (1.0 - progress);
    score -= 10.0 * progress * (1.0 - post_ratio);

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let desperation = (fitting_bins_count == 0) as i32 as f64
            + (mean_ratio < 0.15) as i32 as f64
            + (item_size as f64 / cap > 0.7) as i32 as f64;
        if desperation >= 1.5 {
            score -= 20.0; // open a fresh bin
        } else {
            score += 35.0; // prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
