    let norm_pr = pr / cap;

    // Base: prefer small post residual, but with non-linear diminishing penalty
    let mut score = pr - 18.0 * (norm_pr * std::f64::consts::PI).sin().abs();

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more (dead space is costlier)
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 10.0 * coupling;

    // Reward bins whose residual closely matches the lookahead item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * (-gap * gap * 12.0).exp() * (0.5 + progress);
    }

    // Penalize creating dead space below the minimum item scale (1..100 => small floor)
    let dead = (pr / 40.0).min(1.0);
    score += 6.0 * dead * dead * (0.3 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.3);
    }

    // New-bin candidate: prefer opening a new bin when it keeps residual large
    // and there is slack in the stream; penalize it when residuals are plentiful.
    if bin_residual == bin_capacity {
        let openness = mean_residual / cap;
        score = pr + 12.0 - 15.0 * (1.0 - progress) - 10.0 * (openness - 0.5).abs().min(0.5);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for filling fuller bins as open-bin count grows
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * norm_pr;

    score
}

