        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // scarcity-aware tightness: single fitting bin, consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // near-perfect band late stream
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the leftover: integer division into capacity deciles.
    // Small classes (near-full bins) are good; mid classes create dead space.
    let class = post_residual / 10;
    let class_bonus = match class {
        0 => 60.0,          // post_residual in 1..=9: tiny waste, excellent
        1 => 30.0,          // 10..=19: good
        2 => 10.0,          // 20..=29: acceptable
        3 => -5.0,          // 30..=39: mild dead space
        4 => -20.0,         // 40..=49: dead space
        5 => -30.0,         // 50..=59
        _ => -40.0,         // 60+: half-empty bin
    };
    score -= class_bonus;

    // Lookahead coupling: if the next item fits into the leftover, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic match: leftover class compatible with next item
        let tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 + 40.0 * (1.0 - tightness / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportionally to waste
        score += 8.0 + 0.15 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): should only win when all open fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // More open bins with residual => prefer reusing them
        score += 3.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is relatively cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If next item is large, a fresh bin is more attractive
        score -= 0.1 * next_item_size as f64;
    } else {
        // Existing bins: slight preference for tighter bins (less residual before placement)
        score += 0.05 * bin_residual as f64;
        // Deviation from mean residual: prefer bins below mean (tighter)
        score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Modulo harmonic texture: leftover congruence classes mod 10
    let m = post_residual % 10;
    if m == 0 {
        score -= 5.0; // round leftover, easier to reuse
    } else if m >= 7 {
        score += 3.0; // awkward leftover
    }

    score
}

