                if quint == 0 {
                    score -= 20.0;
                } else if (quint as f64) < 0.02 * bin_capacity as f64 {
                    score -= 8.0;
                }
            }
        } else {
            let waste = (next_item_size - post_residual) as f64;
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 30.0 + waste * 0.9 + waste * 0.4 * scarcity;
            let remaining = (total_items - step_index).max(1) as f64;
            if remaining > 200.0 {
                score += waste * 0.25;
            }
            if waste <= 4.0 && fitting_bins_count > 2 {
                score -= 8.0;
            }
            if waste <= 2.0 && fitting_bins_count == 1 {
                score -= 12.0;
            }
        }
    }

    // reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // dead-space penalty
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.2;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 3 {
        score -= 10.0;
    }

    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += dead * 40.0 * rem_frac;
        } else if dead < 0.28 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 * 0.6 {
            score += 6.0 * rem_frac;
        }
        if progress > 0.9 {
            score += post_residual as f64 * post_residual as f64 * 0.004;
        }
        if dead < 0.10 && next_item_size > 0 && post_residual < next_item_size {
            score += 9.0 * rem_frac;
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual < item_size {
            score += 4.0 * rem_frac;
        }
        // mid-stream dead-space ramp: penalize unusable residuals earlier
        if progress > 0.15 && post_residual > 100 {
            score += (post_residual - 100) as f64 * 0.35 * rem_frac;
        }
        if progress > 0.35 && next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6 * rem_frac;
        }
        if progress > 0.8 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && slack < 5.0 {
                score -= 6.0 * rem_frac;
            }
        }
        if progress > 0.95 && post_residual > 0 {
            score += post_residual as f64 * 0.5 * rem_frac;
        }
        // sliver above next item is nearly dead
        if progress > 0.45 && next_item_size > 0 && post_residual > next_item_size {
            let sliver = post_residual - next_item_size;
            if sliver <= 6 {
                score += sliver as f64 * 0.9 * rem_frac;
            }
        }
    }

    // open-bin pressure
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // new-bin bonus scaled by pairing quality
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 14.0;
            } else if leftover <= 4 {
                score -= 6.0;
            }
        }
        // allow new bins for large items mid-stream
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
        // fallback base penalty for new bin
        score += 30.0 + mean_residual * 0.15;
    } else {
        score += (bin_residual - item_size) as f64 * 0.05;
        score -= (mean_residual - bin_residual as f64) * 0.05;

        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && (post_residual as f64) < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-aware tightness: single fitting bin, consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // typical future items are "dead". Penalize them super-linearly.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small but not zero post_residual is fine if it's a
    // near-perfect fill); perfect fill is best.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    }

    // Penalize post_residual that cannot fit the lookahead item but could
    // have fit it before placement (wasted opportunity for k=2 pairing).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when bin count is high relative to progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / 10.0;
    score += pressure * (1.0 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to consolidate space.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: an empty bin should only win when the item is large
    // and no open bin is a decent fit. Penalize opening a new bin by default,
    // scaled by how many open bins already exist.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
        score -= 1000.0;
    }

    let min_useful = if next_item_size > 0 { next_item_size.min(80).max(10) } else { 10 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + 3.0 * (min_useful - post_residual) as f64;
