            }
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-aware tightness: single fitting bin, consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // near-perfect fill bonus
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // guard: low fill leaving tiny residual is wasteful
        if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves a new residual; penalize leftover dead space
            let next_post = post_residual - next_item_size;
            score += next_post as f64 * 0.5;
        } else {
            // next item does NOT fit in this bin's remainder: penalty grows with mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += mismatch * 0.3;
        }
    }

    // Compare post_residual against mean residual: leaving less than average is good (tight packing)
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it attractive only when existing fit is poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 150.0;
        // but if this bin is the only fitting bin, opening new is bad; handled above
        if fitting_bins_count <= 1 {
            score += 200.0; // discourage abandoning a lone fitting bin
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
        // if next item is large, a fresh bin is useful
        if next_item_size > bin_capacity / 2 {
            score -= 80.0;
        }
    }

    // Penalize tiny unusable leftovers relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let rem_frac = ((total_items - step_index).max(1) as f64 / (total_items.max(1) as f64)).min(1.0);

    if post_residual == 0 {
