            } else if leftover <= 4 {
                score -= 5.0;
            }
        }
        // mutation: triple-combination bonus — a fresh bin that fits this item plus
        // two copies of the next item exactly is a perfect triple; also reward the
        // near-perfect triple band
        if next_item_size > 1 && bin_capacity >= item_size + next_item_size * 2 {
            let leftover = bin_capacity - item_size - next_item_size * 2;
            if leftover == 0 {
                score -= 7.0;
            } else if leftover <= 3 {
                score -= 3.0;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
