            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: exact-fill scarcity escalation — when exactly one bin fits and
        // the fill is near-perfect, deepen the reward to force consolidation into
        // that bin rather than a loose spread
        if fitting_bins_count == 1 && fill > 0.8 && post_residual > 0 {
            score -= (fill - 0.8) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual relative to item size is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize leaving awkward small residuals (dead space) that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to wasted potential.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    // or there are no open bins at all.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0;
        let poor_fit_bonus = if fit_ratio < 0.5 { 0.0 } else { 25.0 };
        let no_bins_bonus = if open_bins_count == 0 { -40.0 } else { 0.0 };
        // Late in the stream, slightly discourage new bins to consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let late_penalty = 6.0 * progress;
        score += base_penalty + poor_fit_bonus + no_bins_bonus + late_penalty;
    }

    // Global state coupling: when mean residual is high, prefer bins below the mean
    // (drain fragmented bins); when low, prefer bins above the mean.
    let dev = bin_residual as f64 - mean_residual;
    score -= 2.5 * (dev / bin_capacity as f64);

    // Mild consolidation pressure: more open bins -> favor filling existing ones.
    score += 0.4 * open_bins_count as f64;

    score
}

