pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: raw post residual
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight packing (penalize residual quadratically);
    // late in the stream, residual waste matters less so damp it.
    let t = progress * 2.0 - 1.0; // map to [-1, 1]
    let damp = 0.5 - 0.35 * t + 0.15 * t * t; // smooth polynomial in progress
    score -= pr * (1.0 - damp) * 0.8; // reward low residual more early

    // Cubic dead-space term: tiny residuals are dead space, heavily penalize.
    let r_norm = pr / cap;
    score += 12.0 * r_norm * r_norm * r_norm * cap * 0.05;

    // Smoothly favor bins whose residual closely matches the item (near-exact fit)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 10.0 * (1.0 - 2.0 * fit_gap * fit_gap);

    // Lookahead: if next item fits in post_residual, reward this bin smoothly.
    if next_item_size > 0 {
        let slack = (pr - next_item_size as f64).abs();
        score -= 6.0 * (-slack / 30.0) * (1.0 + progress);
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Penalize bins far below mean residual (fragmented outlier bins), smoothly.
    score += 0.3 * (mean_residual - pr).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate: make it moderately attractive only when few bins fit
    // the item or post residual would be very small in existing bins.
    if bin_residual == bin_capacity {
        let new_bin_bonus = 8.0 - 10.0 * (fitting_bins_count as f64).min(4.0) / 4.0;
        score = cap - new_bin_bonus + 4.0 * progress;
    }

    score
}

