            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        // new-bin bonus scaled by pairing quality
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 14.0;
            } else if leftover <= 4 {
                score -= 6.0;
            }
        }
        // allow new bins for large items mid-stream when fit competition is high
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.92 {
            score -= 22.0 * (fill - 0.92) / 0.08;
        } else if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        // strong preference for near-exact fits when few bins can host the next item
        if fill > 0.75 && next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 6.0 * (fill - 0.75) / 0.25;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-weighted fill preference
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // scarcity-aware tightness — sole fitting bin should be consumed fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // penalize creating residual just below mean item size (likely dead space)
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.9 && post_residual < item_size && post_residual < next_item_size {
            score += 7.0 * rem_frac;
        }
        // near-perfect fills mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: multiples of 10 are "harmonic" (likely
    // reusable by common item sizes), odd/prime-ish leftovers are dead space.
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 40.0; // perfect fit is always great
    } else if class == 0 {
        score -= 12.0; // harmonic leftover, easy to fill later
    } else if class == 5 {
        score -= 5.0;  // half-harmonic
    } else if class <= 2 {
        score += 18.0; // tiny sliver -> dead space
    } else if class >= 8 {
        score += 8.0;  // nearly a full harmonic slot wasted
    }

    // Dead-space penalty grows as leftover becomes unusable for the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // leftover can't hold the next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // leftover can hold next item: reward, more so if it fits snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0;
            score -= slack * 0.15;
        }
    }

    // Integer-division thresholds: bins whose residual is in a "small item
    // friendly" band (residual / 10 >= 3) are more valuable to preserve.
    let residual_band = post_residual / 10;
    if residual_band >= 3 {
        score -= 4.0;
    } else if residual_band <= 1 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins
    // would leave very poor fits, otherwise discourage spreading out.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        if post_residual == bin_capacity {
            // default new-bin score: base residual minus a mild discount
            score -= 10.0 + 8.0 * (1.0 - progress);
        }
        // fewer open bins -> opening new is cheaper
        if open_bins_count < 3 {
            score -= 6.0;
        }
        // if mean residual is high, prefer existing bins over new ones
        score += mean_residual * 0.35;
    }

    // Waste fraction coupling: penalize bins wasting more than half capacity.
    if post_residual as f64 > bin_capacity as f64 * 0.5 && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
