        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: exact-chain finisher — leaving a residual that is an exact multiple
        // of the next item late in the stream guarantees zero-waste continuation
        if progress > 0.6 && next_item_size > 1 && post_residual > next_item_size
            && post_residual % next_item_size == 0 && post_residual <= next_item_size * 4 {
            score -= 6.0 * rem_frac;
