}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual gap is "dead" if the next item (or typical small item) cannot use it.
    if post_residual > 0 {
        let next_fits_gap = next_item_size > 0 && next_item_size <= post_residual;
        if !next_fits_gap {
            // Dead space penalty: smaller gaps that fit nothing are worse.
            let deadness = if post_residual < 10 {
                3.0
            } else {
                1.5
            };
            score += deadness * (post_residual as f64);
        } else {
            // Reward gaps that exactly or nearly fit the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Near-perfect fit reward.
    if post_residual > 0 && post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bins pressure: discourage spreading across many bins when few bins fit.
    if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it over opening a new bin.
        score -= 15.0;
    } else {
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when current bin would leave large dead space
    // and there is already bin pressure.
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline, penalize if open bins already exist and fit is fine.
        if fitting_bins_count > 0 {
            score += 20.0 + 2.0 * open_bins_count as f64;
        } else {
            score = 0.0;
        }
    }

    // Mild waste aversion relative to mean residual state.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Progress-aware tightening: later in stream, be greedier about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

