pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual) already favored.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward if next item exactly fills the post_residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            score -= 25.0; // perfect chain: next item fills this bin completely
        } else if next_item_size <= post_residual {
            // next item fits here too: good, but penalize leftover after that
            let post2 = post_residual as f64 - nr;
            score -= 10.0;
            score += post2 * 0.15;
        } else {
            // next item won't fit: dead space penalty scaled by gap
            let gap = (nr - post_residual as f64).min(nr);
            score += gap * 0.20;
        }
    }

    // Relative residual vs mean: avoid leaving residuals far above the fleet mean
    // (fragmentation) unless it's near zero (full bin is great).
    let pr = post_residual as f64;
    if pr > 0.0 {
        let dev = pr - mean_residual;
        if dev > 0.0 {
            score += dev * 0.10;
        }
    } else {
        score -= 15.0; // perfectly closed bin
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize it, but relax the penalty as the stream matures
    // and if the item is large relative to capacity (fresh space more valuable).
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        let mut penalty = 30.0;
        if large_item { penalty -= 10.0; }
        if progress > 0.5 { penalty -= 5.0; }
        if next_item_size > 0 && (next_item_size as u32) + item_size <= bin_capacity {
            // room for chaining in a fresh bin
            penalty -= 5.0;
        }
        score += penalty;
    }

    // Mild tie-break: prefer bins with smaller current residual when scores tie.
    score += bin_residual as f64 * 0.01;

    score
}

