pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize large post_residual, but with non-linear curvature
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Stream-progress coupling: later in the stream, tolerate residual waste less
    score *= 1.0 + 0.6 * progress * (1.0 - pr_norm);

    // Reward tight fits (small post_residual) with a smooth super-linear bonus
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize bins whose residual is far below the mean residual (poor integration)
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: favor leaving post_residual compatible with the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr >= nx) as i32 as f64;
        let gap = (pr - nx).abs();
        score += 0.4 * (1.0 - fit_next) * gap;
        score -= 0.2 * fit_next * (1.0 - gap / cap);
    }

    // Mild penalty on opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
