pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residuals that are "nice"
    // denominators for future items (multiples of 10/20) are favored.
    let post = post_residual as i64;
    let class = match post % 10 {
        0 => -8.0,   // perfect harmonic slot
        5 => -3.0,   // half-slot, still usable
        2 | 4 | 6 | 8 => 2.0, // awkward even class
        1 | 3 | 7 | 9 => 4.0, // prime-ish dead space
        _ => 0.0,
    };
    score += class;

    // Integer-division threshold: how many size-10 "quanta" remain.
    let quanta = post / 10;
    score -= quanta as f64 * 1.5;

    // Lookahead coupling: reward residuals that exactly (or nearly) fit next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // perfect lookahead fit
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 6.0;
            } else {
                score -= 3.0 - (slack % 10) as f64 * 0.2;
            }
        } else {
            // next item won't fit here; penalize more if leftover is tiny dead space
            if post_residual < 10 {
                score += 6.0;
            } else {
                score += (next_item_size - post_residual) as f64 * 0.05;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are nearly full on average.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let freshness = 1.0 - progress;
        // Prefer new bin when existing mean residual is small (bins are packed tight)
        let mean_pressure = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 25.0 - freshness * 15.0 - mean_pressure * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Slight preference to fill fuller bins (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Mild penalty for large absolute gap between post_residual and mean residual
    // (keeps residual distribution homogeneous for future harmonic matching).
    let gap = (post_residual as f64 - mean_residual).abs();
    score += gap * 0.05;

    // Small tie-break noise via deterministic coupling of step and post_residual.
    score += ((post_residual as usize).wrapping_mul(step_index.wrapping_add(1)) % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
