    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum plausible item are pure waste.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else if post_residual >= dead_threshold {
        // Usable leftover: mild reward proportional to how well it matches the next item.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 6 {
            score -= 25.0;
        }
    }

    // Penalize wasting a large residual on a small item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score += (1.0 - fill_ratio) * 30.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if the item barely fits anywhere else, a fresh bin is fine.
        if post_residual > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Favor using bins with above-average residual to balance load.
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; leftover likely dead.
        score += 8.0;
    }

    // Late-stream tightness: as the stream progresses, be more aggressive about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_ratio;

    score
}

