            score -= (fill - 0.5) * 14.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // mutation: extra reward for exact fills mid-stream
        if post_residual == 0 && fill > 0.9 && progress > 0.3 {
            score -= 6.0;
        }
        // mutation: penalize leaving residuals just below next_item late
        if progress > 0.6 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let match_val = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight lookahead match: strong reward when post_residual == next item size (perfect chain).
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Reward proportional to closeness of the fit for the next item.
            score -= 25.0 * (1.0 - match_val / (bin_capacity as f64));
        } else {
            // Next item can't fit here: penalize dead space that blocks the lookahead.
            score += 15.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
        // Extra penalty if post_residual is a small unusable sliver (< min plausible item 10).
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }
    }

    // Relative-to-mean coupling: prefer bins that are emptier than average when mean residual is large,
    // prefer filling bins that are tighter than average when mean residual is small.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize wasting a large bin on a small item (poor fit ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - fill_ratio) * 10.0;

    // Slight late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate: only attractive when no good fit exists (handled by above bonuses),
    // but give it a mild base penalty so it isn't chosen casually.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

