pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Perfect fit: strong reward (subtract heavily).
    if post_residual == 0 {
        score -= 60.0 + 40.0 * progress;
    } else {
        // Smoothly penalize unusable dead space: residual too small for any
        // plausible future item (items >= 1). Non-linear coupling with progress:
        // dead space becomes more costly as the stream advances.
        let dead = (pr / cap).powi(3); // cubic: only small residuals hurt a lot
        score += 80.0 * dead * (0.5 + progress);

        // Reward leaving room for the lookahead item (k=2 lookahead).
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt <= pr {
                let tight = 1.0 - ((pr - nxt) / cap).powi(2); // smooth tightness term
                score -= 25.0 * tight;
            } else {
                // Lookahead cannot fit here: mild penalty, stronger late in stream.
                score += 10.0 * (0.4 + progress);
            }
        }

        // Last-chance bin: strongly favor using it over opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 45.0 + 30.0 * progress;
        }

        // Penalize very empty open bins (wasteful placement), scaled by progress.
        let fill = 1.0 - pr / cap;
        score -= 12.0 * fill * fill * (0.3 + progress);

        // Coupling with mean residual: prefer bins near the mean residual
        // (balanced packing), smooth quadratic attraction.
        let dev = pr - mean_residual;
        score += 0.05 * dev * dev / cap;

        // Many open bins: encourage consolidation into existing bins.
        score += (open_bins_count as f64).ln() * 2.0 * (pr / cap);
    }

    // New-bin candidate: penalize opening a new bin unless existing options are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size as f64 > pr {
            score -= 15.0; // big lookahead favors fresh capacity
        }
    }

    score
}

