            let slack = (post_residual - next_item_size) as f64;
            if slack > 0.0 && slack < 5.0 {
                score -= 6.0 * rem_frac;
            }
        }
        // endgame tightness — late stream, avoid leaving any residual at all
        if progress > 0.95 && post_residual > 0 {
            score += post_residual as f64 * 0.5 * rem_frac;
        }
        // mid-stream dead-space ramp — penalize unusable residuals earlier and harder
        if progress > 0.35 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6 * rem_frac;
        }
        // mutation: unusable-gap ramp — residuals between next_item and next_item+small gap
        // are nearly dead; the sliver above next_item will rarely be reused
        if progress > 0.45 && next_item_size > 0 && post_residual > next_item_size {
            let sliver = post_residual - next_item_size;
            if sliver <= 6 {
                score += sliver as f64 * 0.9 * rem_frac;
            }
        }
        // mutation: dead-zone sharpness — residuals that are too small for the next
        // item but would be consumed by a typical (mean) residual-sized item are
        // partially recoverable; scale the penalty by how far below mean they sit
        if progress > 0.25 && next_item_size > 0 && (post_residual as u32) < next_item_size {
            let recoverable = (post_residual as f64 / mean_residual.max(1.0)).min(1.0);
            score += (next_item_size - post_residual) as f64 * 0.35 * (1.0 - recoverable) * rem_frac;
        }
    }

    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (fitting_bins_count as f64 - 1.0).min(3.0) * 4.0;
    }

    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        let remaining = (total_items - step_index).max(1) as f64;
        if frag < 0.18 && fitting_bins_count > 0 {
            score += 60.0;
        }
        if item_size as f64 >= bin_residual as f64 * 0.5 && frag > 0.25 {
            score += 25.0;
        }
        if remaining < 20.0 && fitting_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.6 && frag < 0.3 {
            score += 20.0;
        }
        if frag > 0.35 && next_item_size > 0 && next_item_size as f64 > mean_residual * 0.8 {
            score += 12.0;
        }
        if fitting_bins_count > 0 && frag < 0.35 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            if item_frac > 0.7 {
                score -= 18.0;
            }
        }
        if fitting_bins_count > 0 {
            let item_frac = item_size as f64 / bin_capacity as f64;
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            if item_frac > 0.45 && frag < 0.22 && next_frac > 0.35 {
                score += 14.0;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 && mean_residual >= next_item_size as f64 + 8.0 {
            score += 6.0;
        }
        if next_item_size > 0 && item_size > next_item_size && bin_capacity - item_size == next_item_size {
            score -= 20.0;
        }
        if remaining < 60.0 && fitting_bins_count >= 2 {
            score += 15.0;
        }
        // opening a new bin is only attractive for big items that pair with next
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 14.0;
        }
        // allow new bins for large items even without pairing, but only early/mid-stream
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.75 && progress < 0.7 && fitting_bins_count >= 2 {
            score -= 8.0;
        }
        // mutation: new-bin bonus scaled by pairing quality — if the leftover after this
        // item exactly matches the next item, opening a fresh bin is near-optimal
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover == 0 {
                score -= 10.0;
            } else if leftover <= 4 {
                score -= 5.0;
            }
        }
        // mutation: fresh-bin leftover viability — only open a new bin if its
        // post-item leftover exceeds the mean residual (i.e. is actually usable),
        // otherwise the fresh bin would strand more dead space than an open one
        if next_item_size > 0 && bin_capacity > item_size + next_item_size {
            let leftover = bin_capacity - item_size - next_item_size;
            if (leftover as f64) < mean_residual * 0.5 {
                score += (mean_residual * 0.5 - leftover as f64) * 0.8;
            }
        }
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        if fill > 0.85 {
            score -= 12.0 * (fill - 0.85) / 0.15;
        } else if fill < 0.3 && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 0.05 * bin_capacity as f64 && fitting_bins_count > 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size * 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && post_residual == next_item_size * 2 && fill > 0.5 {
            score -= 5.0;
        }
        if next_item_size > 1 && post_residual == next_item_size * 3 && fill > 0.6 {
            score -= 7.0;
        }
        if fill > 0.6 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0 * (fill - 0.6) / 0.4;
        }
        if fill < 0.5 && next_item_size > 0 {
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > 0.0 && gap < 4.0 {
                score += gap * 1.0;
            }
        }
        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // mutation: scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (1/8 granularity) and reward "usable" classes.
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as i32; // 0..7
    let class_bonus: [f64; 8] = [12.0, 9.0, 6.0, 3.0, -1.0, -3.0, -6.0, -10.0];
    score -= class_bonus[class.clamp(0, 7) as usize];

    // Exact-fit / near-zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Modulo harmony: if the residual is divisible into plausible item sizes
    // (common divisors of small item sizes), the leftover is more reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 5 == 0) {
        score -= 4.0;
    }
    // Dead space: residual too small for the minimum item size.
    if pr > 0 && pr < 5 {
        score += 20.0;
    }

    // Lookahead: strongly prefer bins whose post residual fits next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += 6.0;
        }
        // Perfect two-item packing: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave large dead space and the item is large.
    if bin_residual == bin_capacity {
        let waste_if_open = cap - item_size as f64;
        score = waste_if_open * 0.9;
        if next_item_size > 0 && waste_if_open >= next_item_size as f64 {
            score -= 5.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer filling bins below the mean residual (consolidate emptiness).
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
