pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // worst for post_residual ~1
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 150.0;
    }
    // Small residuals that can still host typical small items are fine.
    if post_residual >= 10 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // unless the fit is truly bad.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        score += 25.0 + 15.0 * (open_bins_count as f64).sqrt() + 30.0 * progress;
    } else {
        score -= 5.0 + (open_bins_count as f64) * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly (sets up a chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 40.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 20.0; // dead space relative to lookahead
        }
    }

    // Prefer bins whose residual is below the mean (tighter bins get packed first),
    // keeping fat bins available for larger future items.
    score += (post_residual as f64 - mean_residual) * 0.3;

    score
}

