        // 0.5 upward, weighted by scarcity of fitting alternatives
        if fill > 0.5 && post_residual > 0 {
            let w = 1.0 / (fitting_bins_count.max(1) as f64);
            score -= (fill - 0.5) * 8.0 * w;
        }
    }

