pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if the next item fits into post_residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 120.0 - (gap as f64).min(120.0);
        if gap == 0 {
            score -= 250.0; // perfect 2-step chain
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that the next item cannot use
        score += 60.0;
    }

    // Penalize creating small unusable residuals relative to mean residual.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.4 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = if next_item_size > 0 {
            (bin_capacity - item_size).saturating_sub(next_item_size)
        } else {
            bin_capacity - item_size
        };
        // Penalize new bin unless it promises a great 2-step packing.
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
        let _ = best_possible;
        // In late stream, discourage proliferation of bins with small residuals.
        if open_bins_count > 4 {
            score += 30.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Mild preference for filling fuller bins (smaller residual) more strongly as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

