    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward residuals that exactly accommodate the next item (perfect pairing).
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.5 * (-slack / 20.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // When many bins can fit the item, mild preference for fuller bins (best-fit bias).
    if fitting_bins_count > 1 {
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * (bin_residual as f64);
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    // (i.e., this call is the empty bin itself and post residual would be huge waste).
    if bin_residual == bin_capacity {
