        // a residual close to next_item_size — such bins promise near-perfect fills
        if next_item_size > 0 && mean_residual >= next_item_size as f64
            && mean_residual <= next_item_size as f64 + 6.0 && fitting_bins_count > 0 {
            score += 10.0;
