        if fill > 0.92 {
            score -= 10.0 * (fill - 0.92) / 0.08;
        }
        if fitting_bins_count <= 2 && fill > 0.7 {
            score -= 6.0 * (fill - 0.7) / 0.3;
        }
        // prefer leaving residual divisible by next item for chains
        if next_item_size > 1 && post_residual > 0 && post_residual % next_item_size == 0 && post_residual <= next_item_size * 5 {
            score -= 4.0;
        }
        // guard against opening bins when a decent fit exists
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // extra anti-fragmentation when many bins compete
        if fitting_bins_count > 3 && post_residual >= next_item_size && next_item_size > 0 {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        // reward near-perfect fills more aggressively mid-stream
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // mutation: exact-match residual bonus — an existing bin whose post-fill
        // residual equals next_item_size is a guaranteed zero-waste chain link
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 + 6.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space grows quadratically in post_residual
    let norm_post = post / cap;
    score += 0.5 * norm_post * norm_post * cap;

    // Stream-progress coupling: tighten bins more aggressively later in the stream
    score -= (1.0 - progress) * 0.3 * norm_post * cap;
    score += progress * 0.2 * post;

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 0.4 * tightness * post;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let room = (post - nxt).max(0.0);
        let miss = (nxt - post).max(0.0);
        score -= 0.5 * room / cap * cap * 0.1;
        score += 0.6 * miss;
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins) early, above later
    score += (0.3 - 0.6 * progress) * (mean_residual - post);

    // Penalize opening new bins when few items remain
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

