pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual (mod 10 buckets): dead space in "hard-to-fill" classes is worse
    let class = post_residual % 10;
    score += match class {
        0 => -60.0,               // residual is a multiple of 10, easy to refill
        1 | 9 => 25.0,            // nearly unusable slivers
        2 | 8 => 12.0,
        3 | 7 => 5.0,
        _ => 0.0,
    };

    // Integer-division threshold: large post_residual chunks are valuable
    let chunk = post_residual / 20; // 0..=5
    score -= chunk as f64 * 15.0;

    // Lookahead harmony: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // chain a perfect follow-up
        } else if next_item_size <= post_residual {
            score -= 40.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize leaving mid-range residuals
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bin would leave large awkward residual
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 150.0;
        // but if no open bin fits well (this item is big relative to residuals), allow it
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // early in stream, opening bins is cheap (need spread)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    } else if post_residual > 0 && post_residual < 10 {
        // creating tiny dead space in an open bin: mild penalty unless last chance
        score += 10.0;
    }

    // Prefer filling bins with low residuals overall (compact the set)
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Many open bins: encourage closing them out (prefer bins with small residual)
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
