    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item are "dead space" — penalize heavily.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += 12.0;
    } else {
        // Smooth penalty rising as residual shrinks toward unusability.
        let closeness = 1.0 - (post_residual as f64 - dead_threshold) / (bin_capacity as f64 - dead_threshold);
        score += 4.0 * closeness * closeness;
    }

    // Reward near-perfect fits (post_residual close to zero).
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: leftover likely becomes dead space.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (bin_residual == bin_capacity) gets post_residual = 100,
    // so subtract a bit there only when few bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin: base attractiveness decreases as open bins accumulate.
        score -= (3.0 - 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0))) * (1.0 - 0.5 * progress);
    } else {
        // Existing bins get a mild bonus proportional to how full they already are.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 2.0 * fullness;
    }

    // Prefer bins with below-average residual (tighter bins) to consolidate.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

