    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // exact 2-chain fit
        } else if post_residual >= next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
