pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for wasted space.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space that next item cannot use: mild penalty scaled by dead fraction.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.08 * dead;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins whose residual is close to the item (best-fit style).
    let fit_gap = (bin_residual - item_size) as f64;
    score += 0.10 * fit_gap;

    // Prefer fuller bins relative to the global mean residual.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, keep bins flexible (penalize very small residuals);
    // late in the stream, prioritize filling bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.5 {
        score += 0.10 * (post_residual as f64).sqrt();
    } else {
        score -= 5.0 * progress;
    }

    // Crowding: with many open bins, favor consolidating into existing ones.
    if open_bins_count > 2 {
        score -= 0.5 * (open_bins_count as f64).ln();
