        let open_cost = 15.0 - 0.3 * (open_bins_count.min(20) as f64);
        // If next item is large and would waste this bin's residual, discourage.
        let lookahead_penalty = if next_item_size > post_residual { 4.0 } else { 0.0 };
        score += open_cost + lookahead_penalty;
    }

    score
}

