        }
        if fitting_bins_count > 3 && next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 3.0 {
                score -= 7.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
            score -= 3.0 * rem_frac;
        }
        // scarcity-aware tightness: single fitting bin, consume it fully
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // guard: near-perfect fill with empty residual gets extra reward
        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: zero residual (perfect fit) -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class 2: residual too small for any item (dead space, min item size 1)
    if post_residual > 0 && post_residual < 5 {
        score -= 50.0; // small dead space is acceptable
    } else if post_residual >= 5 && post_residual < 20 {
        score += 60.0; // awkward dead zone
    }

    // Integer division thresholds on post_residual: quarters of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= quarter && post_residual < quarter + 10 {
        score += 25.0; // just-above-quarter is a poor class
    }
    if post_residual == half {
        score -= 40.0; // half residual is highly reusable
    }

    // Modulo arithmetic: residuals divisible by common item sizes are valuable.
    let div_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for d in [10u32, 20, 25, 50] {
            if r % d == 0 && r > 0 {
                b += 15.0;
            }
        }
        b
    };
    score -= div_bonus(post_residual);

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 80.0 * (1.0 - slack as f64 / cap);
            // harmonic class of slack
            if slack % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this residual at all: penalize larger residuals mildly
            score += 10.0 + pr / 20.0;
        }
    }

    // Last-chance bin logic: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: keep it available early, discourage later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 150.0 + 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: must open
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packing).
    score += (pr - mean_residual) * 0.5;

    // Slight preference for fewer open bins when stream nears the end.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    score
}

