pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best fit), with slight non-linearity
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: this bin's leftover fits next item exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // next item still fits, reward tighter
        } else {
            // next item cannot fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare post_residual to mean residual across open bins
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff; // prefer bins whose resulting residual is below average (tighter packing)

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize creating dead space smaller than the minimum plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // new empty bin: post_residual == capacity - item_size, quite large
        // penalize mildly so it loses to decent existing fits, but wins over bad fits
        score += 12.0;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative -> open new bin
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 5.0; // fresh bin can also absorb the next item
        }
    }

    // Late-stream consolidation: as stream progresses, favor closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty when many bins are open: encourage consolidation into existing bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

