        if fill > 0.95 && post_residual == 0 {
            score -= 5.0;
        }
        // tighten the near-perfect band — treat fill>0.9 as near-perfect late
        if fill > 0.9 && post_residual > 0 && (post_residual as f64) < 0.08 * bin_capacity as f64 && progress > 0.5 {
            score -= 4.0 * rem_frac;
        }
        // scarcity-aware tightness — when only one open bin fits, prefer
        // consuming it fully rather than spreading across many partial fits
        if fitting_bins_count == 1 && fill > 0.5 && post_residual > 0 {
            score -= (fill - 0.5) * 14.0;
        }
        // refined mutation: exact-fill lookahead in scarce fits — if consuming
        // this bin leaves exactly the next item's size, push hard toward it
        if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 * rem_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit: overwhelming bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that no future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // chained fit is fine, mild reward proportional to leftover usability
            score -= 8.0;
        } else {
            // this placement makes residual too small for next item: penalize
            // unless residual is large enough to be generally reusable
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is really bad.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current open bins are crowded or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        // base penalty so we prefer existing bins by default
        score += 20.0;
        // large items justify fresh bins more
        score -= 0.15 * item_size as f64;
        // late in the stream, fewer new bins
        score += 12.0 * progress;
        // if mean residual across bins is small, new bin is more attractive
        score -= 0.3 * mean_residual;
        // many open bins: discourage proliferation
        score += 2.0 * crowded * open_bins_count as f64;
        // if next item is large, a fresh bin is valuable
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer packing into
    // existing ones (penalize new bin implicitly, reward filling).
    if bin_residual != bin_capacity {
        score -= 0.05 * open_bins_count as f64;
    }

    // Slight preference for bins whose residual deviates below mean
    // (consolidate smaller leftovers).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

